open Globals
open Printf
open Rfc_ast

module SM = Map.Make (String)

let module_of_filename (fn: string) =
  let raw_module = Filename.remove_extension (Filename.basename fn) in
  String.concat "." (List.map String.capitalize_ascii (String.split_on_char '.' raw_module))

type parser_kind_metadata =
  | MetadataTotal
  | MetadataFail
  | MetadataDefault

(* Special case of select over a tag *)
type tag_select_t =
  attr list * attr list * typ * field * field * typ * (typ * typ) list * typ option

type ite_t =
  attr list * attr list * typ * typ * typ * int * string * typ * typ * (string option) * (string option)

let string_of_parser_kind_metadata = function
  | MetadataTotal -> "total"
  | MetadataFail -> "fail"
  | MetadataDefault -> "default"

type len_info = {
  mutable len_len: int;
  mutable min_len: int;
  mutable max_len: int;
  mutable min_count: int;
  mutable max_count: int;
  mutable vl : bool;
  mutable meta: parser_kind_metadata;
  mutable has_lserializer: bool;
}

(* Recording the boundaries of variable length structures *)
let linfo : len_info SM.t ref = ref SM.empty

(* Storage of enum fields for select *)
let fields: (enum_field_t list * bool) SM.t ref = ref SM.empty

(* Substitution map for global type rewriting *)
let subst: typ SM.t ref = ref SM.empty

(* Storage of types that require staged parsing (e.g. implicit tag) *)
let erased: unit SM.t ref = ref SM.empty

let w = fprintf
let wh x = if !emit_high then fprintf x else ifprintf x
let wl x = if !emit_low then fprintf x else ifprintf x
let wp x = if !emit_pulse then fprintf x else ifprintf x
(* [wnp] ("write non-pulse"): like [w] (emit on all channels) outside [-pulse],
   but a no-op under [-pulse]. Used for the SLow size32/LSZ machinery, which the
   Pulse backend never references (it uses the structural leaf_size library
   instead) and which must not leak into the extracted Pulse C. Outside [-pulse]
   it behaves exactly like [w], preserving the Low*/High output unchanged. *)
let wnp x = if !emit_pulse then ifprintf x else fprintf x
(* [ws] gates the SLow [size32] combinators. Under [-pulse] they are dropped
   entirely (the Pulse backend has no SLow dependency); outside [-pulse] the
   master behaviour is preserved: emit to all channels when a low-level
   serializer is available, otherwise High-only. *)
let ws has_lserializer x = if !emit_pulse then wh x else (if has_lserializer then w x else wh x)

(* Channel selector for definitions that a transparent Pulse [vmatch]/[lowtype]
   depends on. In [-pulse] mode (which is mutually exclusive with [-low], so the
   ".fst" is purely the Pulse implementation) such definitions must live in the
   interface so the transparent [let ..._vmatch]/[let ..._lowtype] typechecks
   there; [ipub i o] then selects the interface channel [i]. Outside [-pulse] it
   selects the implementation channel [o], leaving Low*/High output unchanged. *)
let ipub i o = if !emit_pulse then i else o

let write_autogen o =
  w o "(* This file has been automatically generated by EverParse. *)\n"

let log256 k =
  if k <= 255 then 1
  else if k <= 65535 then 2
  else if k <= 16777215 then 3
  else 4

let tname (lower:bool) (p:gemstone_t) : string =
  let n = match p with
    | Abstract (_, _, _, _, n) -> n
		| Enum (_, _, n) -> n
		| Struct (_, _, n) -> n
    | Typedef (_, _, n, _, _) -> n
	  in
  if lower then String.uncapitalize_ascii n else n

let str_last_chars str len =
  String.sub str (String.length str - len) len

let module_name (s:string) =
  if !prefix = "" || str_last_chars !prefix 1 = "." then
    !prefix ^ (String.capitalize_ascii s)
  else
    !prefix ^ (String.uncapitalize_ascii s)

let open_files n =
  let fn = sprintf "%s/%s.fst" !odir (module_name n) in
  printf "Writing parsers for type <%s> to <%s>...\n" n fn;
  try open_out fn, open_out (fn^"i")
  with _ -> failwith "Failed to create output file"

let open_files' p =
  let n = tname true p in
  match p with
  | Abstract _ ->
     let fn = sprintf "%s/%s.fst" !odir (module_name n) in
     printf "Writing interface for abstract type %s...\n" n;
     begin
       try
         let (dummy_in, dummy_out) = Unix.pipe () in
         Unix.out_channel_of_descr dummy_out, open_out (fn^"i")
       with _ -> failwith "Failed to create output file"
     end
  | _ -> open_files n

let close_files o i =
  close_out o; close_out i

let attr_of = function
  | Abstract (a, _, _, _, _) -> a
  | Enum (a, _, _) -> a
  | Struct (a, _, _) -> a
  | Typedef (a, _, _, _, _) -> a

let has_attr (a:attr list) (s:attr) = List.mem s a

let get_leninfo (t:typ) =
  try SM.find (String.uncapitalize_ascii t) !linfo
  with _ -> failwith ("Failed lookup for type "^t)

let li_add (s:string) (li:len_info) =
  printf "LINFO<%s>: vl=%s lenLen=%d minLen=%d maxLen=%d minCount=%d maxCount=%d meta=%s\n"
    s (if li.vl then "yes" else "no") li.len_len li.min_len li.max_len li.min_count li.max_count
    (string_of_parser_kind_metadata li.meta);
  if SM.mem s !linfo then failwith (sprintf "Duplicate type definition: %s\n" s);
  linfo := SM.add s li !linfo

let basic_type = function
  | "opaque" | "uint8" | "uint16" | "uint24" | "uint32" | "uint64"
  | "uint16_le" | "uint24_le" | "uint32_le" | "uint64_le"
  | "asn1_len" | "asn1_len8" | "bitcoin_varint"
  | "Empty" | "Fail" -> true
  | _ -> false

let basic_bounds = function
  | "uint8" -> 1, 1, Some 255
  | "uint16" | "uint16_le" -> 2, 2, Some 65535
  | "uint24" | "uint24_le" -> 3, 3, Some 16777215
  | "uint32" | "uint32_le" -> 4, 4, Some 4294967295
  | "uint64" | "uint64_le" -> 8, 8, None (* 18446744073709551615 *)
  | "asn1_len8" -> 1, 2, Some 255
  | "asn1_len" | "bitcoin_varint" -> 1, 5, Some 4294967295
  | s -> failwith (s^" is not a base type and can't be used as symbolic length")
       
let ends_with str suff =
  let str_len = String.length str in
  let suff_len = String.length suff in
  str_len >= suff_len &&
  String.sub str (str_len - suff_len) suff_len = suff

let rec sizeof = function
  | TypeIfeq(tag, v, _, t, _, f) ->
    let lit = sizeof (TypeSimple t) in
    let lif = sizeof (TypeSimple f) in
    {len_len = 0; min_len = min lit.min_len lif.min_len; max_len = max lit.max_len lif.max_len;
      has_lserializer = false; (* FIXME: should be "and" *)
      min_count = 0; max_count = 0; vl = lit.vl || lif.vl; meta =
      match lit.meta, lif.meta with
      | MetadataTotal, MetadataTotal -> MetadataTotal
      | MetadataFail, MetadataFail -> MetadataFail
      | _ -> MetadataDefault}
  | TypeSelect(n, cl, def) ->
    let lil = (List.map (fun (_,ty) -> sizeof (TypeSimple ty)) cl)
      @ (match def with None -> [] | Some ty -> [sizeof (TypeSimple ty)]) in
    let li = { len_len = 0; min_len = max_int; max_len = 0; min_count = 0; max_count = 0;
      has_lserializer = List.for_all (fun l -> l.has_lserializer) lil;
      vl = true; meta = MetadataTotal } in
    List.iter (fun l ->
      match l.meta with
      | MetadataFail -> (* Ignore size for the length boundaries *)
        if li.meta <> MetadataFail then li.meta <- MetadataDefault
      | md ->
        li.min_len <- min li.min_len l.min_len;
        li.max_len <- max li.max_len l.max_len;
        (if l.vl then
          (if li.len_len = 0 then li.len_len <- l.len_len;
          if l.len_len <> li.len_len then li.vl <- false)
        else li.vl <- false);
        if li.meta = MetadataFail || md = MetadataDefault then li.meta <- md
    ) lil;
    (* Propagating Fail outside of select() is not supported in LowParse *)
    if li.meta = MetadataFail then failwith (sprintf "Type select(%s) cannot parse any data" n);
    li
  | TypeSimple typ ->
    let not_is_le = not (ends_with typ "_le") in
    match typ with
    | "opaque"
    | "uint8"  -> { len_len = 0; min_len = 1; max_len = 1; min_count = 0; max_count = 0; vl = false; has_lserializer = true; meta = MetadataTotal }
    | "uint16" | "uint16_le" -> { len_len = 0; min_len = 2; max_len = 2; min_count = 0; max_count = 0; vl = false; has_lserializer = not_is_le; meta = MetadataTotal }
    | "uint24" | "uint24_le" -> { len_len = 0; min_len = 3; max_len = 3; min_count = 0; max_count = 0; vl = false; has_lserializer = not_is_le; meta = MetadataTotal }
    | "uint32" | "uint32_le" -> { len_len = 0; min_len = 4; max_len = 4; min_count = 0; max_count = 0; vl = false; has_lserializer = not_is_le; meta = MetadataTotal }
    | "uint64" | "uint64_le" -> { len_len = 0; min_len = 8; max_len = 8; min_count = 0; max_count = 0; vl = false; has_lserializer = not_is_le; meta = MetadataTotal }
    | "asn1_len8" -> { len_len = 0; min_len = 1; max_len = 2; min_count = 0; max_count = 0; vl = true; has_lserializer = false; meta = MetadataDefault }
    | "asn1_len"
    | "bitcoin_varint" -> { len_len = 0; min_len = 1; max_len = 5; min_count = 0; max_count = 0; vl = true; has_lserializer = true; meta = MetadataDefault }
    | "Empty" -> { len_len = 0; min_len = 0; max_len = 0; min_count = 0; max_count = 0; vl = false; has_lserializer = true; meta = MetadataTotal }
    | "Fail" -> { len_len = 0; min_len = 0; max_len = 0; min_count = 0; max_count = 0; vl = false; has_lserializer = true; meta = MetadataFail }
    | s ->
      let li = get_leninfo s in
      {li with len_len = li.len_len} (* shallow copy *)

let compile_type = function
  | "opaque"
  | "uint8" -> "U8.t"
  | "uint16" | "uint16_le" -> "U16.t"
  | "uint24" | "uint24_le" -> "(LPI.bounded_integer 3)"
  | "uint32" | "uint32_le" -> "U32.t"
  | "uint64" | "uint64_le" -> "U64.t"
  | (( "asn1_len8" | "asn1_len") as s) -> failwith (sprintf "compile_type: for now %s not standalone" s)
  | "bitcoin_varint" -> "U32.t"
  | "Empty" -> "unit"
  | "Fail" -> "(squash False)"
  | t -> String.uncapitalize_ascii t

(* for size headers with bounds *)

let has_bounded_length_parsers = function
  | "asn1_len8"
  | "asn1_len"
  | "bitcoin_varint" -> true
  | _ -> false

let size_of_bounded_length bound = function
  | "asn1_len8"
  | "asn1_len" ->
     if bound < 128
     then 1
     else 1 + log256 bound
  | "bitcoin_varint" ->
     if bound < 253
     then 1
     else if bound < 65536
     then 3
     else 5
  | _ -> failwith "not a has_bounded_length_parsers type"     

let make_combinator_length_header_name combino dup x min max =
  let typename = match x with
    | "asn1_len8"
    | "asn1_len" -> "bounded_der_length32"
    | "bitcoin_varint" -> "bounded_bcvli"
    | _ -> failwith (sprintf "make_combinator_length_header_name: %s not found" x)
  in
  let lengths = if dup then sprintf "%d %dul %d %dul" min min max max else sprintf "%d %d" min max in
  sprintf "(%s_%s %s)" combino typename lengths

let pcombinator_length_header_name = make_combinator_length_header_name "LPI.parse" false
let scombinator_length_header_name = make_combinator_length_header_name "LPI.serialize" false
let pcombinator32_length_header_name = make_combinator_length_header_name "LS.parse32" true
let scombinator32_length_header_name = make_combinator_length_header_name "LS.serialize32" false
let size32_length_header_name = make_combinator_length_header_name "LSZ.size32" false
let validator_length_header_name = make_combinator_length_header_name "LL.validate" true
let jumper_length_header_name = make_combinator_length_header_name "LL.jump" false
let reader_length_header_name = make_combinator_length_header_name "LL.read" false

(* Pulse length header helpers *)
let pulse_validator_length_header_name x min max = match x with
  | "asn1_len8" | "asn1_len" ->
    sprintf "(PPDER.validate_bounded_der_length32 %dul %dul (LPPI.read_u8' ()) (fun i -> if i = 1 then PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer 1) (PPBI.leaf_read_bounded_integer_1 ()) else if i = 2 then PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer 2) (PPBI.leaf_read_bounded_integer_2 ()) else if i = 3 then PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer 3) (PPBI.leaf_read_bounded_integer_3 ()) else PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer 4) (PPBI.leaf_read_bounded_integer_4 ())))" min max
  | "bitcoin_varint" ->
    sprintf "(PPBCVLI.validate_bounded_bcvli %dul %dul PPBI.leaf_read_bounded_integer_le_1 PPBI.leaf_read_bounded_integer_le_2 PPBI.leaf_read_bounded_integer_le_4)" min max
  | _ -> failwith (sprintf "pulse_validator_length_header_name: %s not found" x)

let pulse_reader_length_header_name x min max = match x with
  | "asn1_len8" | "asn1_len" ->
    sprintf "(PPDER.leaf_read_bounded_der_length32 %d %d (PPB.leaf_reader_of_serialized (LPPI.read_u8' ())) (PPBI.leaf_read_bounded_integer))" min max
  | "bitcoin_varint" ->
    sprintf "(PPBCVLI.leaf_read_bounded_bcvli %d %d PPBI.leaf_read_bounded_integer_le_1 PPBI.leaf_read_bounded_integer_le_2 PPBI.leaf_read_bounded_integer_le_4)" min max
  | _ -> failwith (sprintf "pulse_reader_length_header_name: %s not found" x)

let pulse_jumper_length_header_name x min max = match x with
  | "asn1_len8" | "asn1_len" ->
    sprintf "(PPDER.jump_bounded_der_length32 %d %d (PPB.leaf_reader_of_serialized (LPPI.read_u8' ())))" min max
  | "bitcoin_varint" ->
    sprintf "(PPBCVLI.jump_bounded_bcvli %d %d PPBI.leaf_read_bounded_integer_le_1)" min max
  | _ -> failwith (sprintf "pulse_jumper_length_header_name: %s not found" x)

(* Pulse l2r LEAF WRITER for a length header (used by copyful safe writers). *)
let pulse_leaf_writer_length_header_name x min max = match x with
  | "asn1_len8" | "asn1_len" ->
    sprintf "(PPDER.l2r_leaf_write_bounded_der_length32 %d %d)" min max
  | "bitcoin_varint" ->
    sprintf "(PPBCVLI.l2r_leaf_write_bounded_bcvli %d %d ())" min max
  | _ -> failwith (sprintf "pulse_leaf_writer_length_header_name: %s not found" x)

(* Pulse SIZE function for a length header (used by copyful safe writers/sizes),
   eta-expanded to avoid contravariant subtyping issues on the domain refinement. *)
let pulse_size_length_header_name x min max = match x with
  | "asn1_len8" | "asn1_len" ->
    sprintf "(fun x -> PPDER.bounded_der_length32_size %d %d x)" min max
  | "bitcoin_varint" ->
    sprintf "(fun x -> PPBCVLI.bounded_bcvli_size %d %d x)" min max
  | _ -> failwith (sprintf "pulse_size_length_header_name: %s not found" x)

(* Is a graceful copyful safe writer/size available for length-header type [x]? *)
let pulse_length_header_writable = function
  | "asn1_len8" | "asn1_len" | "bitcoin_varint" -> true
  | _ -> false

