    "uint16_le" |
      "uint24_le" |
      "uint32_le" |
      "uint64_le"
  ) as s
    -> failwith ("lscombinator_name: " ^ s ^ " not implemented")
  | "uint32" -> "LL.serialize32_u32"
  | "uint64" -> "LL.serialize32_u64"
  | "bitcoin_varint" -> "LL.serialize32_bcvli"
  | "Empty" -> "LL.serialize32_empty"
