let bytesize_call t x = match t with
  | "opaque" | "uint8" -> "1"
  | "uint16" | "uint16_le" -> "2"
  | "uint24" | "uint24_le" -> "3"
  | "uint32" | "uint32_le" -> "4"
  | "uint64" | "uint64_le" -> "8"
  | "asn1_len" -> sprintf "(if U32.v %s < 128 then 1 else if U32.v %s < 256 then 2 else if U32.v %s < 65536 then 3 else if U32.v %s < 16777216 then 4 else 5)" x x x x
  | "bitcoin_varint" -> sprintf "(if U32.v %s <= 252 then 1 else if U32.v %s <= 65535 then 3 else 5)" x x
  | "Empty" | "Fail" -> "0"
  | _ -> sprintf "(%s_bytesize (%s))" (String.uncapitalize_ascii t) x

let bytesize_eq_call t x = match t with
  | "opaque" | "uint8" -> sprintf "(assert (FStar.Seq.length (LP.serialize LP.serialize_u8 (%s)) == 1))" x
  | "uint16" | "uint16_le" -> sprintf "(assert (FStar.Seq.length (LP.serialize LP.serialize_u16 (%s)) == 2))" x
  | "uint24" | "uint24_le" -> sprintf "(assert (FStar.Seq.length (LP.serialize LP.serialize_u32 (%s)) == 4))" x
  | "uint32" | "uint32_le" -> sprintf "(assert (FStar.Seq.length (LP.serialize LP.serialize_u32 (%s)) == 4))" x
  | "uint64" | "uint64_le" -> sprintf "(assert (FStar.Seq.length (LP.serialize LP.serialize_u64 (%s)) == 8))" x
  | "asn1_len" -> sprintf "(LP.serialize_bounded_der_length32_size 0 4294967295 %s)" x
  | "bitcoin_varint" -> sprintf "(LP.serialize_bcvli_eq %s)" x
  | "Empty" -> sprintf "(assert (FStar.Seq.length (LP.serialize LP.serialize_empty (%s)) == 0))" x
  | "Fail" -> sprintf "(assert False)"
  | _ -> sprintf "(%s_bytesize_eq (%s))" (String.uncapitalize_ascii t) x

let leaf_reader_name = function
  | "opaque" | "uint8" -> "LL.read_u8"
  | "uint16" -> "LL.read_u16"
  | "uint16_le" -> "LL.read_u16_le"
  | "uint24" -> "(LL.read_bounded_integer_3 ())"
  | "uint24_le" -> "LL.read_bounded_integer_le_3"
  | "uint32" -> "LL.read_u32"
  | "uint32_le" -> "LL.read_u32_le"
  | "uint64" -> "LL.read_u64"
  | "uint64_le" -> "LL.read_u64_le"
  | "asn1_len" -> "(LL.read_bounded_der_length32 0 4294967295)"
  | "bitcoin_varint" -> "LL.read_bcvli"
  | "Empty" -> "LL.read_empty"
  | "Fail" -> "LL.read_false"
  | t -> sprintf "%s_reader" (String.uncapitalize_ascii t)

let leaf_writer_name = function
  | "opaque" | "uint8" -> "LL.write_u8"
  | "uint16" -> "LL.write_u16"
  | "uint16_le" -> "LL.write_u16_le"
  | "uint24" -> "(LL.write_bounded_integer_3 ())"
  | "uint24_le" -> "LL.write_bounded_integer_le_3"
  | "uint32" -> "LL.write_u32"
  | "uint32_le" -> "LL.write_u32_le"
  | "uint64" -> "LL.write_u64"
  | "uint64_le" -> "LL.write_u64_le"
  | "asn1_len" -> "(LL.write_bounded_der_length32 0 4294967295)"
  | "bitcoin_varint" -> "LL.write_bcvli"
  | _ -> failwith "leaf_writer_name: should only be called for enum repr"

(* Pulse/PulseParse name functions *)

let pulse_validator_name = function
  | "opaque" | "uint8" -> "LPPI.validate_u8"
  | "uint16" -> "LPPI.validate_u16"
  | "uint16_le" -> "PPBI.validate_u16_le"
  | "uint24" -> "(PPBI.validate_bounded_integer 3)"
  | "uint32" -> "LPPI.validate_u32"
  | "uint32_le" -> "PPBI.validate_u32_le"
  | "uint64" -> "LPPI.validate_u64"
  | "bitcoin_varint" -> "(PPBCVLI.validate_bcvli PPBI.leaf_read_bounded_integer_le_1 PPBI.leaf_read_bounded_integer_le_2 PPBI.leaf_read_bounded_integer_le_4)"
  | "Empty" -> "(LPS.validate_total_constant_size LP.parse_empty 0sz)"
  | "Fail" -> "(PPC.validate_false ())"
  | t -> String.uncapitalize_ascii t^"_validator"

let pulse_jumper_name = function
  | "opaque" | "uint8" -> "LPPI.jump_u8"
  | "uint16" -> "LPPI.jump_u16"
  | "uint16_le" -> "PPBI.jump_u16_le"
  | "uint24" -> "(LPS.jump_constant_size (LP.parse_bounded_integer 3) 3sz)"
  | "uint32" -> "LPPI.jump_u32"
  | "uint32_le" -> "PPBI.jump_u32_le"
  | "uint64" -> "LPPI.jump_u64"
  | "bitcoin_varint" -> "(PPBCVLI.jump_bcvli PPBI.leaf_read_bounded_integer_le_1)"
  | "Empty" -> "(LPS.jump_constant_size LP.parse_empty 0sz)"
  | "Fail" -> "(LPS.jump_constant_size LP.parse_false 0sz)"
  | t -> String.uncapitalize_ascii t^"_jumper"

let pulse_leaf_reader_name = function
  | "opaque" | "uint8" -> "(PPB.leaf_reader_of_serialized (LPPI.read_u8' ()))"
  | "uint16" -> "(PPB.leaf_reader_of_serialized (LPPI.read_u16' ()))"
  | "uint16_le" -> "PPBILE.read_u16_le"
  | "uint32" -> "(PPB.leaf_reader_of_serialized (LPPI.read_u32' ()))"
  | "uint32_le" -> "PPBILE.read_u32_le"
  | "uint64" -> "(PPB.leaf_reader_of_serialized (LPPI.read_u64' ()))"
  | "bitcoin_varint" -> "(PPBCVLI.leaf_read_bcvli PPBI.leaf_read_bounded_integer_le_1 PPBI.leaf_read_bounded_integer_le_2 PPBI.leaf_read_bounded_integer_le_4)"
  | "Empty" -> "PPC.leaf_read_empty"
  | "Fail" -> "(PPC.read_false ())"
  | t -> sprintf "%s_reader" (String.uncapitalize_ascii t)

let pulse_leaf_writer_name = function
  | "opaque" | "uint8" -> "(LPPI.l2r_leaf_write_u8 ())"
  | "uint16" -> "(LPPI.l2r_leaf_write_u16 ())"
  | "uint16_le" -> "LPPILE.l2r_leaf_write_u16_le"
  | "uint32" -> "(LPPI.l2r_leaf_write_u32 ())"
  | "uint32_le" -> "LPPILE.l2r_leaf_write_u32_le"
  | "uint64" -> "(LPPI.l2r_leaf_write_u64 ())"
  | "Empty" -> "LPC.l2r_leaf_write_empty"
  | "Fail" -> "(LPC.l2r_leaf_write_false ())"
  | t -> sprintf "%s_writer" (String.uncapitalize_ascii t)

(* The pure structural [leaf_size] (LowParse.Pulse.Base.leaf_size) expression for
   a base/leaf field type, parallel to [pulse_leaf_writer_name]. Constant-size
   leaves use [leaf_size_constant_size] (the kind-bound squash is discharged by a
   normalize+SMT tactic); [Empty]/[Fail] map to the dedicated combinators; user
   types resolve to their emitted [<ty>_leaf_size]. *)
let pulse_leaf_size_name =
  let cst s sz = sprintf "(LPS.leaf_size_constant_size %s %dsz (_ by (FStar.Tactics.norm [delta; iota; zeta; primops]; FStar.Tactics.smt ())))" s sz in
  function
  | "opaque" | "uint8" -> cst "LPI.serialize_u8" 1
  | "uint16" -> cst "LPI.serialize_u16" 2
  | "uint16_le" -> cst "LPI.serialize_u16_le" 2
  | "uint32" -> cst "LPI.serialize_u32" 4
  | "uint32_le" -> cst "LPI.serialize_u32_le" 4
  | "uint64" -> cst "LPI.serialize_u64" 8
  | "Empty" -> "LPC.leaf_size_empty"
  | "Fail" -> "(LPC.leaf_size_false ())"
  | t -> sprintf "%s_leaf_size" (String.uncapitalize_ascii t)


let assume_some = function
  | None -> failwith "assume_some"
  | Some x -> x

(* Under -pulse, ALL byte types are emitted Seq-natively (no FStar.Bytes): fixed
   and variable-length byte blobs, blobs with generic/variable-width length
   headers (asn1_len, asn1_len8, bitcoin_varint), and blobs with an oversized
   fixed-width header all go through the LowParse.Pulse.SeqBytes combinators (see
   compile_vlbytes and the Seq-native VectorRange branches in compile_typedef).
   Consequently no generated -pulse module references FStar.Bytes, so the
   FStar.Bytes module headers are emitted only outside -pulse. *)
let gemstone_uses_fstar_bytes_pulse (_p:gemstone_t) = false

(* Is [ty] a base/leaf type whose copyful parser is built from a leaf_reader
   (as opposed to a user-defined type that has its own read_<ty>/free_<ty>)? *)
let is_copyful_leaf_type = function
  | "opaque" | "uint8" | "uint16" | "uint16_le" | "uint24" | "uint24_le"
  | "uint32" | "uint32_le" | "uint64" | "uint64_le" | "bitcoin_varint"
  | "Empty" | "Fail" -> true
  | _ -> false

(* The low-level (LHS) representation type of a field type's copyful vmatch.
   Leaf types are represented by their high type; user types export a
   <ty>_lowtype abbreviation. *)
let copyful_lowtype_name ty =
  if is_copyful_leaf_type ty
  then compile_type ty
  else sprintf "%s_lowtype" (String.uncapitalize_ascii ty)

(* The vmatch slprop for a field type, used to build composite (pair/synth)
   vmatches. Leaf types use a pure equality (eq_as_slprop); user types refer to
   their generated <ty>_vmatch. *)
let copyful_vmatch_name ty =
  if is_copyful_leaf_type ty
  then sprintf "(LPS.eq_as_slprop %s)" (compile_type ty)
  else sprintf "%s_vmatch" (String.uncapitalize_ascii ty)

(* The copyful parser (PPB.copyful_parse) for a field type. *)
let copyful_read_name ty =
  if is_copyful_leaf_type ty
  then sprintf "(PPB.copyful_parse_leaf %s)" (pulse_leaf_reader_name ty)
  else sprintf "read_%s" (String.uncapitalize_ascii ty)

(* The free combinator (PPB.free_t) for a field type. *)
let copyful_free_name ty =
  if is_copyful_leaf_type ty
  then sprintf "(PPB.free_leaf #%s)" (compile_type ty)
  else sprintf "free_%s" (String.uncapitalize_ascii ty)

(* The refinement-free "mid" type used as the RHS of a field type's copyful
   vmatch. Leaf types use their (refinement-free) high type; user types export a
   <ty>_mid abbreviation. *)
let copyful_mid_name ty =
  if is_copyful_leaf_type ty
  then compile_type ty
  else sprintf "%s_mid" (String.uncapitalize_ascii ty)

(* The conv (<ty>_mid -> GTot (option <ty>)) for a field type. Leaf types use the
   total identity (mid = high), threaded as Some; user types refer to their
   generated <ty>_conv. *)
let copyful_conv_name ty =
  if is_copyful_leaf_type ty
  then sprintf "(PPB.leaf_conv %s)" (compile_type ty)
  else sprintf "%s_conv" (String.uncapitalize_ascii ty)

(* ----- Copyful safe writers (l2r_safe_writer / write_<n>) ----- *)

(* Is [ty] a base/leaf type that has a graceful leaf safe writer? This is a
   subset of [is_copyful_leaf_type]: it excludes the leaves (uint24/uint24_le,
   uint64_le, asn1_len) for which no [l2r_safe_writer_leaf]/[l2r_safe_writer_leaf_vl]
   is wired yet. Fixed-size leaves use [l2r_safe_writer_leaf]; bitcoin_varint is a
   variable-length leaf wired via [l2r_safe_writer_leaf_vl]. *)
let is_copyful_safe_leaf_type = function
  | "opaque" | "uint8" | "uint16" | "uint32" | "uint64" | "Empty" | "Fail" -> true
  | "uint16_le" | "uint32_le" -> true
  | "bitcoin_varint" -> true
  | _ -> false

(* The inline graceful leaf safe writer expression for a base safe-leaf type:
   (serializer, byte-size, low-level constant-size leaf writer). *)
let safe_leaf_writer_expr = function
  | "opaque" | "uint8" -> "(PPB.l2r_safe_writer_leaf LPI.serialize_u8 1sz (LPPI.l2r_leaf_write_u8 ()))"
  | "uint16" -> "(PPB.l2r_safe_writer_leaf LPI.serialize_u16 2sz (LPPI.l2r_leaf_write_u16 ()))"
  | "uint32" -> "(PPB.l2r_safe_writer_leaf LPI.serialize_u32 4sz (LPPI.l2r_leaf_write_u32 ()))"
  | "uint64" -> "(PPB.l2r_safe_writer_leaf LPI.serialize_u64 8sz (LPPI.l2r_leaf_write_u64 ()))"
  | "uint16_le" -> "(PPB.l2r_safe_writer_leaf LPI.serialize_u16_le 2sz LPPILE.l2r_leaf_write_u16_le)"
  | "uint32_le" -> "(PPB.l2r_safe_writer_leaf LPI.serialize_u32_le 4sz LPPILE.l2r_leaf_write_u32_le)"
  | "bitcoin_varint" -> "(PPB.l2r_safe_writer_leaf_vl LPI.serialize_bcvli PPBCVLI.bcvli_size (PPBCVLI.l2r_leaf_write_bcvli ()))"
  | "Empty" -> "(PPB.l2r_safe_writer_leaf LP.serialize_empty 0sz LPC.l2r_leaf_write_empty)"
  | "Fail" -> "(PPS.l2r_safe_writer_false (LPS.eq_as_slprop (squash False)) LP.serialize_false)"
  | t -> failwith (sprintf "safe_leaf_writer_expr: no safe leaf writer for %s" t)

(* Registry of user type names [n] for which a [write_<n>] was emitted. Populated
   in emission order (which follows the source/topological order, so a composite's
   field types are always processed first). A composite emits [write_<n>] only if
   every field type is writer-available, keeping the test gate green. *)
let copyful_writers : (string, unit) Hashtbl.t = Hashtbl.create 97
let register_writer n = Hashtbl.replace copyful_writers (String.uncapitalize_ascii n) ()
let writer_registered n = Hashtbl.mem copyful_writers (String.uncapitalize_ascii n)

(* Is a graceful [write_*] available for field type [ty]? *)
let copyful_writer_available ty =
  if is_copyful_leaf_type ty
  then is_copyful_safe_leaf_type ty
  else writer_registered ty

(* The graceful safe writer (PPB.l2r_safe_writer) for a field type. *)
let copyful_writer_name ty =
  if is_copyful_leaf_type ty
  then safe_leaf_writer_expr ty
  else sprintf "write_%s" (String.uncapitalize_ascii ty)

(* ----- Copyful safe SIZE combinators (l2r_safe_size / size_<n>) ----- *)

(* Is [ty] a base/leaf type with a CONSTANT-SIZE graceful leaf safe-size
   ([l2r_safe_size_leaf])? Same set as [is_copyful_safe_leaf_type] minus [Fail]
   (no [l2r_safe_size] for the vacuous false leaf). *)
let is_copyful_safe_size_leaf_type = function
  | "opaque" | "uint8" | "uint16" | "uint32" | "uint64" | "Empty" -> true
  | "uint16_le" | "uint32_le" -> true
  | "bitcoin_varint" -> true
  | _ -> false

(* The inline graceful leaf safe-size expression for a base safe-leaf type. *)
let safe_leaf_size_expr = function
  | "opaque" | "uint8" -> "(PPB.l2r_safe_size_leaf LPI.serialize_u8 1sz)"
  | "uint16" -> "(PPB.l2r_safe_size_leaf LPI.serialize_u16 2sz)"
  | "uint32" -> "(PPB.l2r_safe_size_leaf LPI.serialize_u32 4sz)"
  | "uint64" -> "(PPB.l2r_safe_size_leaf LPI.serialize_u64 8sz)"
  | "uint16_le" -> "(PPB.l2r_safe_size_leaf LPI.serialize_u16_le 2sz)"
  | "uint32_le" -> "(PPB.l2r_safe_size_leaf LPI.serialize_u32_le 4sz)"
  | "bitcoin_varint" -> "(PPB.l2r_safe_size_leaf_vl LPI.serialize_bcvli PPBCVLI.bcvli_size)"
  | "Empty" -> "(PPB.l2r_safe_size_leaf LP.serialize_empty 0sz)"
  | t -> failwith (sprintf "safe_leaf_size_expr: no safe leaf size for %s" t)

(* Registry of user type names [n] for which a [size_<n>] (l2r_safe_size) was
   emitted. Mirrors [copyful_writers]; populated in emission order. *)
let copyful_sizes : (string, unit) Hashtbl.t = Hashtbl.create 97
let register_size n = Hashtbl.replace copyful_sizes (String.uncapitalize_ascii n) ()
let size_registered n = Hashtbl.mem copyful_sizes (String.uncapitalize_ascii n)

(* Is a graceful [size_*] available for field type [ty]? *)
let copyful_size_available ty =
  if is_copyful_leaf_type ty
  then is_copyful_safe_size_leaf_type ty
  else size_registered ty

(* The graceful safe-size (PPB.l2r_safe_size) for a field type. *)
let copyful_size_name ty =
  if is_copyful_leaf_type ty
  then safe_leaf_size_expr ty
  else sprintf "size_%s" (String.uncapitalize_ascii ty)

(* Emit a copyful parser (read_<n>) and free combinator (free_<n>) for a leaf
   type that has a leaf_reader (e.g. enums). The vmatch is a pure equality. *)
let emit_copyful_leaf o i n =
  wp i "let %s_lowtype = %s\n\n" n n;
  wp i "noextract let %s_mid = %s\n\n" n n;
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop = LPS.eq_as_slprop %s\n\n" n n n n;
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) = fun x -> FStar.Pervasives.Native.Some x\n\n" n n n;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "let read_%s = PPB.copyful_parse_leaf %s_reader\n\n" n n;
  wp o "let free_%s = PPB.free_leaf\n\n" n

(* Emit the graceful copyful safe writer (write_<n>) for a CONSTANT-SIZE type
   [n] whose copyful vmatch is [eq_as_slprop] and conv is [leaf_conv] (i.e. that
   was emitted via [emit_copyful_leaf]: enums and fully leaf-readable constant-
   size sums), and which already has a non-graceful [<n>_writer : l2r_leaf_writer
   <n>_serializer]. [blen] is the constant serialized byte size. *)
let emit_copyful_safe_leaf_writer o i n blen =
  wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
  wp o "let write_%s = PPB.l2r_safe_writer_leaf %s_serializer %dsz %s_writer\n\n" n n blen n;
  register_writer n;
  wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
  wp o "let size_%s = PPB.l2r_safe_size_leaf %s_serializer %dsz\n\n" n n blen;
  register_size n

(* Emit the graceful copyful safe writer (write_<n>) and size (size_<n>) for a
   VARIABLE-SIZE leaf-readable type [n] whose copyful vmatch is [eq_as_slprop]
   and conv is [leaf_conv] (i.e. emitted via [emit_copyful_leaf], e.g. a
   leaf-readable sum), and which already has a non-graceful
   [<n>_writer : l2r_leaf_writer <n>_serializer] and an
   [<n>_size32 : LSZ.size32 <n>_serializer]. The exact serialized size is
   obtained from [<n>_size32] via [PPSL.leaf_size_of_size32] (the parser kind's
   [Some] high bound guarantees no saturation), and fed to the variable-length
   leaf writer/size combinators. Works for both constant- and variable-size
   leaf-readable types. *)
let emit_copyful_safe_leaf_writer_vl o i n =
  wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
  wp o "let write_%s = PPB.l2r_safe_writer_leaf_vl %s_serializer %s_leaf_size %s_writer\n\n" n n n n;
  register_writer n;
  wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
  wp o "let size_%s = PPB.l2r_safe_size_leaf_vl %s_serializer %s_leaf_size\n\n" n n n;
  register_size n

(* Emit a copyful parser (read_<n>) and free combinator (free_<n>) for a
   byte-array type. The result is a freshly allocated, freeable sized byte
   vector (PPBY.lvec, carrying a runtime length alongside the Pulse.Lib.Vec)
   related to the high-level value by PPBY.vmatch_copy_bytes. [combinator] is
   the copyful_parse_* expression producing the lvec. *)
let emit_copyful_bytes ?writer ?size o i n combinator conv =
  wp i "let %s_lowtype = PPBY.lvec FStar.UInt8.t\n\n" n;
  wp i "noextract let %s_mid = BY.bytes\n\n" n;
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop = PPBY.vmatch_copy_bytes\n\n" n n n;
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) = %s\n\n" n n n conv;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "let read_%s = %s\n\n" n combinator;
  wp o "let free_%s : PPB.free_t %s_vmatch = fun x #v -> PPBY.free_copy_bytes x #(Ghost.hide (Ghost.reveal v <: BY.bytes))\n\n" n n;
  (match writer with
   | Some w when !emit_pulse ->
     wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
     wp o "let write_%s = %s\n\n" n w;
     register_writer n
   | _ -> ());
  (match size with
   | Some s when !emit_pulse ->
     wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
     wp o "let size_%s = %s\n\n" n s;
     register_size n
   | _ -> ())

(* Seq-native analog of [emit_copyful_bytes]: emits the copyful tag block for an
  if-then-else discriminant whose high-level value is a plain [Seq.lseq byte
  clen] (NO FStar.Bytes), using the LowParse.Pulse.SeqBytes combinators. The
  freeable low representation [PPBY.lvec FStar.UInt8.t] is shared with the
  FStar.Bytes version; only the vmatch/conv and the read/free/write/size
  combinators are Seq-native. This is what lets the discriminant constant be
  built by a total [Seq.seq_of_list] (no [assume]). *)
let emit_copyful_seqbytes o i n clen =
  wp i "let %s_lowtype = PPBY.lvec FStar.UInt8.t\n\n" n;
  wp i "noextract let %s_mid = Seq.seq FStar.UInt8.t\n\n" n;
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop = LSeqB.vmatch_copy_seqbytes\n\n" n n n;
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) = LSeqB.seq_flbytes_conv %d\n\n" n n n clen;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "let read_%s = LSeqB.copyful_parse_seq_flbytes %d\n\n" n clen;
  wp o "let free_%s : PPB.free_t %s_vmatch = fun x #v -> LSeqB.free_copy_seqbytes x #(Ghost.hide (Ghost.reveal v <: Seq.seq FStar.UInt8.t))\n\n" n n;
  wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
  wp o "let write_%s = LSeqB.l2r_safe_writer_seq_flbytes %d %dsz\n\n" n clen clen;
  register_writer n;
  wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
  wp o "let size_%s = LSeqB.l2r_safe_size_seq_flbytes %d %dsz\n\n" n clen clen;
  register_size n

(* Seq-native analog of [emit_copyful_bytes] for VARIABLE-length byte types
   (bounded vlbytes). The high-level value is a plain [Seq.seq FStar.UInt8.t]
   refinement (NO FStar.Bytes); the freeable low representation [PPBY.lvec
   FStar.UInt8.t] is shared with the FStar.Bytes version. [combinator] is the
   copyful_parse_* expression and [conv] the option-conv, both from
   LowParse.Pulse.SeqBytes. *)
let emit_copyful_seqbytes_vl ?writer ?size o i n combinator conv =
  wp i "let %s_lowtype = PPBY.lvec FStar.UInt8.t\n\n" n;
  wp i "noextract let %s_mid = Seq.seq FStar.UInt8.t\n\n" n;
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop = LSeqB.vmatch_copy_seqbytes\n\n" n n n;
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) = %s\n\n" n n n conv;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "let read_%s = %s\n\n" n combinator;
  wp o "let free_%s : PPB.free_t %s_vmatch = fun x #v -> LSeqB.free_copy_seqbytes x #(Ghost.hide (Ghost.reveal v <: Seq.seq FStar.UInt8.t))\n\n" n n;
  (match writer with
   | Some w when !emit_pulse ->
     wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
     wp o "let write_%s = %s\n\n" n w;
     register_writer n
   | _ -> ());
  (match size with
   | Some s when !emit_pulse ->
     wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
     wp o "let size_%s = %s\n\n" n s;
     register_size n
   | _ -> ())

(* Render a hex string (2 chars per byte) as an F* byte-list literal, e.g.
  "0001ff" -> "0x00uy; 0x01uy; 0xffuy". Used to build the if-then-else
  discriminant constant via [Seq.seq_of_list] (total, no assume). *)
let hex_to_uy_list (cval: string) : string =
  let b = Buffer.create 64 in
  let nbytes = String.length cval / 2 in
  for j = 0 to nbytes - 1 do
   if j > 0 then Buffer.add_string b "; ";
   Buffer.add_string b (Printf.sprintf "0x%c%cuy" cval.[2*j] cval.[2*j+1])
  done;
  Buffer.contents b

(* Emit copyful parser (read_<n>) and free (free_<n>) for a closed sum (tagged
   union) whose payloads are not all leaf-readable: it builds a freshly
   allocated, freeable "owned" low representation [<n>_low] (an inductive type
   mirroring the high-level constructors, reusing each field type's own
   generated lowtype, and existing F* types only for leaves). The vmatch relates
   it to the high value via PPS.vmatch_sum + a per-case [<n>_casevmatch].
   [tn] is the tag enum type name, [cprefix] the constructor prefix, [cl] the
   (case, field-type) list (auto-completed for all enum keys). *)
let emit_copyful_owned_sum o i n tn cprefix cl =
  let ii = ipub i o in
  (* owned low representation (an inductive mirroring the high constructors).
     Emitted to the interface (under -pulse) so the transparent direct [vmatch]
     can reference its constructors there. *)
  wp ii "noeq type %s_low =\n" n;
  List.iter (fun (case, ty) -> wp ii "  | %s_%s_low of %s\n" cprefix case (copyful_lowtype_name ty)) cl;
  wp ii "\n";
  wp ii "let %s_lowtype = %s_low\n\n" n n;
  (* refinement-free "mid" inductive (interface), mirroring the constructors but
     carrying each field's refinement-free [<ty>_mid]. *)
  wp ii "noextract noeq type %s_mid =\n" n;
  List.iter (fun (case, ty) -> wp ii "  | %s_%s_mid of %s\n" cprefix case (copyful_mid_name ty)) cl;
  wp ii "\n";
  (* interface-side [enum_key]-typed tag discriminators on the low repr and the
     mid, used by the transparent direct vmatch. *)
  wp i "let %s_low_tag (xl: %s_low) : LP.enum_key %s_enum =\n  match xl with\n" n n tn;
  List.iter (fun (case, ty) -> wp i "  | %s_%s_low _ -> %s_as_enum_key %s\n" cprefix case tn (String.capitalize_ascii case)) cl;
  wp i "\n";
  wp i "noextract let %s_mid_tag (m: %s_mid) : LP.enum_key %s_enum =\n  match m with\n" n n tn;
  List.iter (fun (case, ty) -> wp i "  | %s_%s_mid _ -> %s_as_enum_key %s\n" cprefix case tn (String.capitalize_ascii case)) cl;
  wp i "\n";
  (* transparent direct vmatch (interface), defined by a textual match over the
     mid, with NO reference to [<n>_sum]/tactics. Each case relates the low repr
     to the field's own refinement-free mid via its bare [<ty>_vmatch]. *)
  wp i "let %s_vmatch (xl: %s_low) (m: %s_mid) : Pulse.Lib.Core.slprop =\n  Pulse.Lib.Core.op_Star_Star\n    (Pulse.Lib.Core.pure (%s_low_tag xl == %s_mid_tag m))\n    (match m with\n" n n n n n;
  List.iter (fun (case, ty) ->
    wp i "     | %s_%s_mid cm -> (match xl with | %s_%s_low v -> %s v cm | _ -> Pulse.Lib.Core.pure False)\n" cprefix case cprefix case (copyful_vmatch_name ty)
  ) cl;
  wp i "    )\n\n";
  (* transparent TIGHT conv (interface): a constructor's mid maps to the high
     value iff every field's conv succeeds. *)
  wp i "noextract let %s_conv (m: %s_mid) : GTot (FStar.Pervasives.Native.option %s) =\n  match m with\n" n n n;
  List.iter (fun (case, ty) ->
    wp i "  | %s_%s_mid cm -> (match %s cm with | FStar.Pervasives.Native.Some y -> FStar.Pervasives.Native.Some (%s_%s y) | FStar.Pervasives.Native.None -> FStar.Pervasives.Native.None)\n" cprefix case (copyful_conv_name ty) cprefix case
  ) cl;
  wp i "\n";
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  (* impl-side [sum_key]-typed tag discriminator (consumed by the sum machinery) *)
  wp o "inline_for_extraction\nlet %s_tag_of_low (xl: %s_low) : LP.sum_key %s_sum =\n  match xl with\n" n n n;
  List.iter (fun (case, ty) -> wp o "  | %s_%s_low _ -> %s_as_enum_key %s\n" cprefix case tn (String.capitalize_ascii case)) cl;
  wp o "\n";
  (* impl-side per-tag refinement-free mid family and per-tag conv. *)
  wp o "noextract let %s_mid_of_tag (k: LP.sum_key %s_sum) : Type0 =\n  match k with\n" n n;
  List.iter (fun (case, ty) ->
    wp o "  | %s -> %s\n" (String.capitalize_ascii case) (copyful_mid_name ty)
  ) cl;
  wp o "\n";
  wp o "noextract let %s_conv_of_tag (k: LP.sum_key %s_sum) : %s_mid_of_tag k -> GTot (FStar.Pervasives.Native.option (LP.sum_type_of_tag %s_sum k)) =\n  match k with\n" n n n n;
  List.iter (fun (case, ty) ->
    wp o "  | %s -> %s\n" (String.capitalize_ascii case) (copyful_conv_name ty)
  ) cl;
  wp o "\n";
  (* impl-side per-case vmatch (bare child vmatch over the per-tag mid) *)
  wp o "let %s_casevmatch (k: LP.sum_key %s_sum) (xl: %s_low) (cm: %s_mid_of_tag k) : Pulse.Lib.Core.slprop =\n  match k with\n" n n n n;
  List.iter (fun (case, ty) ->
    let cn = String.capitalize_ascii case in
    wp o "  | %s -> (match xl with | %s_%s_low v -> %s v cm | _ -> Pulse.Lib.Core.pure False)\n" cn cprefix case (copyful_vmatch_name ty)
  ) cl;
  wp o "\n";
  (* ghost maps between the library dependent-pair mid and the interface mid. *)
  wp o "let %s_fg (m: PPS.sum_mid %s_sum %s_mid_of_tag) : %s_mid =\n  match m with\n  | (| k, cm |) ->\n    (match k with\n" n n n n;
  List.iter (fun (case, ty) ->
    wp o "     | %s -> %s_%s_mid cm\n" (String.capitalize_ascii case) cprefix case
  ) cl;
  wp o "    )\n\n";
  wp o "let %s_gf (m: %s_mid) : PPS.sum_mid %s_sum %s_mid_of_tag =\n  match m with\n" n n n n;
  List.iter (fun (case, ty) ->
    wp o "  | %s_%s_mid cm -> (| %s_as_enum_key %s, cm |)\n" cprefix case tn (String.capitalize_ascii case)
  ) cl;
  wp o "\n";
  (* per-case copyful parsers (tight conv) *)
  wp o "inline_for_extraction\nlet copyful_%s_cases (k: LP.sum_key %s_sum)\n  : PPS.copyful_parse_sum_payload_t %s_sum parse_%s_cases %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag k =\n  match k with\n" n n n n n n n n n;
  List.iter (fun (case, ty) ->
    let cn = String.capitalize_ascii case in
    wp o "  | %s -> PPS.copyful_parse_sum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag %s\n      %s %s_%s_low () ()\n" cn n n n n n n cn (copyful_read_name ty) cprefix case
  ) cl;
  wp o "\n";
  (* copyful parser at the library dependent-pair mid, then bridged to the
     transparent interface mid/vmatch/conv via [copyful_parse_coerce_mid]. *)
  wp o "let read_%s_sum\n  : PPB.copyful_parse (PPS.vmatch_sum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch) %s_parser (PPS.sum_conv %s_sum %s_mid_of_tag %s_conv_of_tag) =\n  PPS.copyful_parse_sum %s_sum %s_repr_reader %s_repr_jumper parse_%s_cases\n    %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag copyful_%s_cases (_ by (LP.dep_enum_destr_tac ())) (_ by (LP.dep_maybe_enum_destr_t_tac ())) () ()\n\n" n n n n n n n n n n n tn tn n n n n n n n;
  wp o "let %s_coerce_vmatch_eq (xl: %s_low) (m1: PPS.sum_mid %s_sum %s_mid_of_tag)\n  : Lemma (PPS.vmatch_sum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch xl m1 == %s_vmatch xl (%s_fg m1))\n  = match m1 with\n  | (| k, cm |) ->\n    (match k with\n" n n n n n n n n n n n;
  List.iter (fun (kcase, kty) ->
    wp o "     | %s -> (match xl with\n" (String.capitalize_ascii kcase);
    List.iter (fun (xcase, xty) ->
      wp o "       | %s_%s_low vp -> assert (PPS.vmatch_sum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s_%s_low vp) (| %s, cm |) == %s_vmatch (%s_%s_low vp) (%s_fg (| %s, cm |))) by (FStar.Tactics.norm [delta; iota; zeta; primops]; FStar.Tactics.trefl ())\n"
        cprefix xcase n n n n n cprefix xcase (String.capitalize_ascii kcase) n cprefix xcase n (String.capitalize_ascii kcase)
    ) cl;
    wp o "      )\n"
  ) cl;
  wp o "    )\n\n";
  wp o "let %s_coerce_conv_eq (m1: PPS.sum_mid %s_sum %s_mid_of_tag)\n  : Lemma (%s_conv (%s_fg m1) == PPS.sum_conv %s_sum %s_mid_of_tag %s_conv_of_tag m1)\n  = match m1 with\n  | (| k, cm |) ->\n    (match k with\n" n n n n n n n n;
  List.iter (fun (kcase, kty) ->
    wp o "     | %s -> assert (%s_conv (%s_fg (| %s, cm |)) == PPS.sum_conv %s_sum %s_mid_of_tag %s_conv_of_tag (| %s, cm |)) by (FStar.Tactics.norm [delta; iota; zeta; primops; unascribe; nbe]; FStar.Tactics.trefl ())\n"
      (String.capitalize_ascii kcase) n n (String.capitalize_ascii kcase) n n n (String.capitalize_ascii kcase)
  ) cl;
  wp o "    )\n\n";
  wp o "let %s_coerce_eq ()\n  : Lemma (\n      (forall (xl: %s_low) (m1: PPS.sum_mid %s_sum %s_mid_of_tag) .\n        PPS.vmatch_sum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch xl m1 == %s_vmatch xl (%s_fg m1)) /\\\n      (forall (m1: PPS.sum_mid %s_sum %s_mid_of_tag) .\n        %s_conv (%s_fg m1) == PPS.sum_conv %s_sum %s_mid_of_tag %s_conv_of_tag m1)\n    )\n  = FStar.Classical.forall_intro_2 %s_coerce_vmatch_eq;\n    FStar.Classical.forall_intro %s_coerce_conv_eq\n\n" n n n n n n n n n n n n n n n n n n n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n  PPB.copyful_parse_coerce_mid read_%s_sum %s_vmatch %s_conv %s_fg (%s_coerce_eq ())\n\n" n n n n n n n n n;
  (* per-case free (bare child free over the per-tag mid) *)
  wp o "inline_for_extraction\nlet free_%s_cases (k: LP.sum_key %s_sum)\n  : PPB.free_t (%s_casevmatch k) =\n  match k with\n" n n n;
  List.iter (fun (case, ty) ->
    let cn = String.capitalize_ascii case in
    wp o "  | %s -> PPS.free_sum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s\n      %s (fun xl -> match xl with | %s_%s_low v -> Some v | _ -> None) ()\n" cn n n n n n cn (copyful_free_name ty) cprefix case
  ) cl;
  wp o "\n";
  (* free at the library mid, then bridged to the interface vmatch via
     [free_coerce_mid]. *)
  wp o "let free_%s_sum : PPB.free_t (PPS.vmatch_sum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch) =\n  PPS.free_sum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch free_%s_cases (_ by (LP.dep_enum_destr_tac ()))\n\n" n n n n n n n n n n n n;
  wp o "let %s_free_vmatch_eq (xl: %s_low) (m: %s_mid)\n  : Lemma (%s_vmatch xl m == PPS.vmatch_sum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch xl (%s_gf m))\n  = match m with\n" n n n n n n n n n n;
  List.iter (fun (mcase, mty) ->
    wp o "  | %s_%s_mid cm -> (match xl with\n" cprefix mcase;
    List.iter (fun (xcase, xty) ->
      wp o "    | %s_%s_low vp -> assert (%s_vmatch (%s_%s_low vp) (%s_%s_mid cm) == PPS.vmatch_sum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s_%s_low vp) (%s_gf (%s_%s_mid cm))) by (FStar.Tactics.norm [delta; iota; zeta; primops]; FStar.Tactics.trefl ())\n"
        cprefix xcase n cprefix xcase cprefix mcase n n n n n cprefix xcase n cprefix mcase
    ) cl;
    wp o "    )\n"
  ) cl;
  wp o "\n";
  wp o "let free_%s : PPB.free_t %s_vmatch =\n  PPB.free_coerce_mid free_%s_sum %s_vmatch %s_gf (FStar.Classical.forall_intro_2 %s_free_vmatch_eq)\n\n" n n n n n n;
  (* Graceful safe writer (write_<n>), emitted only if every case field type has
     an available writer. Mirrors read_<n>: build at the library sum mid via
     PPS.l2r_safe_writer_sum, then re-index to the transparent interface
     mid/vmatch/conv with PPB.l2r_safe_writer_coerce_mid (gf direction). *)
  if !emit_pulse && List.for_all (fun (_, ty) -> copyful_writer_available ty) cl then begin
    let tagsz = (get_leninfo tn).min_len in
    (* per-case safe writers (tight conv) *)
    wp o "inline_for_extraction\nlet write_%s_cases (k: LP.sum_key %s_sum)\n  : PPS.l2r_safe_writer_sum_payload_t %s_sum parse_%s_cases serialize_%s_cases %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag k =\n  match k with\n" n n n n n n n n n n;
    List.iter (fun (case, ty) ->
      let cn = String.capitalize_ascii case in
      wp o "  | %s -> PPS.l2r_safe_writer_sum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag %s\n      %s (fun xl -> match xl with | %s_%s_low v -> Some v | _ -> None) ()\n" cn n n n n n n cn (copyful_writer_name ty) cprefix case
    ) cl;
    wp o "\n";
    (* safe writer at the library dependent-pair mid *)
    wp o "let write_%s_sum\n  : PPB.l2r_safe_writer (PPS.vmatch_sum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch) (LP.serialize_sum %s_sum %s_repr_serializer serialize_%s_cases) (PPS.sum_conv %s_sum %s_mid_of_tag %s_conv_of_tag) =\n  PPS.l2r_safe_writer_sum %s_sum %s_repr_serializer write_%s_key %dsz parse_%s_cases serialize_%s_cases\n    %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag write_%s_cases (_ by (LP.dep_enum_destr_tac ())) ()\n\n" n n n n n n n tn n n n n n tn tn tagsz n n n n n n n n;
    (* conv bridge in the gf direction (mirrors <n>_free_vmatch_eq for vmatch). *)
    wp o "let %s_write_conv_eq (m: %s_mid)\n  : Lemma (%s_conv m == PPS.sum_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_gf m))\n  = match m with\n" n n n n n n n;
    List.iter (fun (mcase, _) ->
      wp o "  | %s_%s_mid cm -> assert (%s_conv (%s_%s_mid cm) == PPS.sum_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_gf (%s_%s_mid cm))) by (FStar.Tactics.norm [delta; iota; zeta; primops; unascribe; nbe]; FStar.Tactics.trefl ())\n"
        cprefix mcase n cprefix mcase n n n n cprefix mcase
    ) cl;
    wp o "\n";
    wp o "let %s_write_coerce_eq ()\n  : Lemma (\n      (forall (x: %s_low) (m2: %s_mid) . %s_vmatch x m2 == PPS.vmatch_sum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch x (%s_gf m2)) /\\\n      (forall (m2: %s_mid) . %s_conv m2 == PPS.sum_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_gf m2))\n    )\n  = FStar.Classical.forall_intro_2 %s_free_vmatch_eq;\n    FStar.Classical.forall_intro %s_write_conv_eq\n\n" n n n n n n n n n n n n n n n n n n;
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n  PPB.l2r_safe_writer_coerce_mid write_%s_sum %s_vmatch %s_conv %s_gf (%s_write_coerce_eq ())\n\n" n n n n n n n n n;
    register_writer n
  end

(* Emit copyful parser (read_<n>) and free (free_<n>) for an OPEN sum (dsum)
   whose payloads are not all leaf-readable. Like [emit_copyful_owned_sum] but
   the inductive owned low representation [<n>_low] also has an Unknown
   constructor carrying the raw tag repr and the default-type owned low value.
   [tn] is the tag enum type name, [cprefix] the constructor prefix, [cl] the
   (case, field-type) list (auto-completed over all known enum keys), and [dt]
   the default (unknown-case) field type name. *)
let emit_copyful_owned_dsum o i n tn cprefix cl dt =
  let g = pcombinator_name dt in
  let ii = ipub i o in
  let cap = String.capitalize_ascii in
  (* owned low representation (an inductive mirroring the high constructors),
     plus an Unknown constructor carrying the raw repr and the default lowtype.
     Emitted to the interface (under -pulse) for the transparent direct vmatch. *)
  wp ii "noeq type %s_low =\n" n;
  List.iter (fun (case, ty) -> wp ii "  | %s_%s_low of %s\n" cprefix case (copyful_lowtype_name ty)) cl;
  wp ii "  | %s_Unknown_%s_low : v:%s_repr{not (known_%s_repr v)} -> %s -> %s_low\n" cprefix tn tn tn (copyful_lowtype_name dt) n;
  wp ii "\n";
  wp ii "let %s_lowtype = %s_low\n\n" n n;
  (* refinement-free "mid" inductive (interface). *)
  wp ii "noextract noeq type %s_mid =\n" n;
  List.iter (fun (case, ty) -> wp ii "  | %s_%s_mid of %s\n" cprefix case (copyful_mid_name ty)) cl;
  wp ii "  | %s_Unknown_%s_mid : v:%s_repr{not (known_%s_repr v)} -> %s -> %s_mid\n" cprefix tn tn tn (copyful_mid_name dt) n;
  wp ii "\n";
  (* interface-side [maybe_enum_key]-typed tag discriminators. *)
  wp i "let %s_low_tag (xl: %s_low) : LP.maybe_enum_key %s_enum =\n  match xl with\n" n n tn;
  List.iter (fun (case, ty) -> wp i "  | %s_%s_low _ -> LP.Known (known_%s_as_enum_key %s)\n" cprefix case tn (cap case)) cl;
  wp i "  | %s_Unknown_%s_low v _ -> LP.Unknown (unknown_%s_as_enum_key v)\n\n" cprefix tn tn;
  wp i "noextract let %s_mid_tag (m: %s_mid) : LP.maybe_enum_key %s_enum =\n  match m with\n" n n tn;
  List.iter (fun (case, ty) -> wp i "  | %s_%s_mid _ -> LP.Known (known_%s_as_enum_key %s)\n" cprefix case tn (cap case)) cl;
  wp i "  | %s_Unknown_%s_mid v _ -> LP.Unknown (unknown_%s_as_enum_key v)\n\n" cprefix tn tn;
  (* transparent direct vmatch (interface). *)
  wp i "let %s_vmatch (xl: %s_low) (m: %s_mid) : Pulse.Lib.Core.slprop =\n  Pulse.Lib.Core.op_Star_Star\n    (Pulse.Lib.Core.pure (%s_low_tag xl == %s_mid_tag m))\n    (match m with\n" n n n n n;
  List.iter (fun (case, ty) ->
    wp i "     | %s_%s_mid cm -> (match xl with | %s_%s_low v -> %s v cm | _ -> Pulse.Lib.Core.pure False)\n" cprefix case cprefix case (copyful_vmatch_name ty)
  ) cl;
  wp i "     | %s_Unknown_%s_mid _ cm -> (match xl with | %s_Unknown_%s_low _ v -> %s v cm | _ -> Pulse.Lib.Core.pure False)\n" cprefix tn cprefix tn (copyful_vmatch_name dt);
  wp i "    )\n\n";
  (* transparent TIGHT conv (interface). *)
  wp i "noextract let %s_conv (m: %s_mid) : GTot (FStar.Pervasives.Native.option %s) =\n  match m with\n" n n n;
  List.iter (fun (case, ty) ->
    wp i "  | %s_%s_mid cm -> (match %s cm with | FStar.Pervasives.Native.Some y -> FStar.Pervasives.Native.Some (%s_%s y) | FStar.Pervasives.Native.None -> FStar.Pervasives.Native.None)\n" cprefix case (copyful_conv_name ty) cprefix case
  ) cl;
  wp i "  | %s_Unknown_%s_mid rv cm -> (match %s cm with | FStar.Pervasives.Native.Some y -> FStar.Pervasives.Native.Some (%s_Unknown_%s rv y) | FStar.Pervasives.Native.None -> FStar.Pervasives.Native.None)\n" cprefix tn (copyful_conv_name dt) cprefix tn;
  wp i "\n";
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  (* impl-side [dsum_key]-typed tag discriminator. *)
  wp o "inline_for_extraction\nlet %s_tag_of_low (xl: %s_low) : LP.dsum_key %s_sum =\n  match xl with\n" n n n;
  List.iter (fun (case, ty) -> wp o "  | %s_%s_low _ -> LP.Known (known_%s_as_enum_key %s)\n" cprefix case tn (cap case)) cl;
  wp o "  | %s_Unknown_%s_low v _ -> LP.Unknown (unknown_%s_as_enum_key v)\n\n" cprefix tn tn;
  (* impl-side per-tag refinement-free mid family and per-tag conv. *)
  wp o "#push-options \"--max_fuel 8 --max_ifuel 8 --z3rlimit 100\"\n";
  wp o "noextract let %s_mid_of_tag (k: LP.dsum_key %s_sum) : Type0 =\n  match k with\n  | LP.Known kk -> (match kk with\n" n n;
  List.iter (fun (case, ty) -> wp o "    | %s -> %s\n" (cap case) (copyful_mid_name ty)) cl;
  wp o "    )\n  | LP.Unknown _ -> %s\n\n" (copyful_mid_name dt);
  wp o "noextract let %s_conv_of_tag (k: LP.dsum_key %s_sum) : %s_mid_of_tag k -> GTot (FStar.Pervasives.Native.option (LP.dsum_type_of_tag %s_sum k)) =\n  match k with\n  | LP.Known kk -> (match kk with\n" n n n n;
  List.iter (fun (case, ty) -> wp o "    | %s -> %s\n" (cap case) (copyful_conv_name ty)) cl;
  wp o "    )\n  | LP.Unknown _ -> %s\n\n" (copyful_conv_name dt);
  (* impl-side per-case vmatch (bare child vmatch over the per-tag mid). *)
  wp o "let %s_casevmatch (k: LP.dsum_key %s_sum) (xl: %s_low) (cm: %s_mid_of_tag k) : Pulse.Lib.Core.slprop =\n  match k with\n  | LP.Known kk -> (match kk with\n" n n n n;
  List.iter (fun (case, ty) ->
    wp o "    | %s -> (match xl with | %s_%s_low v -> %s v cm | _ -> Pulse.Lib.Core.pure False)\n" (cap case) cprefix case (copyful_vmatch_name ty)
  ) cl;
  wp o "    )\n  | LP.Unknown _ -> (match xl with | %s_Unknown_%s_low _ v -> %s v cm | _ -> Pulse.Lib.Core.pure False)\n\n" cprefix tn (copyful_vmatch_name dt);
  (* ghost maps between the library dependent-pair mid and the interface mid. *)
  wp o "let %s_fg (m: PPS.dsum_mid %s_sum %s_mid_of_tag) : %s_mid =\n  match m with\n  | (| k, cm |) ->\n    (match k with\n     | LP.Known kk -> (match kk with\n" n n n n;
  List.iter (fun (case, ty) -> wp o "        | %s -> %s_%s_mid cm\n" (cap case) cprefix case) cl;
  wp o "        )\n     | LP.Unknown r -> %s_Unknown_%s_mid r cm\n    )\n\n" cprefix tn;
  wp o "let %s_gf (m: %s_mid) : PPS.dsum_mid %s_sum %s_mid_of_tag =\n  match m with\n" n n n n;
  List.iter (fun (case, ty) -> wp o "  | %s_%s_mid cm -> (| LP.Known (known_%s_as_enum_key %s), cm |)\n" cprefix case tn (cap case)) cl;
  wp o "  | %s_Unknown_%s_mid r cm -> (| LP.Unknown r, cm |)\n\n" cprefix tn;
  (* per-case copyful parsers (tight conv). *)
  wp o "inline_for_extraction\nlet copyful_%s_cases (k: LP.dsum_key %s_sum)\n  : PPS.copyful_parse_dsum_payload_t %s_sum parse_%s_cases %s %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag k =\n  match k with\n  | LP.Known kk -> (match kk with\n" n n n n g n n n n n;
  List.iter (fun (case, ty) ->
    wp o "    | %s -> PPS.copyful_parse_dsum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag (LP.Known %s)\n        %s %s_%s_low () ()\n" (cap case) n n n n n n (cap case) (copyful_read_name ty) cprefix case
  ) cl;
  wp o "    )\n  | LP.Unknown r -> PPS.copyful_parse_dsum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag (LP.Unknown r)\n      %s (fun lv -> %s_Unknown_%s_low r lv) () ()\n\n" n n n n n n (copyful_read_name dt) cprefix tn;
  (* copyful parser at the library dependent-pair mid, then bridged via coerce_mid. *)
  wp o "let read_%s_sum\n  : PPB.copyful_parse (PPS.vmatch_dsum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch) %s_parser (PPS.dsum_conv %s_sum %s_mid_of_tag %s_conv_of_tag) =\n  PPS.copyful_parse_dsum %s_sum read_maybe_%s_key %s_repr_jumper parse_%s_cases\n    %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag copyful_%s_cases (_ by (LP.dep_maybe_enum_destr_t_tac ())) (_ by (LP.enum_repr_of_key_tac %s_enum)) ()\n\n" n n n n n n n n n n n tn tn n n n n n n n tn;
  (* vmatch bridge lemma (per dtuple-key / low-pattern branch, plain norm). *)
  wp o "let %s_coerce_vmatch_eq (xl: %s_low) (m1: PPS.dsum_mid %s_sum %s_mid_of_tag)\n  : Lemma (PPS.vmatch_dsum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch xl m1 == %s_vmatch xl (%s_fg m1))\n  = match m1 with\n  | (| k, cm |) ->\n    (match k with\n" n n n n n n n n n n n;
  let vm_assert keyexpr xlpat =
    wp o "         | %s -> assert (PPS.vmatch_dsum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s) (| %s, cm |) == %s_vmatch (%s) (%s_fg (| %s, cm |))) by (FStar.Tactics.norm [delta; iota; zeta; primops]; FStar.Tactics.trefl ())\n"
      xlpat n n n n n xlpat keyexpr n xlpat n keyexpr
  in
  let low_pats = (List.map (fun (case, _) -> sprintf "%s_%s_low vp" cprefix case) cl) @ [sprintf "%s_Unknown_%s_low rvl vpl" cprefix tn] in
  wp o "     | LP.Known kk -> (match kk with\n";
  List.iter (fun (kcase, _) ->
    wp o "       | %s -> (match xl with\n" (cap kcase);
    List.iter (fun lpat -> vm_assert (sprintf "LP.Known %s" (cap kcase)) lpat) low_pats;
    wp o "        )\n"
  ) cl;
  wp o "       )\n";
  wp o "     | LP.Unknown r -> (match xl with\n";
  List.iter (fun lpat -> vm_assert "LP.Unknown r" lpat) low_pats;
  wp o "      )\n    )\n\n";
  (* conv bridge lemma (per dtuple-key branch, nbe+unascribe norm). *)
  wp o "let %s_coerce_conv_eq (m1: PPS.dsum_mid %s_sum %s_mid_of_tag)\n  : Lemma (%s_conv (%s_fg m1) == PPS.dsum_conv %s_sum %s_mid_of_tag %s_conv_of_tag m1)\n  = match m1 with\n  | (| k, cm |) ->\n    (match k with\n" n n n n n n n n;
  let conv_assert leading keyexpr =
    wp o "%sassert (%s_conv (%s_fg (| %s, cm |)) == PPS.dsum_conv %s_sum %s_mid_of_tag %s_conv_of_tag (| %s, cm |)) by (FStar.Tactics.norm [delta; iota; zeta; primops; unascribe; nbe]; FStar.Tactics.trefl ())\n"
      leading n n keyexpr n n n keyexpr
  in
  wp o "     | LP.Known kk -> (match kk with\n";
  List.iter (fun (kcase, _) -> conv_assert (sprintf "       | %s -> " (cap kcase)) (sprintf "LP.Known %s" (cap kcase))) cl;
  wp o "       )\n";
  wp o "     | LP.Unknown r -> ";
  conv_assert "" "LP.Unknown r";
  wp o "    )\n\n";
  wp o "let %s_coerce_eq ()\n  : Lemma (\n      (forall (xl: %s_low) (m1: PPS.dsum_mid %s_sum %s_mid_of_tag) .\n        PPS.vmatch_dsum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch xl m1 == %s_vmatch xl (%s_fg m1)) /\\\n      (forall (m1: PPS.dsum_mid %s_sum %s_mid_of_tag) .\n        %s_conv (%s_fg m1) == PPS.dsum_conv %s_sum %s_mid_of_tag %s_conv_of_tag m1)\n    )\n  = FStar.Classical.forall_intro_2 %s_coerce_vmatch_eq;\n    FStar.Classical.forall_intro %s_coerce_conv_eq\n\n" n n n n n n n n n n n n n n n n n n n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n  PPB.copyful_parse_coerce_mid read_%s_sum %s_vmatch %s_conv %s_fg (%s_coerce_eq ())\n\n" n n n n n n n n n;
  (* per-case free (bare child free over the per-tag mid). *)
  wp o "inline_for_extraction\nlet free_%s_cases (k: LP.dsum_key %s_sum)\n  : PPB.free_t (%s_casevmatch k) =\n  match k with\n  | LP.Known kk -> (match kk with\n" n n n;
  List.iter (fun (case, ty) ->
    wp o "    | %s -> PPS.free_dsum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (LP.Known %s)\n        %s (fun xl -> match xl with | %s_%s_low v -> Some v | _ -> None) ()\n" (cap case) n n n n n (cap case) (copyful_free_name ty) cprefix case
  ) cl;
  wp o "    )\n  | LP.Unknown r -> PPS.free_dsum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (LP.Unknown r)\n      %s (fun xl -> match xl with | %s_Unknown_%s_low _ v -> Some v | _ -> None) ()\n\n" n n n n n (copyful_free_name dt) cprefix tn;
  wp o "let free_%s_sum : PPB.free_t (PPS.vmatch_dsum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch) =\n  PPS.free_dsum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch free_%s_cases (_ by (LP.dep_maybe_enum_destr_t_tac ())) (_ by (LP.enum_repr_of_key_tac %s_enum))\n\n" n n n n n n n n n n n n tn;
  wp o "let %s_free_vmatch_eq (xl: %s_low) (m: %s_mid)\n  : Lemma (%s_vmatch xl m == PPS.vmatch_dsum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch xl (%s_gf m))\n  = match m with\n" n n n n n n n n n n;
  let fv_assert midpat xlpat =
    wp o "    | %s -> assert (%s_vmatch (%s) (%s) == PPS.vmatch_dsum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s) (%s_gf (%s))) by (FStar.Tactics.norm [delta; iota; zeta; primops]; FStar.Tactics.trefl ())\n"
      xlpat n xlpat midpat n n n n n xlpat n midpat
  in
  let low_pats_f = (List.map (fun (case, _) -> sprintf "%s_%s_low vp" cprefix case) cl) @ [sprintf "%s_Unknown_%s_low rvl vpl" cprefix tn] in
  List.iter (fun (mcase, _) ->
    wp o "  | %s_%s_mid cm -> (match xl with\n" cprefix mcase;
    List.iter (fun lpat -> fv_assert (sprintf "%s_%s_mid cm" cprefix mcase) lpat) low_pats_f;
    wp o "    )\n"
  ) cl;
  wp o "  | %s_Unknown_%s_mid rv cm -> (match xl with\n" cprefix tn;
  List.iter (fun lpat -> fv_assert (sprintf "%s_Unknown_%s_mid rv cm" cprefix tn) lpat) low_pats_f;
  wp o "    )\n\n";
  wp o "let free_%s : PPB.free_t %s_vmatch =\n  PPB.free_coerce_mid free_%s_sum %s_vmatch %s_gf (FStar.Classical.forall_intro_2 %s_free_vmatch_eq)\n\n" n n n n n n;
  (* Graceful safe writer (write_<n>) for the open dsum, emitted only if every
     known case field type AND the default type have an available writer. *)
  if !emit_pulse && copyful_writer_available dt && List.for_all (fun (_, ty) -> copyful_writer_available ty) cl then begin
    let tagsz = (get_leninfo tn).min_len in
    wp o "inline_for_extraction\nlet write_%s_cases (k: LP.dsum_key %s_sum)\n  : PPS.l2r_safe_writer_dsum_payload_t %s_sum parse_%s_cases serialize_%s_cases %s %s %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag k =\n  match k with\n  | LP.Known kk -> (match kk with\n" n n n n n (pcombinator_name dt) (scombinator_name dt) n n n n n;
    List.iter (fun (case, ty) ->
      wp o "    | %s -> PPS.l2r_safe_writer_dsum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag (LP.Known %s)\n        %s (fun xl -> match xl with | %s_%s_low v -> Some v | _ -> None) ()\n" (cap case) n n n n n n (cap case) (copyful_writer_name ty) cprefix case
    ) cl;
    wp o "    )\n  | LP.Unknown r -> PPS.l2r_safe_writer_dsum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag (LP.Unknown r)\n      %s (fun xl -> match xl with | %s_Unknown_%s_low _ v -> Some v | _ -> None) ()\n\n" n n n n n n (copyful_writer_name dt) cprefix tn;
    wp o "let write_%s_sum\n  : PPB.l2r_safe_writer (PPS.vmatch_dsum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch) (LP.serialize_dsum %s_sum %s_repr_serializer parse_%s_cases serialize_%s_cases %s %s) (PPS.dsum_conv %s_sum %s_mid_of_tag %s_conv_of_tag) =\n  PPS.l2r_safe_writer_dsum %s_sum %s_repr_serializer write_maybe_%s_key %dsz parse_%s_cases serialize_%s_cases %s %s\n    %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag write_%s_cases (_ by (LP.dep_maybe_enum_destr_t_tac ())) (_ by (LP.enum_repr_of_key_tac %s_enum)) ()\n\n" n n n n n n n tn n n (pcombinator_name dt) (scombinator_name dt) n n n n tn tn tagsz n n (pcombinator_name dt) (scombinator_name dt) n n n n n n tn;
    wp o "let %s_write_conv_eq (m: %s_mid)\n  : Lemma (%s_conv m == PPS.dsum_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_gf m))\n  = match m with\n" n n n n n n n;
    List.iter (fun (mcase, _) ->
      wp o "  | %s_%s_mid cm -> assert (%s_conv (%s_%s_mid cm) == PPS.dsum_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_gf (%s_%s_mid cm))) by (FStar.Tactics.norm [delta; iota; zeta; primops; unascribe; nbe]; FStar.Tactics.trefl ())\n"
        cprefix mcase n cprefix mcase n n n n cprefix mcase
    ) cl;
    wp o "  | %s_Unknown_%s_mid rv cm -> assert (%s_conv (%s_Unknown_%s_mid rv cm) == PPS.dsum_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_gf (%s_Unknown_%s_mid rv cm))) by (FStar.Tactics.norm [delta; iota; zeta; primops; unascribe; nbe]; FStar.Tactics.trefl ())\n\n" cprefix tn n cprefix tn n n n n cprefix tn;
    wp o "let %s_write_coerce_eq ()\n  : Lemma (\n      (forall (x: %s_low) (m2: %s_mid) . %s_vmatch x m2 == PPS.vmatch_dsum %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch x (%s_gf m2)) /\\\n      (forall (m2: %s_mid) . %s_conv m2 == PPS.dsum_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_gf m2))\n    )\n  = FStar.Classical.forall_intro_2 %s_free_vmatch_eq;\n    FStar.Classical.forall_intro %s_write_conv_eq\n\n" n n n n n n n n n n n n n n n n n n;
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n  PPB.l2r_safe_writer_coerce_mid write_%s_sum %s_vmatch %s_conv %s_gf (%s_write_coerce_eq ())\n\n" n n n n n n n n n;
    register_writer n
  end;
  wp o "#pop-options\n\n"

(* Emit copyful parser (read_<n>) and free (free_<n>) for an IMPLICIT sum: the
   tag is not stored inline but supplied as a parameter [k], the high type is
   [<n> k] (= a tag-refinement, defeq to [LP.sum_cases <n>_sum (<tn>_as_enum_key k)]
   via the generated [<n>_eq_lemma] SMTPat), and the parser is parameterized:
   [<n>_parser k = LP.parse_sum_cases <n>_sum parse_<n>_cases (<tn>_as_enum_key k)].
   We reuse the closed owned-sum machinery (inductive [<n>_low], [<n>_tag_of_low],
   [<n>_casevmatch], per-case copyful/free) but emit a tag-parameterized vmatch,
   read_<n> and free_<n> built from PPS.{vmatch,copyful_parse,free}_sum_cases.
   [tn] is the tag enum type name, [cprefix] the constructor prefix, [cl] the
   (case, field-type) list (auto-completed, default folded in). *)
let emit_copyful_implicit_sum o i n tn cprefix cl =
  let ii = ipub i o in
  let cap = String.capitalize_ascii in
  (* owned low representation (an inductive mirroring the high constructors),
     emitted to the interface (under -pulse) for the transparent direct vmatch. *)
  wp ii "noeq type %s_low =\n" n;
  List.iter (fun (case, ty) -> wp ii "  | %s_%s_low of %s\n" cprefix case (copyful_lowtype_name ty)) cl;
  wp ii "\n";
  wp ii "let %s_lowtype = %s_low\n\n" n n;
  (* interface-side [enum_key]-typed tag discriminator on the low repr. *)
  wp i "let %s_low_tag (xl: %s_low) : LP.enum_key %s_enum =\n  match xl with\n" n n tn;
  List.iter (fun (case, ty) -> wp i "  | %s_%s_low _ -> %s_as_enum_key %s\n" cprefix case tn (cap case)) cl;
  wp i "\n";
  (* exposed per-tag refinement-free mid (textual, no [<n>_sum] reference). *)
  wp i "noextract let %s_mid (k:%s) : Type0 =\n  match k with\n" n tn;
  List.iter (fun (case, ty) -> wp i "  | %s -> %s\n" (cap case) (copyful_mid_name ty)) cl;
  wp i "\n";
  (* exposed per-tag transparent vmatch (textual). [m : <n>_mid k] reduces to the
     case's child mid once [k] is fixed by the match. *)
  wp i "let %s_vmatch (k:%s) (xl: %s_low) (m: %s_mid k) : Pulse.Lib.Core.slprop =\n  match k with\n" n tn n n;
  List.iter (fun (case, ty) ->
    wp i "  | %s -> Pulse.Lib.Core.op_Star_Star (Pulse.Lib.Core.pure (%s_low_tag xl == %s_as_enum_key %s)) (match xl with | %s_%s_low v -> %s v m | _ -> Pulse.Lib.Core.pure False)\n" (cap case) n tn (cap case) cprefix case (copyful_vmatch_name ty)
  ) cl;
  wp i "\n";
  (* exposed per-tag TIGHT conv (textual): a case's mid maps to the high value iff
     the child conv succeeds. *)
  wp i "noextract let %s_conv (k:%s) : %s_mid k -> GTot (FStar.Pervasives.Native.option (%s k)) =\n  match k with\n" n tn n n;
  List.iter (fun (case, ty) ->
    wp i "  | %s -> (fun cm -> match %s cm with | FStar.Pervasives.Native.Some y -> FStar.Pervasives.Native.Some (%s_%s y <: %s %s) | FStar.Pervasives.Native.None -> FStar.Pervasives.Native.None)\n" (cap case) (copyful_conv_name ty) cprefix case n (cap case)
  ) cl;
  wp i "\n";
  wp i "val read_%s (k:%s) : PPB.copyful_parse (%s_vmatch k) (%s_parser k) (%s_conv k)\n\n" n tn n n n;
  wp i "val free_%s (k:%s) : PPB.free_t (%s_vmatch k)\n\n" n tn n;
  (* impl-side [sum_key]-typed tag discriminator (consumed by the sum machinery). *)
  wp o "inline_for_extraction\nlet %s_tag_of_low (xl: %s_low) : LP.sum_key %s_sum =\n  match xl with\n" n n n;
  List.iter (fun (case, ty) -> wp o "  | %s_%s_low _ -> %s_as_enum_key %s\n" cprefix case tn (cap case)) cl;
  wp o "\n";
  (* impl-side per-tag refinement-free mid family and per-tag conv. *)
  wp o "noextract let %s_mid_of_tag (k: LP.sum_key %s_sum) : Type0 =\n  match k with\n" n n;
  List.iter (fun (case, ty) -> wp o "  | %s -> %s\n" (cap case) (copyful_mid_name ty)) cl;
  wp o "\n";
  wp o "noextract let %s_conv_of_tag (k: LP.sum_key %s_sum) : %s_mid_of_tag k -> GTot (FStar.Pervasives.Native.option (LP.sum_type_of_tag %s_sum k)) =\n  match k with\n" n n n n;
  List.iter (fun (case, ty) -> wp o "  | %s -> %s\n" (cap case) (copyful_conv_name ty)) cl;
  wp o "\n";
  (* impl-side per-case vmatch (bare child vmatch over the per-tag mid). *)
  wp o "let %s_casevmatch (k: LP.sum_key %s_sum) (xl: %s_low) (cm: %s_mid_of_tag k) : Pulse.Lib.Core.slprop =\n  match k with\n" n n n n;
  List.iter (fun (case, ty) -> wp o "  | %s -> (match xl with | %s_%s_low v -> %s v cm | _ -> Pulse.Lib.Core.pure False)\n" (cap case) cprefix case (copyful_vmatch_name ty)) cl;
  wp o "\n";
  (* identity-retype between the exposed per-tag mid and the library per-tag mid:
     for each fixed [k] both reduce to the same child mid. *)
  wp o "let %s_fg (k:%s) (m: %s_mid_of_tag (%s_as_enum_key k)) : %s_mid k =\n  match k with\n" n tn n tn n;
  List.iter (fun (case, ty) -> wp o "  | %s -> m\n" (cap case)) cl;
  wp o "\n";
  wp o "let %s_gf (k:%s) (m: %s_mid k) : %s_mid_of_tag (%s_as_enum_key k) =\n  match k with\n" n tn n n tn;
  List.iter (fun (case, ty) -> wp o "  | %s -> m\n" (cap case)) cl;
  wp o "\n";
  (* per-case copyful parsers (tight conv). *)
  wp o "inline_for_extraction\nlet copyful_%s_cases (k: LP.sum_key %s_sum)\n  : PPS.copyful_parse_sum_payload_t %s_sum parse_%s_cases %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag k =\n  match k with\n" n n n n n n n n n;
  List.iter (fun (case, ty) -> wp o "  | %s -> PPS.copyful_parse_sum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag %s\n      %s %s_%s_low () ()\n" (cap case) n n n n n n (cap case) (copyful_read_name ty) cprefix case) cl;
  wp o "\n";
  (* copyful parser at the library per-tag mid, then bridged to the transparent
     interface mid/vmatch/conv via [copyful_parse_coerce_mid]. *)
  wp o "let read_%s_sum (k:%s)\n  : PPB.copyful_parse (PPS.vmatch_sum_cases %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s_as_enum_key k)) (%s_parser k) (PPS.sum_cases_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_as_enum_key k)) =\n  PPS.copyful_parse_sum_cases %s_sum parse_%s_cases\n    %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag copyful_%s_cases (_ by (LP.dep_enum_destr_tac ())) (%s_as_enum_key k)\n\n" n tn n n n n n tn n n n n tn n n n n n n n n tn;
  wp o "let %s_coerce_vmatch_eq (k:%s) (xl: %s_low) (m1: %s_mid_of_tag (%s_as_enum_key k))\n  : Lemma (PPS.vmatch_sum_cases %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s_as_enum_key k) xl m1 == %s_vmatch k xl (%s_fg k m1))\n  = match k with\n" n tn n n tn n n n n n tn n n;
  List.iter (fun (kcase, kty) ->
    wp o "  | %s -> (match xl with\n" (cap kcase);
    List.iter (fun (xcase, xty) ->
      wp o "    | %s_%s_low vp -> assert (PPS.vmatch_sum_cases %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s_as_enum_key %s) (%s_%s_low vp) m1 == %s_vmatch %s (%s_%s_low vp) (%s_fg %s m1)) by (FStar.Tactics.norm [delta; iota; zeta; primops]; FStar.Tactics.trefl ())\n"
        cprefix xcase n n n n n tn (cap kcase) cprefix xcase n (cap kcase) cprefix xcase n (cap kcase)
    ) cl;
    wp o "    )\n"
  ) cl;
  wp o "\n";
  wp o "let %s_coerce_conv_eq (k:%s) (m1: %s_mid_of_tag (%s_as_enum_key k))\n  : Lemma (%s_conv k (%s_fg k m1) == PPS.sum_cases_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_as_enum_key k) m1)\n  = match k with\n" n tn n tn n n n n n tn;
  List.iter (fun (kcase, kty) ->
    wp o "  | %s -> %s_eq_lemma %s; assert (%s_conv %s (%s_fg %s m1) == PPS.sum_cases_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_as_enum_key %s) m1) by (FStar.Tactics.norm [delta; iota; zeta; primops; unascribe; nbe]; FStar.Tactics.smt ())\n"
      (cap kcase) n (cap kcase) n (cap kcase) n (cap kcase) n n n tn (cap kcase)
  ) cl;
  wp o "\n";
  wp o "let %s_coerce_eq (k:%s)\n  : Lemma (\n      (forall (xl: %s_low) (m1: %s_mid_of_tag (%s_as_enum_key k)) .\n        PPS.vmatch_sum_cases %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s_as_enum_key k) xl m1 == %s_vmatch k xl (%s_fg k m1)) /\\\n      (forall (m1: %s_mid_of_tag (%s_as_enum_key k)) .\n        %s_conv k (%s_fg k m1) == PPS.sum_cases_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_as_enum_key k) m1)\n    )\n  = FStar.Classical.forall_intro_2 (%s_coerce_vmatch_eq k);\n    FStar.Classical.forall_intro (%s_coerce_conv_eq k)\n\n" n tn n n tn n n n n n tn n n n tn n n n n n tn n n;
  wp o "let read_%s (k:%s) : PPB.copyful_parse (%s_vmatch k) (%s_parser k) (%s_conv k) =\n  PPB.copyful_parse_coerce_mid (read_%s_sum k) (%s_vmatch k) (%s_conv k) (%s_fg k) (%s_coerce_eq k)\n\n" n tn n n n n n n n n;
  (* per-case free (bare child free over the per-tag mid). *)
  wp o "inline_for_extraction\nlet free_%s_cases (k: LP.sum_key %s_sum)\n  : PPB.free_t (%s_casevmatch k) =\n  match k with\n" n n n;
  List.iter (fun (case, ty) -> wp o "  | %s -> PPS.free_sum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s\n      %s (fun xl -> match xl with | %s_%s_low v -> Some v | _ -> None) ()\n" (cap case) n n n n n (cap case) (copyful_free_name ty) cprefix case) cl;
  wp o "\n";
  wp o "let free_%s_sum (k:%s) : PPB.free_t (PPS.vmatch_sum_cases %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s_as_enum_key k)) =\n  PPS.free_sum_cases %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch free_%s_cases (_ by (LP.dep_enum_destr_tac ())) (%s_as_enum_key k)\n\n" n tn n n n n n tn n n n n n n tn;
  wp o "let %s_free_vmatch_eq (k:%s) (xl: %s_low) (m: %s_mid k)\n  : Lemma (%s_vmatch k xl m == PPS.vmatch_sum_cases %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s_as_enum_key k) xl (%s_gf k m))\n  = match k with\n" n tn n n n n n n n n tn n;
  List.iter (fun (kcase, kty) ->
    wp o "  | %s -> (match xl with\n" (cap kcase);
    List.iter (fun (xcase, xty) ->
      wp o "    | %s_%s_low vp -> assert (%s_vmatch %s (%s_%s_low vp) m == PPS.vmatch_sum_cases %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s_as_enum_key %s) (%s_%s_low vp) (%s_gf %s m)) by (FStar.Tactics.norm [delta; iota; zeta; primops]; FStar.Tactics.trefl ())\n"
        cprefix xcase n (cap kcase) cprefix xcase n n n n n tn (cap kcase) cprefix xcase n (cap kcase)
    ) cl;
    wp o "    )\n"
  ) cl;
  wp o "\n";
  wp o "let free_%s (k:%s) : PPB.free_t (%s_vmatch k) =\n  PPB.free_coerce_mid (free_%s_sum k) (%s_vmatch k) (%s_gf k) (FStar.Classical.forall_intro_2 (%s_free_vmatch_eq k))\n\n" n tn n n n n n;
  (* Graceful safe writer (write_<n>, tag-parameterized) for the implicit sum,
     emitted only if every case field type has an available writer. Mirrors
     read_<n>: build at the library per-tag mid via PPS.l2r_safe_writer_sum_cases
     (NO tag written), then re-index to the transparent interface mid/vmatch/conv
     with PPB.l2r_safe_writer_coerce_mid (gf direction). *)
  if !emit_pulse && List.for_all (fun (_, ty) -> copyful_writer_available ty) cl then begin
    wp o "inline_for_extraction\nlet write_%s_cases (k: LP.sum_key %s_sum)\n  : PPS.l2r_safe_writer_sum_payload_t %s_sum parse_%s_cases serialize_%s_cases %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag k =\n  match k with\n" n n n n n n n n n n;
    List.iter (fun (case, ty) ->
      wp o "  | %s -> PPS.l2r_safe_writer_sum_case %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag %s\n      %s (fun xl -> match xl with | %s_%s_low v -> Some v | _ -> None) ()\n" (cap case) n n n n n n (cap case) (copyful_writer_name ty) cprefix case
    ) cl;
    wp o "\n";
    wp o "let write_%s_sum (k:%s)\n  : PPB.l2r_safe_writer (PPS.vmatch_sum_cases %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s_as_enum_key k)) (LP.serialize_sum_cases %s_sum parse_%s_cases serialize_%s_cases (%s_as_enum_key k)) (PPS.sum_cases_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_as_enum_key k)) =\n  PPS.l2r_safe_writer_sum_cases %s_sum parse_%s_cases serialize_%s_cases\n    %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch %s_conv_of_tag write_%s_cases (_ by (LP.dep_enum_destr_tac ())) (%s_as_enum_key k)\n\n" n tn n n n n n tn n n n tn n n n tn n n n n n n n n n tn;
    wp o "let %s_write_conv_eq (k:%s) (m: %s_mid k)\n  : Lemma (%s_conv k m == PPS.sum_cases_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_as_enum_key k) (%s_gf k m))\n  = match k with\n" n tn n n n n n tn n;
    List.iter (fun (kcase, _) ->
      wp o "  | %s -> %s_eq_lemma %s; assert (%s_conv %s m == PPS.sum_cases_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_as_enum_key %s) (%s_gf %s m)) by (FStar.Tactics.norm [delta; iota; zeta; primops; unascribe; nbe]; FStar.Tactics.smt ())\n"
        (cap kcase) n (cap kcase) n (cap kcase) n n n tn (cap kcase) n (cap kcase)
    ) cl;
    wp o "\n";
    wp o "let %s_write_coerce_eq (k:%s)\n  : Lemma (\n      (forall (x: %s_low) (m2: %s_mid k) .\n        %s_vmatch k x m2 == PPS.vmatch_sum_cases %s_sum %s_low %s_tag_of_low %s_mid_of_tag %s_casevmatch (%s_as_enum_key k) x (%s_gf k m2)) /\\\n      (forall (m2: %s_mid k) .\n        %s_conv k m2 == PPS.sum_cases_conv %s_sum %s_mid_of_tag %s_conv_of_tag (%s_as_enum_key k) (%s_gf k m2))\n    )\n  = FStar.Classical.forall_intro_2 (%s_free_vmatch_eq k);\n    FStar.Classical.forall_intro (%s_write_conv_eq k)\n\n" n tn n n n n n n n n tn n n n n n n tn n n n;
    wp i "val write_%s (k:%s) : PPB.l2r_safe_writer (%s_vmatch k) (%s_serializer k) (%s_conv k)\n\n" n tn n n n;
    wp o "let write_%s (k:%s) : PPB.l2r_safe_writer (%s_vmatch k) (%s_serializer k) (%s_conv k) =\n  PPB.l2r_safe_writer_coerce_mid (write_%s_sum k) (%s_vmatch k) (%s_conv k) (%s_gf k) (%s_write_coerce_eq k)\n\n" n tn n n n n n n n n
  end

(* Emit copyful parser (read_<n>) and free (free_<n>) for a fixed-count array
   [ty\[byte_size\]] (elem_count elements of element type [ty]). The low-level
   representation is a freshly allocated, freeable [Pulse.Lib.Vec.vec <elem_lowtype>]
   related to the high-level list via PPAR.vmatch_array (elementwise reusing the
   element type's own copyful vmatch). *)
let emit_copyful_array o i n ty byte_size elem_count =
  wp i "let %s_lowtype = Pulse.Lib.Vec.vec %s\n\n" n (copyful_lowtype_name ty);
  wp i "noextract let %s_mid = list %s\n\n" n (compile_type ty);
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop = PPAR.vmatch_array (PPB.vmatch_conv %s %s) %dsz\n\n" n n n (copyful_vmatch_name ty) (copyful_conv_name ty) elem_count;
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) = PPAR.array_conv %d\n\n" n n n elem_count;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n" n n n n;
  wp o "  %s_eq ();\n" n;
  wp o "  assert_norm (LP.fldata_array_precond (LP.get_parser_kind %s) %d %d == true);\n" (pcombinator_name ty) byte_size elem_count;
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
  wp o "  PPAR.copyful_parse_array %s %s %s %d %dsz %d %dsz ()\n\n" (scombinator_name ty) (copyful_read_name ty) (pulse_jumper_name ty) byte_size byte_size elem_count elem_count;
  wp o "let free_%s : PPB.free_t %s_vmatch = fun x #v -> PPAR.free_array (PPB.free_vmatch_conv %s %s %s) %dsz x #(Ghost.hide (Ghost.reveal v <: list %s))\n\n" n n (copyful_vmatch_name ty) (copyful_conv_name ty) (copyful_free_name ty) elem_count (compile_type ty);
  if !emit_pulse && copyful_writer_available ty then begin
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  %s_eq ();\n" n;
    wp o "  assert_norm (LP.fldata_array_precond (LP.get_parser_kind %s) %d %d == true);\n" (pcombinator_name ty) byte_size elem_count;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
    wp o "  PPAR.l2r_safe_writer_array %s %s %d %dsz %d %dsz () ()\n\n" (scombinator_name ty) (copyful_writer_name ty) byte_size byte_size elem_count elem_count;
    register_writer n
  end;
  if !emit_pulse && copyful_size_available ty then begin
    wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  %s_eq ();\n" n;
    wp o "  assert_norm (LP.fldata_array_precond (LP.get_parser_kind %s) %d %d == true);\n" (pcombinator_name ty) byte_size elem_count;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
    wp o "  PPAR.l2r_safe_size_array %s %s %d %dsz %d %dsz () ()\n\n" (scombinator_name ty) (copyful_size_name ty) byte_size byte_size elem_count elem_count;
    register_size n
  end

(* Emit copyful parser (read_<n>) and free (free_<n>) for a variable-count list
   [ty<low..high>] prefixed by its element count (parsed with [repr_t]'s leaf
   reader/jumper). The low-level representation is [PPVCL.vclist_lowtype
   <elem_lowtype>] = [option (SizeT.t * Pulse.Lib.Vec.vec <elem_lowtype>)] (None
   for the empty list), related to the high-level list via PPVCL.vmatch_vclist
   (elementwise reusing the element type's own copyful vmatch). *)
let emit_copyful_vclist o i n ty low high repr_t =
  wp i "let %s_lowtype = PPVCL.vclist_lowtype %s\n\n" n (copyful_lowtype_name ty);
  wp i "noextract let %s_mid = list %s\n\n" n (compile_type ty);
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop = PPVCL.vmatch_vclist (PPB.vmatch_conv %s %s)\n\n" n n n (copyful_vmatch_name ty) (copyful_conv_name ty);
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) = PPVCL.vclist_conv (FStar.UInt32.v %dul) (FStar.UInt32.v %dul)\n\n" n n n low high;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n" n n n n;
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
  wp o "  PPVCL.copyful_parse_vclist %dul %dul %s %s %s %s () ()\n\n" low high (pulse_jumper_name repr_t) (pulse_leaf_reader_name repr_t) (copyful_read_name ty) (pulse_jumper_name ty);
  wp o "let free_%s : PPB.free_t %s_vmatch = fun x #v -> PPVCL.free_vclist (PPB.free_vmatch_conv %s %s %s) x #(Ghost.hide (Ghost.reveal v <: list %s))\n\n" n n (copyful_vmatch_name ty) (copyful_conv_name ty) (copyful_free_name ty) (compile_type ty);
  (* Pulse: copyful safe WRITER (write_<n>) for the element-count-framed (vclist)
     list. The count header is a bcvli over U32; the payload bytes coincide with
     [serialize_list] bytes, so the combinator writes the count then the list body.
     Gated on the element type having a graceful writer. Only bitcoin_varint count
     headers are supported (bcvli leaf writer). *)
  if !emit_pulse && repr_t = "bitcoin_varint" && copyful_writer_available ty then begin
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name repr_t);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
    wp o "  PPVCL.l2r_safe_writer_vclist (FStar.UInt32.v %dul) %dul (FStar.UInt32.v %dul) %dul %s PPBCVLI.bcvli_size (PPBCVLI.l2r_leaf_write_bcvli ()) %s %s ()\n\n" low low high high (scombinator_name repr_t) (scombinator_name ty) (copyful_writer_name ty);
    register_writer n
  end;
  (* Pulse: copyful safe SIZE (size_<n>) for the element-count-framed (vclist)
     list. Same structure as the writer but without an output buffer. Gated on the
     element type having a graceful size. *)
  if !emit_pulse && repr_t = "bitcoin_varint" && copyful_size_available ty then begin
    wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name repr_t);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
    wp o "  PPVCL.l2r_safe_size_vclist (FStar.UInt32.v %dul) %dul (FStar.UInt32.v %dul) %dul %s PPBCVLI.bcvli_size %s %s ()\n\n" low low high high (scombinator_name repr_t) (scombinator_name ty) (copyful_size_name ty);
    register_size n
  end

(* Emit copyful parser (read_<n>) and free (free_<n>) for a byte-length-bounded
   list [ty<low..high>]: a list of [ty] elements framed by a byte-length prefix
   ([parse_bounded_vldata_strong] of [serialize_list]), then coerced via
   [parse_synth synth_<n>] to the refined list type <n>. The low-level
   representation is the same [PPVCL.vclist_lowtype <elem_lowtype>] used for
   vclist -- neither the byte-length framing nor the synth coercion changes the
   high-level value or its copyful representation -- so read/free are assembled
   as PPC.copyful_parse_synth (PPVD.copyful_parse_bounded_vldata_strong_payload
   (PPLS.copyful_parse_list ...)) and the dual for free, reusing the element's own
   copyful parser/free and PPVCL.free_vclist. [min]/[max] are the payload byte
   bounds (length prefix excluded). The vmatch mentions synth_<n>_recip (a
   .fst-only definition), so it is exported abstractly. *)
let emit_copyful_vldata_list o i n ty min max =
  wp i "let %s_lowtype = PPVCL.vclist_lowtype %s\n\n" n (copyful_lowtype_name ty);
  wp i "noextract let %s_mid = list %s\n\n" n (compile_type ty);
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop =\n" n n n;
  wp i "  PPVD.vmatch_vldata_strong %d %d (LP.serialize_list _ %s) (PPVCL.vmatch_vclist (PPB.vmatch_conv %s %s))\n\n" min max (scombinator_name ty) (copyful_vmatch_name ty) (copyful_conv_name ty);
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) =\n" n n n;
  wp i "  PPC.synth_conv (PPVD.vldata_strong_conv %d %d (LP.serialize_list _ %s) (fun (x: list %s) -> FStar.Pervasives.Native.Some x)) synth_%s\n\n" min max (scombinator_name ty) (compile_type ty) n;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "\nlet %s_copyful_synth_injective () : Lemma (LP.synth_injective synth_%s) = ()\n\n" n n;
  wp o "let %s_copyful_synth_inverse () : Lemma (LP.synth_inverse synth_%s synth_%s_recip) = ()\n\n" n n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n" n n n n;
  wp o "  %s_copyful_synth_injective ();\n" n;
  wp o "  %s_copyful_synth_inverse ();\n" n;
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
  wp o "  PPC.copyful_parse_synth\n";
  wp o "    (PPVD.copyful_parse_bounded_vldata_strong_payload %d %d (LP.serialize_list _ %s)\n" min max (scombinator_name ty);
  wp o "       (PPLS.copyful_parse_list %s %s ())\n" (copyful_read_name ty) (pulse_jumper_name ty);
  wp o "       (PPBI.leaf_read_bounded_integer_%d ()))\n" (log256 max);
  wp o "    synth_%s synth_%s_recip\n\n" n n;
  wp o "let free_%s : PPB.free_t %s_vmatch =\n" n n;
  wp o "  PPVD.free_vldata_strong %d %d (LP.serialize_list _ %s) (PPVCL.free_vclist (PPB.free_vmatch_conv %s %s %s))\n\n" min max (scombinator_name ty) (copyful_vmatch_name ty) (copyful_conv_name ty) (copyful_free_name ty);
  if !emit_pulse && copyful_writer_available ty then begin
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  %s_copyful_synth_injective ();\n" n;
    wp o "  %s_copyful_synth_inverse ();\n" n;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
    wp o "  PPC.l2r_safe_writer_synth\n";
    wp o "    ((PPVD.l2r_safe_writer_bounded_vldata_strong_payload %d %dul %d %dul %d %dsz (LP.serialize_list _ %s)\n" min min max max (log256 max) (log256 max) (scombinator_name ty);
    wp o "       (PPLS.l2r_safe_writer_list %s %s ())) <: PPB.l2r_safe_writer _ %s'_serializer _)\n" (scombinator_name ty) (copyful_writer_name ty) n;
    wp o "    synth_%s synth_%s_recip\n\n" n n;
    register_writer n
  end

(* Like emit_copyful_vldata_list but for a list framed by a generic length-header
   parser (parse_bounded_vlgen, used when the [<lo..hi : repr>] vector specifies
   an explicit length-prefix representation). Same low representation/vmatch/free
   as the plain vlbytes-framed list; only the framing combinator differs
   (PPVG.copyful_parse_bounded_vlgen_payload, which still produces
   PPVD.vmatch_vldata_strong). [lenty] is the length-prefix representation. *)
let emit_copyful_vllist o i n ty smin smax lenty =
  wp i "let %s_lowtype = PPVCL.vclist_lowtype %s\n\n" n (copyful_lowtype_name ty);
  wp i "noextract let %s_mid = list %s\n\n" n (compile_type ty);
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop =\n" n n n;
  wp i "  PPVD.vmatch_vldata_strong %d %d (LP.serialize_list _ %s) (PPVCL.vmatch_vclist (PPB.vmatch_conv %s %s))\n\n" smin smax (scombinator_name ty) (copyful_vmatch_name ty) (copyful_conv_name ty);
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) =\n" n n n;
  wp i "  PPC.synth_conv (PPVD.vldata_strong_conv %d %d (LP.serialize_list _ %s) (fun (x: list %s) -> FStar.Pervasives.Native.Some x)) synth_%s\n\n" smin smax (scombinator_name ty) (compile_type ty) n;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "\nlet %s_copyful_synth_injective () : Lemma (LP.synth_injective synth_%s) = ()\n\n" n n;
  wp o "let %s_copyful_synth_inverse () : Lemma (LP.synth_inverse synth_%s synth_%s_recip) = ()\n\n" n n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n" n n n n;
  wp o "  %s_copyful_synth_injective ();\n" n;
  wp o "  %s_copyful_synth_inverse ();\n" n;
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_length_header_name lenty smin smax);
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
  wp o "  PPC.copyful_parse_synth\n";
  wp o "    (PPVG.copyful_parse_bounded_vlgen_payload %d %d %s %s (LP.serialize_list _ %s)\n" smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax) (scombinator_name ty);
  wp o "       (PPLS.copyful_parse_list %s %s ()) ())\n" (copyful_read_name ty) (pulse_jumper_name ty);
  wp o "    synth_%s synth_%s_recip\n\n" n n;
  wp o "let free_%s : PPB.free_t %s_vmatch =\n" n n;
  wp o "  PPVD.free_vldata_strong %d %d (LP.serialize_list _ %s) (PPVCL.free_vclist (PPB.free_vmatch_conv %s %s %s))\n\n" smin smax (scombinator_name ty) (copyful_vmatch_name ty) (copyful_conv_name ty) (copyful_free_name ty);
  (* Pulse: copyful safe writer. Only for bcvli (bitcoin_varint) length headers
     (the only generic vlgen length-header writer built so far) and when the
     element type has both a graceful writer and a graceful size (the payload
     list size pass that feeds the up-front header value). *)
  if !emit_pulse && lenty = "bitcoin_varint"
     && copyful_writer_available ty && copyful_size_available ty then begin
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  %s_copyful_synth_injective ();\n" n;
    wp o "  %s_copyful_synth_inverse ();\n" n;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_length_header_name lenty smin smax);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
    wp o "  PPC.l2r_safe_writer_synth\n";
    wp o "    ((PPVG.l2r_safe_writer_bounded_vlgen_payload %d %dul %d %dul %s (fun x -> PPBCVLI.bounded_bcvli_size %d %d x) (PPBCVLI.l2r_leaf_write_bounded_bcvli %d %d ()) (LP.serialize_list _ %s)\n" smin smin smax smax (scombinator_length_header_name lenty smin smax) smin smax smin smax (scombinator_name ty);
    wp o "       (PPLS.l2r_safe_writer_list %s %s ()) (PPLS.l2r_safe_size_list %s %s ())) <: PPB.l2r_safe_writer _ %s'_serializer _)\n" (scombinator_name ty) (copyful_writer_name ty) (scombinator_name ty) (copyful_size_name ty) n;
    wp o "    synth_%s synth_%s_recip\n\n" n n;
    register_writer n
  end;
  (* Pulse: copyful safe SIZE (size_<n>) for the bcvli-framed vllist. Needed so
     the vllist can compose into an enclosing struct/list size pass. Gated only
     on the element type having a graceful size. *)
  if !emit_pulse && lenty = "bitcoin_varint" && copyful_size_available ty then begin
    wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  %s_copyful_synth_injective ();\n" n;
    wp o "  %s_copyful_synth_inverse ();\n" n;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_length_header_name lenty smin smax);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
    wp o "  PPC.l2r_safe_size_synth\n";
    wp o "    ((PPVG.l2r_safe_size_bounded_vlgen_payload %d %dul %d %dul %s (fun x -> PPBCVLI.bounded_bcvli_size %d %d x) (LP.serialize_list _ %s)\n" smin smin smax smax (scombinator_length_header_name lenty smin smax) smin smax (scombinator_name ty);
    wp o "       (PPLS.l2r_safe_size_list %s %s ())) <: PPB.l2r_safe_size _ %s'_serializer _)\n" (scombinator_name ty) (copyful_size_name ty) n;
    wp o "    synth_%s synth_%s_recip\n\n" n n;
    register_size n
  end

(* Emit a copyful parser (read_<n>) and free (free_<n>) for a length-framed
   SINGLE payload [t payload[len]] (compile_vldata's fits_in_bounds branch):
   one [ty] value whose serialization occupies exactly [len] bytes, framed by a
   length-header parser ([parse_vlgen smin smax lenheader serializer_ty]). The
   generated high type [<n>] is a plain alias of [ty], and
   [parse_vlgen = parse_bounded_vlgen `parse_synth` synth_vlgen] (synth_vlgen is
   the identity that merely drops the byte-length refinement). So the copyful
   parser is the vlgen-payload combinator (whose vmatch is
   [PPVD.vmatch_vldata_strong], free [PPVD.free_vldata_strong]) lifted across the
   library [synth_vlgen]/[synth_vlgen_recip] iso. The low representation is the
   payload type's own [<ty>_lowtype]/[<ty>_vmatch] (the framing changes neither
   the high value nor its representation). [lenty] is the length-header repr. *)
let emit_copyful_vlgen_payload o i n ty smin smax lenty =
  wp i "let %s_lowtype = %s\n\n" n (copyful_lowtype_name ty);
  wp i "noextract let %s_mid = %s\n\n" n (copyful_mid_name ty);
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop =\n" n n n;
  wp i "  PPVD.vmatch_vldata_strong %d %d %s %s\n\n" smin smax (scombinator_name ty) (copyful_vmatch_name ty);
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) =\n" n n n;
  wp i "  PPC.synth_conv (PPVD.vldata_strong_conv %d %d %s %s) (LP.synth_vlgen %d %d %s)\n\n" smin smax (scombinator_name ty) (copyful_conv_name ty) smin smax (scombinator_name ty);
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "\nlet %s_copyful_synth_injective () : Lemma (LP.synth_injective (LP.synth_vlgen %d %d %s)) = ()\n\n" n smin smax (scombinator_name ty);
  wp o "let %s_copyful_synth_inverse () : Lemma (LP.synth_inverse (LP.synth_vlgen %d %d %s) (LP.synth_vlgen_recip %d %d %s)) = ()\n\n" n smin smax (scombinator_name ty) smin smax (scombinator_name ty);
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n" n n n n;
  wp o "  %s_copyful_synth_injective ();\n" n;
  wp o "  %s_copyful_synth_inverse ();\n" n;
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_length_header_name lenty smin smax);
  wp o "  PPC.copyful_parse_synth\n";
  wp o "    (PPVG.copyful_parse_bounded_vlgen_payload %d %d %s %s %s %s ())\n" smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax) (scombinator_name ty) (copyful_read_name ty);
  wp o "    (LP.synth_vlgen %d %d %s) (LP.synth_vlgen_recip %d %d %s)\n\n" smin smax (scombinator_name ty) smin smax (scombinator_name ty);
  wp o "let free_%s : PPB.free_t %s_vmatch =\n" n n;
  wp o "  PPVD.free_vldata_strong %d %d %s %s\n\n" smin smax (scombinator_name ty) (copyful_free_name ty);
  (* Pulse: copyful safe WRITER/SIZE for a length-framed SINGLE payload. The
     payload bytes are exactly [serialize <ty>] so the vlgen-payload combinator
     writes the length header then the element via its own safe writer/size,
     lifted across the library synth_vlgen iso (identity on values). Supported
     length headers: bitcoin_varint (bcvli), asn1_len/asn1_len8 (DER). *)
  if !emit_pulse && pulse_length_header_writable lenty && copyful_writer_available ty then begin
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  %s_copyful_synth_injective ();\n" n;
    wp o "  %s_copyful_synth_inverse ();\n" n;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_length_header_name lenty smin smax);
    wp o "  PPC.l2r_safe_writer_synth\n";
    wp o "    ((PPVG.l2r_safe_writer_bounded_vlgen_payload %d %dul %d %dul %s %s %s %s %s %s) <: PPB.l2r_safe_writer _ (LP.serialize_bounded_vlgen %d %d %s %s) _)\n" smin smin smax smax (scombinator_length_header_name lenty smin smax) (pulse_size_length_header_name lenty smin smax) (pulse_leaf_writer_length_header_name lenty smin smax) (scombinator_name ty) (copyful_writer_name ty) (copyful_size_name ty) smin smax (scombinator_length_header_name lenty smin smax) (scombinator_name ty);
    wp o "    (LP.synth_vlgen %d %d %s) (LP.synth_vlgen_recip %d %d %s)\n\n" smin smax (scombinator_name ty) smin smax (scombinator_name ty);
    register_writer n
  end;
  if !emit_pulse && pulse_length_header_writable lenty && copyful_size_available ty then begin
    wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  %s_copyful_synth_injective ();\n" n;
    wp o "  %s_copyful_synth_inverse ();\n" n;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_length_header_name lenty smin smax);
    wp o "  PPC.l2r_safe_size_synth\n";
    wp o "    ((PPVG.l2r_safe_size_bounded_vlgen_payload %d %dul %d %dul %s %s %s %s) <: PPB.l2r_safe_size _ (LP.serialize_bounded_vlgen %d %d %s %s) _)\n" smin smin smax smax (scombinator_length_header_name lenty smin smax) (pulse_size_length_header_name lenty smin smax) (scombinator_name ty) (copyful_size_name ty) smin smax (scombinator_length_header_name lenty smin smax) (scombinator_name ty);
    wp o "    (LP.synth_vlgen %d %d %s) (LP.synth_vlgen_recip %d %d %s)\n\n" smin smax (scombinator_name ty) smin smax (scombinator_name ty);
    register_size n
  end

(* Like emit_copyful_vlgen_payload, but for the case where the payload type [ty]
   may exceed the length bounds, so compile_vldata's else-branch generates a
   REFINED high type [<n> = x:ty{ smin <= bytesize x <= smax }] together with
   generated identity coercions [synth_<n>]/[synth_<n>_recip] between [<n>] and
   the byte-length-refined payload [<n>' = parse_bounded_vldata_strong_t]. The
   low representation/vmatch is the payload type's own (the framing changes
   neither the high value nor its representation); we lift the vlgen-payload
   copyful parser across the generated [synth_<n>]/[synth_<n>_recip] iso. *)
let emit_copyful_vlgen_payload_refined o i n ty smin smax lenty =
  wp i "let %s_lowtype = %s\n\n" n (copyful_lowtype_name ty);
  wp i "noextract let %s_mid = %s\n\n" n (copyful_mid_name ty);
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop =\n" n n n;
  wp i "  PPVD.vmatch_vldata_strong %d %d %s %s\n\n" smin smax (scombinator_name ty) (copyful_vmatch_name ty);
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) =\n" n n n;
  wp i "  PPC.synth_conv (PPVD.vldata_strong_conv %d %d %s %s) synth_%s\n\n" smin smax (scombinator_name ty) (copyful_conv_name ty) n;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "\nlet %s_copyful_synth_injective () : Lemma (LP.synth_injective synth_%s) = ()\n\n" n n;
  wp o "let %s_copyful_synth_inverse () : Lemma (LP.synth_inverse synth_%s synth_%s_recip) = ()\n\n" n n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n" n n n n;
  wp o "  %s_copyful_synth_injective ();\n" n;
  wp o "  %s_copyful_synth_inverse ();\n" n;
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_length_header_name lenty smin smax);
  wp o "  PPC.copyful_parse_synth\n";
  wp o "    (PPVG.copyful_parse_bounded_vlgen_payload %d %d %s %s %s %s ())\n" smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax) (scombinator_name ty) (copyful_read_name ty);
  wp o "    synth_%s synth_%s_recip\n\n" n n;
  wp o "let free_%s : PPB.free_t %s_vmatch =\n" n n;
  wp o "  PPVD.free_vldata_strong %d %d %s %s\n\n" smin smax (scombinator_name ty) (copyful_free_name ty);
  (* Pulse: copyful safe WRITER/SIZE for the refined single payload. Analogous to
     emit_copyful_vlgen_payload but lifted across the generated synth_<n> iso
     (over the byte-length-refined high type) rather than the library synth_vlgen. *)
  if !emit_pulse && pulse_length_header_writable lenty && copyful_writer_available ty then begin
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  %s_copyful_synth_injective ();\n" n;
    wp o "  %s_copyful_synth_inverse ();\n" n;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_length_header_name lenty smin smax);
    wp o "  PPC.l2r_safe_writer_synth\n";
    wp o "    ((PPVG.l2r_safe_writer_bounded_vlgen_payload %d %dul %d %dul %s %s %s %s %s %s) <: PPB.l2r_safe_writer _ %s'_serializer _)\n" smin smin smax smax (scombinator_length_header_name lenty smin smax) (pulse_size_length_header_name lenty smin smax) (pulse_leaf_writer_length_header_name lenty smin smax) (scombinator_name ty) (copyful_writer_name ty) (copyful_size_name ty) n;
    wp o "    synth_%s synth_%s_recip\n\n" n n;
    register_writer n
  end;
  if !emit_pulse && pulse_length_header_writable lenty && copyful_size_available ty then begin
    wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  %s_copyful_synth_injective ();\n" n;
    wp o "  %s_copyful_synth_inverse ();\n" n;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_length_header_name lenty smin smax);
    wp o "  PPC.l2r_safe_size_synth\n";
    wp o "    ((PPVG.l2r_safe_size_bounded_vlgen_payload %d %dul %d %dul %s %s %s %s) <: PPB.l2r_safe_size _ %s'_serializer _)\n" smin smin smax smax (scombinator_length_header_name lenty smin smax) (pulse_size_length_header_name lenty smin smax) (scombinator_name ty) (copyful_size_name ty) n;
    wp o "    synth_%s synth_%s_recip\n\n" n n;
    register_size n
  end

(* Copyful for a length-framed SINGLE payload [t x[len]] where the length [len]
   is a plain fixed-size integer field (uint8/uint16/uint24), routed to the
   non-bounded-length-parser branch using [parse_bounded_vldata] (fixed
   log256-derived header). The generated high type [<n>] is a plain alias of
   [ty] and [parse_bounded_vldata] returns [ty] directly (no refinement, no
   synth), so the library [PPVD.copyful_parse_bounded_vldata_payload] produces a
   copyful parser with the payload's OWN vmatch/free unchanged. We re-export the
   payload's [<ty>_lowtype]/[<ty>_vmatch] under the [<n>_*] names so the
   enclosing struct's copyful composition resolves. *)
let emit_copyful_bounded_vldata_payload o i n ty smax =
  wp i "let %s_lowtype = %s\n\n" n (copyful_lowtype_name ty);
  wp i "noextract let %s_mid = %s\n\n" n (copyful_mid_name ty);
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop = %s\n\n" n n n (copyful_vmatch_name ty);
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) = %s\n\n" n n n (copyful_conv_name ty);
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n" n n n n;
  wp o "  PPVD.copyful_parse_bounded_vldata_payload 0 %d %s (PPBI.leaf_read_bounded_integer_%d ())\n\n" smax (copyful_read_name ty) (log256 smax);
  wp o "let free_%s : PPB.free_t %s_vmatch = %s\n\n" n n (copyful_free_name ty);
  if !emit_pulse && copyful_writer_available ty then begin
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  PPVD.l2r_safe_writer_bounded_vldata_payload 0 0ul %d %dul %d %dsz %s %s\n\n" smax smax (log256 smax) (log256 smax) (scombinator_name ty) (copyful_writer_name ty);
    register_writer n
  end

(* Like emit_copyful_bounded_vldata_payload but for the over-bounds case where a
   refined high type [<n> = x:ty{ 0 <= bytesize x <= smax }] and generated
   identity coercions [synth_<n>]/[synth_<n>_recip] are produced over the strong
   parser [parse_bounded_vldata_strong]. We lift
   [PPVD.copyful_parse_bounded_vldata_strong_payload] (vmatch=vmatch_vldata_strong,
   free=free_vldata_strong) across the generated synth iso. *)
let emit_copyful_bounded_vldata_payload_refined o i n ty smax =
  wp i "let %s_lowtype = %s\n\n" n (copyful_lowtype_name ty);
  wp i "noextract let %s_mid = %s\n\n" n (copyful_mid_name ty);
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop =\n" n n n;
  wp i "  PPVD.vmatch_vldata_strong %d %d %s %s\n\n" 0 smax (scombinator_name ty) (copyful_vmatch_name ty);
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) =\n" n n n;
  wp i "  PPC.synth_conv (PPVD.vldata_strong_conv %d %d %s %s) synth_%s\n\n" 0 smax (scombinator_name ty) (copyful_conv_name ty) n;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "\nlet %s_copyful_synth_injective () : Lemma (LP.synth_injective synth_%s) = ()\n\n" n n;
  wp o "let %s_copyful_synth_inverse () : Lemma (LP.synth_inverse synth_%s synth_%s_recip) = ()\n\n" n n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n" n n n n;
  wp o "  %s_copyful_synth_injective ();\n" n;
  wp o "  %s_copyful_synth_inverse ();\n" n;
  wp o "  PPC.copyful_parse_synth\n";
  wp o "    (PPVD.copyful_parse_bounded_vldata_strong_payload %d %d %s %s (PPBI.leaf_read_bounded_integer_%d ()))\n" 0 smax (scombinator_name ty) (copyful_read_name ty) (log256 smax);
  wp o "    synth_%s synth_%s_recip\n\n" n n;
  wp o "let free_%s : PPB.free_t %s_vmatch =\n" n n;
  wp o "  PPVD.free_vldata_strong %d %d %s %s\n\n" 0 smax (scombinator_name ty) (copyful_free_name ty);
  if !emit_pulse && copyful_writer_available ty then begin
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  %s_copyful_synth_injective ();\n" n;
    wp o "  %s_copyful_synth_inverse ();\n" n;
    wp o "  PPC.l2r_safe_writer_synth\n";
    wp o "    ((PPVD.l2r_safe_writer_bounded_vldata_strong_payload %d %dul %d %dul %d %dsz %s %s) <: PPB.l2r_safe_writer _ %s'_serializer _)\n" 0 0 smax smax (log256 smax) (log256 smax) (scombinator_name ty) (copyful_writer_name ty) n;
    wp o "    synth_%s synth_%s_recip\n\n" n n;
    register_writer n
  end

(* Emit copyful parser (read_<n>) and free (free_<n>) for a fixed-BYTE-length
   container of variable-length elements [t x[k]] (the VectorFixed branch). The
   payload is a list of [ty] elements occupying exactly [k] bytes
   (parse_fldata_strong of serialize_list). The low representation is the same
   [PPVCL.vclist_lowtype <elem_lowtype>] used for vclist/list, and the underlying
   vmatch is [PPVCL.vmatch_vclist] applied to the element values (the fldata
   framing changes neither the high value nor its representation). The generated
   refined type [<n>] and the payload type [parse_fldata_strong_t] (= [<n>']) are
   only propositionally equal (via [<n>_eq]), so we re-index the
   FLData-payload copyful parser/free from [<n>'] to [<n>] using the value-level
   PPB.copyful_parse_ext / PPB.free_ext combinators (which discharge first-order
   type/parser/vmatch extensionality obligations rather than coercing the
   dependent copyful_parse/free_t types). *)
let emit_copyful_vectorfixed_list o i n ty k =
  wp i "let %s_lowtype = PPVCL.vclist_lowtype %s\n\n" n (copyful_lowtype_name ty);
  wp i "noextract let %s_mid = list %s\n\n" n (compile_type ty);
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop =\n" n n n;
  wp i "  PPVCL.vmatch_vclist (PPB.vmatch_conv %s %s)\n\n" (copyful_vmatch_name ty) (copyful_conv_name ty);
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) =\n" n n n;
  wp i "  %s_eq (); PPFD.fldata_strong_conv (LP.serialize_list _ %s) %d (fun (x: list %s) -> FStar.Pervasives.Native.Some x)\n\n" n (scombinator_name ty) k (compile_type ty);
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n" n n n n;
  wp o "  %s_eq ();\n" n;
  wp o "  PPB.copyful_parse_ext\n";
  wp o "    (PPFD.copyful_parse_fldata_strong_payload (LP.serialize_list _ %s) %d\n" (scombinator_name ty) k;
  wp o "       (PPLS.copyful_parse_list %s %s ()))\n" (copyful_read_name ty) (pulse_jumper_name ty);
  wp o "    %s_parser %s_vmatch ()\n\n" n n;
  wp o "let free_%s : PPB.free_t %s_vmatch =\n" n n;
  wp o "  %s_eq ();\n" n;
  wp o "  PPB.free_ext\n";
  wp o "    (PPFD.free_fldata_strong (LP.serialize_list _ %s) %d (PPVCL.free_vclist (PPB.free_vmatch_conv %s %s %s)))\n" (scombinator_name ty) k (copyful_vmatch_name ty) (copyful_conv_name ty) (copyful_free_name ty);
  wp o "    %s_vmatch ()\n\n" n;
  if !emit_pulse && copyful_writer_available ty then begin
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  %s_eq ();\n" n;
    wp o "  PPB.l2r_safe_writer_ext\n";
    wp o "    ((PPFD.l2r_safe_writer_fldata_strong_payload (LP.serialize_list _ %s) %d %dsz\n" (scombinator_name ty) k k;
    wp o "       (PPLS.l2r_safe_writer_list %s %s ())) <: PPB.l2r_safe_writer _ %s'_serializer _)\n" (scombinator_name ty) (copyful_writer_name ty) n;
    wp o "    %s_serializer %s_vmatch ()\n\n" n n;
    register_writer n
  end

(* Emit copyful parser (read_<n>) and free (free_<n>) for an explicit-length
   array [t x[len]] / count-bounded list of fixed-size elements (the vlarray
   case: VectorRange with elem_li.min_len = elem_li.max_len). The high type
   [<n>] is [LP.vlarray ty min_count max_count] and [<n>_parser =
   LP.parse_vlarray low high elem_ser min_count max_count ()], which unfolds to
   [parse_bounded_vldata_strong low high (serialize_list _ elem_ser)
   `parse_synth` vldata_to_vlarray ...]. So this is the same byte-length-framed
   list as emit_copyful_vldata_list, with the synth pair being the library
   functions [vldata_to_vlarray] / [vlarray_to_vldata] (count refinement only,
   identity on the underlying list). The low representation is the shared
   [PPVCL.vclist_lowtype <elem_lowtype>]. [low]/[high] are the byte-length frame
   bounds; [mn]/[mx] are the element-count bounds. *)
let emit_copyful_vlarray o i n ty low high mn mx =
  wp i "let %s_lowtype = PPVCL.vclist_lowtype %s\n\n" n (copyful_lowtype_name ty);
  wp i "noextract let %s_mid = list %s\n\n" n (compile_type ty);
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop =\n" n n n;
  wp i "  PPVD.vmatch_vldata_strong %d %d (LP.serialize_list _ %s) (PPVCL.vmatch_vclist (PPB.vmatch_conv %s %s))\n\n" low high (scombinator_name ty) (copyful_vmatch_name ty) (copyful_conv_name ty);
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) =\n" n n n;
  wp i "  PPC.synth_conv (PPVD.vldata_strong_conv %d %d (LP.serialize_list _ %s) (fun (x: list %s) -> FStar.Pervasives.Native.Some x)) (LP.vldata_to_vlarray %d %d %s %d %d ())\n\n" low high (scombinator_name ty) (compile_type ty) low high (scombinator_name ty) mn mx;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n" n n n n;
  wp o "  LP.vldata_to_vlarray_inj %d %d %s %d %d ();\n" low high (scombinator_name ty) mn mx;
  wp o "  LP.vlarray_to_vldata_to_vlarray %d %d %s %d %d ();\n" low high (scombinator_name ty) mn mx;
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
  wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
  wp o "  PPC.copyful_parse_synth\n";
  wp o "    (PPVD.copyful_parse_bounded_vldata_strong_payload %d %d (LP.serialize_list _ %s)\n" low high (scombinator_name ty);
  wp o "       (PPLS.copyful_parse_list %s %s ())\n" (copyful_read_name ty) (pulse_jumper_name ty);
  wp o "       (PPBI.leaf_read_bounded_integer_%d ()))\n" (log256 high);
  wp o "    (LP.vldata_to_vlarray %d %d %s %d %d ())\n" low high (scombinator_name ty) mn mx;
  wp o "    (LP.vlarray_to_vldata %d %d %s %d %d ())\n\n" low high (scombinator_name ty) mn mx;
  wp o "let free_%s : PPB.free_t %s_vmatch =\n" n n;
  wp o "  PPVD.free_vldata_strong %d %d (LP.serialize_list _ %s) (PPVCL.free_vclist (PPB.free_vmatch_conv %s %s %s))\n\n" low high (scombinator_name ty) (copyful_vmatch_name ty) (copyful_conv_name ty) (copyful_free_name ty);
  if !emit_pulse && copyful_writer_available ty then begin
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  LP.vldata_to_vlarray_inj %d %d %s %d %d ();\n" low high (scombinator_name ty) mn mx;
    wp o "  LP.vlarray_to_vldata_to_vlarray %d %d %s %d %d ();\n" low high (scombinator_name ty) mn mx;
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_subkind == Some LP.ParserStrong);\n" (pcombinator_name ty);
    wp o "  assert_norm ((LP.get_parser_kind %s).LP.parser_kind_low > 0);\n" (pcombinator_name ty);
    wp o "  PPC.l2r_safe_writer_synth\n";
    wp o "    ((PPVD.l2r_safe_writer_bounded_vldata_strong_payload %d %dul %d %dul %d %dsz (LP.serialize_list _ %s)\n" low low high high (log256 high) (log256 high) (scombinator_name ty);
    wp o "       (PPLS.l2r_safe_writer_list %s %s ())) <: PPB.l2r_safe_writer _ (LP.serialize_bounded_vldata_strong %d %d (LP.serialize_list _ %s)) _)\n" (scombinator_name ty) (copyful_writer_name ty) low high (scombinator_name ty);
    wp o "    (LP.vldata_to_vlarray %d %d %s %d %d ())\n" low high (scombinator_name ty) mn mx;
    wp o "    (LP.vlarray_to_vldata %d %d %s %d %d ())\n\n" low high (scombinator_name ty) mn mx;
    register_writer n
  end

let add_field al (tn:typ) (n:field) (ty:type_t) (v:vector_t) =
  let qname = if tn = "" then n else tn^"@"^n in
  let li = sizeof ty in
  let li' =
    if has_attr al "implicit" then sizeof (TypeSimple "Empty") else
    match v with
    | VectorNone -> li
    | VectorFixed k ->
      {li with
        min_len = k;
        max_len = k;
        min_count = k / li.min_len;
        max_count = k / li.max_len;
        meta = (if li.meta = MetadataFail || li.min_len = li.max_len then li.meta else MetadataDefault);
        has_lserializer = false;
      }
    | VectorFixedCount k ->
      { li with
        min_count = k;
        max_count = k;
        min_len = k * li.min_len;
        max_len = k * li.max_len;
        meta = (if li.meta = MetadataFail || li.min_len = li.max_len then li.meta else MetadataDefault);
        has_lserializer = false;
      }
    | VectorVldata tn ->
      let (len_len_min, len_len_max, max_len) = basic_bounds tn in
      let (li_min_len, li_max_len) =
        if ty = TypeSimple "opaque" then (0, assume_some max_len)
        else (li.min_len, li.max_len) in
      let max' = len_len_max + min (assume_some max_len) li_max_len in
      (*let min', max' = li.min_len, min li.max_len max_len in*)
      let meta' = if li.meta = MetadataFail then li.meta else MetadataDefault in
      {li with len_len = len_len_min; min_len = len_len_min + li_min_len; max_len = max'; vl = true; has_lserializer = false; meta = meta' }
    | VectorSymbolic cst ->
      if tn = "" then failwith "Can't define a symbolic bytelen outide struct";
      let li' = get_leninfo (tn^"@"^cst) in
      (* Important: must reflect parse_bounded_vldata_strong_kind computation *)
      let max' = min li.max_len (match li'.max_len with
      | 1 -> 255 | 2 ->  65535 | 3 -> 16777215 | 4 -> 4294967295
      | _ -> failwith "bad vldata") in
      let meta' = if li.meta = MetadataFail then li.meta else MetadataDefault in
      (* N.B. the len_len will be counted in the explicit length field *)
      {li' with vl = true; len_len = 0; min_len = li.min_len; max_len = max'; has_lserializer = false; meta = meta' }
    | VectorCount (low, high, repr) ->
      let (l, h, meta) = match repr with
        | None -> let x = log256 high in (x, x, MetadataTotal)
        | Some t ->
          let (l, h, _) = basic_bounds t in
          let len_li = sizeof (TypeSimple t) in
          (l, h, len_li.meta)
        in
      { vl = true;
        min_count = low;
        max_count = high;
        len_len = h;
        min_len = l + low * li.min_len;
        max_len = h + high * li.max_len;
        has_lserializer = false;
        meta = match li.meta with (* See parse_vclist_payload_kind *)
               | MetadataFail -> li.meta
               | d -> if high = 0 then meta else MetadataDefault;
      }
    | VectorRange (low, high, repr) ->
      let l, h = match repr with
        | None -> let z = log256 high in (z, z)
        | Some t ->
           if has_bounded_length_parsers t
           then (size_of_bounded_length low t, size_of_bounded_length high t)
           else 
             let (l, h, _) = basic_bounds t in
             (l, h)
      in
      (if h < log256 high then failwith (sprintf "Can't represent <%d..%d> over %d bytes" low high h));
      (if li.len_len + li.max_len = 0 then failwith ("Can't compute count bound on "^tn));
      { vl = true;
        min_count = low / (li.len_len + li.max_len);
        max_count = high / (li.len_len + li.min_len);
        len_len = h;
        min_len = l + low;
        max_len = h + high;
        has_lserializer = false;
        meta = if li.meta = MetadataFail then li.meta else MetadataDefault;
      } in
    li_add qname li'

let typedep = function
  | TypeSimple ty -> [ty]
  | TypeIfeq (tag, v, _, t, _, f) -> [t; f]
  | TypeSelect (_, l, o) ->
    let l = List.map (fun (_, ty)->ty) l in
    match o with None -> l | Some ty -> ty :: l

let dedup l =
  let r = ref [] in
  List.iter (fun x -> if not (List.mem x !r) then r := x::!r) l;
  List.rev !r

let getdep (toplevel:bool) (p:gemstone_t) : typ list =
  let tn = tname toplevel p in
  let dep =
    match p with
    | Abstract (attrs, _, min, max, _) ->
      let li = { len_len = 0; min_len = min; max_len = max; min_count = 0; max_count = 0; vl = (min <> max); meta = MetadataDefault; has_lserializer = has_attr attrs "has_lserializer"; } in
      li_add tn li;
      ([]:typ list list)
    | Enum (a, fl, n) ->
      if not toplevel then failwith "Invalid internal rewrite of an enum";
      let meta = if has_attr a "open" then MetadataTotal else MetadataDefault in
      let m = try List.find (function EnumFieldAnonymous x -> true | _ -> false) fl
              with _ -> failwith ("Enum "^n^" is missing a representation hint") in
      let li = { len_len = 0; min_len = 0; max_len = 0; min_count = 0; max_count = 0;  vl = false; has_lserializer = true; meta = meta; } in
      (match m with
      | EnumFieldAnonymous 255 -> li.min_len <- 1; li.max_len <- 1
      | EnumFieldAnonymous 65535 -> li.min_len <- 2; li.max_len <- 2
      | EnumFieldAnonymous 4294967295 -> li.min_len <- 4; li.max_len <- 4
      | EnumFieldAnonymous d -> failwith ("unsupported enum representation: "^string_of_int d)
      | _ -> failwith "impossible");
      li_add tn li; ([]:typ list list)
    | Struct (_, [(al, ty, _, vec, def)], n)
    | Typedef (al, ty, n, vec, def) ->
      if toplevel then add_field al "" (String.uncapitalize_ascii n) ty vec;
      [typedep ty]
    | Struct (_, fl, _) ->
      if not toplevel then failwith "invalid internal rewrite of a struct";
      let li = { len_len = 0; min_len = 0; max_len = 0; min_count = 0; max_count = 0;  vl = false; has_lserializer = true; meta = MetadataTotal } in
      let dep = List.map (fun (al, ty, n, vec, def) ->
        add_field al tn n ty vec;
        let lif = get_leninfo (tn^"@"^n) in
        li.min_len <- li.min_len + lif.min_len;
        li.max_len <- li.max_len + lif.max_len;
        if lif.meta = MetadataDefault then li.meta <- MetadataDefault;
        li.has_lserializer <- li.has_lserializer && lif.has_lserializer;
        typedep ty) fl in
      li_add tn li; dep
    in
  dedup (List.flatten dep)

let need_validator (md: parser_kind_metadata) bmin bmax =
  match md with
  | MetadataTotal -> bmin <> bmax
  | _ -> true

let need_jumper bmin bmax =
  bmin <> bmax

let get_api_params p n =
  let (* (parg, ptyp, pparse, pser) as *) res = match p with
    | None -> "", n, sprintf "%s_parser" n, sprintf "%s_serializer" n
    | Some t ->
      sprintf " (k:%s)" (compile_type t), sprintf "(%s k)" n,
      sprintf "(%s_parser k)" n, sprintf "(%s_serializer k)" n
    in
  res

let write_bytesize o ?param:(p=None) is_private n =
  let (parg, ptyp, pparse, pser) = get_api_params p n in
  if is_private then ()
  else
    if p = None then begin
        (* Under -pulse the bytesize defining function is emitted transparently in
           the interface (see write_api), so generated refinement types stay
           definitionally equal to their parse_bounded_vldata_strong_t form. *)
        if not !emit_pulse then
          w o "let %s_bytesize (x:%s) : GTot nat = Seq.length (%s x)\n\n" n n pser;
        w o "let %s_bytesize_eq x = ()\n\n" n;
    end else begin
        if not !emit_pulse then
          w o "let %s_bytesize%s (x:%s k) : GTot nat = let s = %s in Seq.length (s x)\n\n" n parg n pser;
        w o "let %s_bytesize_eq k x = ()\n\n" n;
    end

let write_api o i ?param:(p=None) has_lserializer is_private (md: parser_kind_metadata) n bmin bmax =
  let (parg, ptyp, pparse, pser) = get_api_params p n in
  let parser_kind = match md with
    | MetadataTotal   -> "(Some LP.ParserKindMetadataTotal)"
    | MetadataFail -> "(Some LP.ParserKindMetadataFail)"
    | MetadataDefault -> "None"
    in
  w i "inline_for_extraction noextract let %s_parser_kind = LP.strong_parser_kind %d %d %s\n\n" n bmin bmax parser_kind;
  w i "noextract val %s_parser%s: LP.parser %s_parser_kind %s\n\n" n parg n ptyp;
  if is_private then ()
  else
   begin
    w i "noextract val %s_serializer%s: LP.serializer %s\n\n" n parg pparse;
    if p = None then begin
      if !emit_pulse then
        w i "noextract let %s_bytesize (x:%s) : GTot nat = Seq.length (LP.serialize %s x)\n\n" n n pser
      else
        w i "noextract val %s_bytesize (x:%s) : GTot nat\n\n" n n;
      w i "noextract val %s_bytesize_eq (x:%s) : Lemma (%s_bytesize x == Seq.length (LP.serialize %s x))\n\n" n n n pser;
      ()
    end else begin
      if !emit_pulse then
        w i "noextract let %s_bytesize%s (x:%s k) : GTot nat = let s = %s in Seq.length (LP.serialize s x)\n\n" n parg n pser
      else
        w i "noextract val %s_bytesize%s (x:%s k) : GTot nat\n\n" n parg n;
      w i "noextract val %s_bytesize_eq%s (x: %s k) : Lemma (%s_bytesize k x == Seq.length (LP.serialize (%s) x))\n\n" n parg n n pser;
      ()
    end;
    wh i "val %s_parser32%s: LS.parser32 %s\n\n" n parg pparse;
    wh i "val %s_serializer32%s: LS.serializer32 %s\n\n" n parg pser;
    ws has_lserializer i "val %s_size32%s: LSZ.size32 %s\n\n" n parg pser;
    begin if has_lserializer && !emit_eq
    then match p with
    | None -> w i "let %s_equals (x1 x2: %s) : Tot bool = x1 = x2\n\n" n n
    | _ -> w i "let %s_equals%s (x1 x2: %s k) : Tot bool = x1 = x2\n\n" n parg n
    end;
    if need_validator md bmin bmax then
      wl i "val %s_validator%s: LL.validator %s\n\n" n parg pparse
    else
      wl i "let %s_validator%s: LL.validator %s = LL.validate_total_constant_size %s %duL ()\n\n" n parg pparse pparse bmin;
    if need_jumper bmin bmax then
      wl i "val %s_jumper%s: LL.jumper %s\n\n" n parg pparse
    else
      wl i "let %s_jumper%s: LL.jumper %s = LL.jump_constant_size %s %dul ()\n\n" n parg pparse pparse bmin;
    (* Pulse validators and jumpers *)
    if need_validator md bmin bmax then
      wp i "val %s_validator%s: LPS.validator %s\n\n" n parg pparse
    else
      wp i "let %s_validator%s: LPS.validator %s = LPS.validate_total_constant_size %s %dsz\n\n" n parg pparse pparse bmin;
    if need_jumper bmin bmax then
      wp i "val %s_jumper%s: LPS.jumper %s\n\n" n parg pparse
    else
      wp i "let %s_jumper%s: LPS.jumper %s = LPS.jump_constant_size %s %dsz\n\n" n parg pparse pparse bmin;
    ()
   end
     
  
(* Emit the if-then-else discriminant tag as a dedicated, spec-only, Seq-based
   fixed-length-bytes type [tagt = Seq.lseq FStar.UInt8.t clen]. Unlike the
   generic [opaque[clen]] typedef it does NOT use FStar.Bytes, so the discriminant
   constant can be built by a total [Seq.seq_of_list] (no [assume]). Emits the
   spec parser/serializer (over [parse_lseq_bytes]/[serialize_lseq_bytes]),
   write_api declarations, bytesize, and—under -pulse—the copyful tag block via
   [emit_copyful_seqbytes]. The SLow/Low [parser32]/[validator] declarations from
   [write_api] are left undefined on purpose: if-then-else is -pulse only (guarded
   elsewhere), and under -pulse those [wh]/[wl] writes are no-ops. *)
let compile_ite_tag o i tagt clen is_private =
  (* Under -pulse the executable tag representation is the Vec-based lowtype
     ([<tagt>_lowtype = PPBY.lvec uint8]); the high [Seq.lseq uint8 clen] type is
     referenced only by noextract/GTot specs and phantom parser indices, so mark
     it noextract to avoid a [Prims_list__uint8_t] cons-list typedef in the
     extracted C.  if-then-else is -pulse-only, but gate defensively. *)
  w i "%stype %s = Seq.lseq FStar.UInt8.t %d\n\n" (if !emit_pulse then "noextract " else "") tagt clen;
  write_api o i false is_private MetadataTotal tagt clen clen;
  w o "noextract let %s_parser = LP.parse_lseq_bytes %d\n\n" tagt clen;
  w o "noextract let %s_serializer = LP.serialize_lseq_bytes %d\n\n" tagt clen;
  write_bytesize o is_private tagt;
  w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == Seq.length x) [SMTPat (%s_bytesize x)]\n\n" tagt tagt tagt tagt;
  w o "let %s_bytesize_eqn x = ()\n\n" tagt;
  if !emit_pulse then emit_copyful_seqbytes o i tagt clen

(* binary trees to compile struct fields into log nesting instead of a comb *)

type 'a btree =
  | TLeaf of 'a
  | TNode of (int * ('a btree) * ('a btree))

let rec btree_count (t: 'a btree) =
  match t with
  | TLeaf _ -> 1
  | TNode (n, _, _) -> n

let rec btree_insert (t: 'a btree) (x: 'a) =
  (* always insert to the right-hand-side, leaving the left-hand-side complete *)
  match t with
  | TLeaf y -> TNode (2, t, TLeaf x)
  | TNode (n, left, right) ->
     if btree_count left = btree_count right
     then TNode (n + 1, t, TLeaf x)
     else TNode (n + 1, left, btree_insert right x)

let rec btree_fold
          (f: 'global -> 'local -> 'elem -> 'global) pushl plpr popr (* : 'global -> 'global *) left right (* : 'local -> 'local *) (ginit: 'global) (linit: 'local) (t: 'elem btree) : 'global =
  match t with
  | TLeaf x -> f ginit linit x
  | TNode (_, tleft, tright) ->
     let g1 = btree_fold f pushl plpr popr left right (pushl ginit) (left linit) tleft in
     let g2 = btree_fold f pushl plpr popr left right (plpr g1) (right linit) tright in
     popr g2
  
let type_channel tch i = match tch with
  | None -> i
  | Some tch -> tch

(* Emit the copyful (owned read/free/write/size + lowtype/mid/vmatch/conv)
   interface for an if-then-else type [n] (tag type [tagt]; branch payload types
   [tt] for the true arm, [tf] for the false arm), routed through the
   LowParse.PulseParse.IfThenElse copyful combinators. This is what lets an
   if-then-else type be used as a field of an enclosing copyful struct (the
   struct's own [_lowtype]/[_vmatch]/[_conv]/[read_]/[free_] compose the field's).
   Mirrors [emit_copyful_seqbytes] (the tag) / [emit_copyful_owned_sum] (a closed
   sum) but over [parse_ifthenelse]/[serialize_ifthenelse].
   REQUIRES [parse_<n>_param] and [<n>_cond] to be in the INTERFACE: the
   transparent [<n>_vmatch]/[<n>_conv] reference them. -pulse-only. *)
let emit_copyful_ite o i n tagt tt tf =
  (* per-branch payload type/vmatch/conv families: payload b = if b then tt else tf *)
  let fam f = sprintf "(fun b -> if b then %s else %s)" (f tt) (f tf) in
  (* When both branches share the same family member (e.g. an if-then-else whose two
     arms have the same payload type, as in TLS ServerHello/HelloRetryRequest), emit a
     CONSTANT [(fun _ -> X)] rather than [(fun b -> if b then X else X)]. This matters
     for the [free_<n>] call below: [free_ifthenelse]'s [vmatch_pl] is not pinned by its
     value arguments (unlike read/write, which carry the [p] param), so leaving it
     implicit makes F* infer a constant [(fun _ -> X)] from the [free_pl] argument. By
     defining [<n>_payload_vmatch] itself as that same constant, the pinned result type
     and the per-branch [free_pl] obligation both hold by beta-reduction alone — no
     [if b then X else X] ite that would otherwise require functional extensionality. *)
  let fam_eq f = if (f tt) = (f tf) then sprintf "(fun _ -> %s)" (f tt) else fam f in
  wp i "let %s_lowtype = LPITE.ite_lowtype %s_lowtype %s\n\n" n tagt (fam_eq copyful_lowtype_name);
  wp i "noextract let %s_mid = LPITE.ite_mid %s_mid %s\n\n" n tagt (fam_eq copyful_mid_name);
  (* Named payload-vmatch family, shared by [<n>_vmatch] and [free_<n>] so the two
     [vmatch_ite ...] terms are syntactically identical (the pinned [vmatch_pl] and the
     one in [<n>_vmatch] are the same name). *)
  wp i "let %s_payload_vmatch = %s\n\n" n (fam_eq copyful_vmatch_name);
  (* Named payload-conv family, pinned in the write/size calls below alongside
     [<n>_payload_vmatch] so their result conv/vmatch are exactly [<n>_conv]/[<n>_vmatch]
     (the constant [fam_eq] form makes the per-branch obligations hold by beta). *)
  wp i "noextract let %s_payload_conv = %s\n\n" n (fam_eq copyful_conv_name);
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop = LPITE.vmatch_ite %s_vmatch %s_cond %s_conv %s_payload_vmatch\n\n" n n n tagt n tagt n;
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) = LPITE.ite_conv parse_%s_param %s_conv %s_payload_conv\n\n" n n n n tagt n;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp o "let read_%s = LPITE.copyful_parse_ifthenelse parse_%s_param %s_jumper %s_test read_%s\n  %s ()\n\n" n n tagt n tagt (fam_eq copyful_read_name);
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  (* Pin tag_t/cond/conv_tag (free_ifthenelse lacks the [p] param that determines them)
     and vmatch_pl to the named [<n>_payload_vmatch], so the result type is exactly
     [<n>_vmatch]. The per-branch [free_pl] obligation discharges by beta-reduction
     because [<n>_payload_vmatch] is the constant [fam_eq] family (see above). *)
  wp o "let free_%s = LPITE.free_ifthenelse #_ #_ #%s #_ #%s_cond #%s_conv #_ #_ #%s_payload_vmatch free_%s\n  %s\n\n" n tagt n tagt n tagt (fam_eq copyful_free_name);
  if copyful_writer_available tt && copyful_writer_available tf then begin
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s = LPITE.l2r_safe_writer_ifthenelse parse_%s_param serialize_%s_param #_ #_ #_ #_ #_ #_ #%s_payload_vmatch #%s_payload_conv write_%s\n  %s\n\n" n n n n n tagt (fam_eq copyful_writer_name);
    register_writer n
  end;
  if copyful_size_available tt && copyful_size_available tf then begin
    wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let size_%s = LPITE.l2r_safe_size_ifthenelse parse_%s_param serialize_%s_param #_ #_ #_ #_ #_ #_ #%s_payload_vmatch #%s_payload_conv size_%s\n  %s\n\n" n n n n n tagt (fam_eq copyful_size_name);
    register_size n
  end

let rec compile_enum tch o i n (fl: enum_field_t list) (al:attr list) =
  let is_open = has_attr al "open" in
  let is_private = has_attr al "private" in
  let is_little_endian = has_attr al "little_endian" in
  fields := SM.add n (fl, is_open) !fields;

  let patch_little_endian s = if not is_little_endian then s else sprintf "%s_le" s in
  let repr_t, int_z, blen =
	  let m = try List.find (function EnumFieldAnonymous x -> true | _ -> false) fl
		        with _ -> failwith ("Enum "^n^" is missing a representation hint") in
	  match m with
		| EnumFieldAnonymous 255 -> "uint8", "z", 1
		| EnumFieldAnonymous 65535 -> patch_little_endian "uint16", "us", 2
		| EnumFieldAnonymous 4294967295 -> patch_little_endian "uint32", "ul", 4
		| _ -> failwith ("Cannot represent enum type "^n^" (only u8, u16, u32, u64 supported)")
	in

  if is_open then
   begin
  	let rec collect_valid_repr int_z acc acc_rparen = function
  	  | [] -> sprintf "%sfalse%s" acc acc_rparen
  		| (EnumFieldAnonymous _) :: t -> collect_valid_repr int_z acc acc_rparen t
  		| (EnumFieldSimple (_, i)) :: t ->
  		  let acc' =
  			  sprintf "%sv `%s_repr_eq` %d%s || (" acc n i int_z in
                    let acc_rparen' = sprintf ")%s" acc_rparen in
  		  collect_valid_repr int_z acc' acc_rparen' t
  		| (EnumFieldRange (_, i, j)) :: t ->
  		  let acc' = acc in (* For now we treat enum ranges as unknown
  			  (if acc = "" then acc else acc^" /\\ ")^
  			  "(v < " ^ (string_of_int i) ^ int_z ^
  				" \\/ v > " ^ (string_of_int j) ^ int_z ^ ")" in *)
                    let acc_rparen' = acc_rparen in
  		  collect_valid_repr int_z acc' acc_rparen' t
  		in
    let unknown_formula = collect_valid_repr int_z "" "" fl in

    w i "let %s_repr = %s\n" n (compile_type repr_t);
    w i "inline_for_extraction let %s_repr_eq (x1 x2: %s_repr) : Tot bool = (x1 = x2)\n" n n;
    w i "let known_%s_repr (v:%s) : bool = %s\n\n" n (compile_type repr_t) unknown_formula
   end;

  if !types_from = "" then begin
	w (type_channel tch i) "type %s =\n" n;
	List.iter (function
	  | EnumFieldSimple (x, _) ->
		  w (type_channel tch i) "  | %s\n" (String.capitalize_ascii x)
		| _ -> ()) fl;
  if is_open then
	  w (type_channel tch i) "  | Unknown_%s of (v:%s{not (known_%s_repr v)})\n\n" n (compile_type repr_t) n
  else w (type_channel tch i) "\n";
  end;

	w i "let string_of_%s = function\n" n;
  List.iter (function
	  | EnumFieldSimple (x, _) ->
		  w i "  | %s -> \"%s\"\n" (String.capitalize_ascii x) x
		| _ -> ()) fl;
  if is_open then
	  w i "  | Unknown_%s _ -> \"Unknown_%s\"\n\n" n n
  else w i "\n";

  (* Enum definition. Under -pulse, emitted to the interface so that transparent
     Pulse vmatch tag-helpers (typed at [enum_key <n>_enum]) can reference it. *)
        let ienum = ipub i o in
	w ienum "[@LT.Norm] inline_for_extraction %slet %s_enum : LP.enum %s %s =\n" (if !emit_pulse then "noextract " else "") n n (compile_type repr_t);
	w ienum "  [@inline_let] let e = [\n";
	List.iter (function
	  | EnumFieldSimple (x, i) ->
		  w ienum "    %s, %d%s;\n" (String.capitalize_ascii x) i int_z
		| _ -> ()) fl;
	w ienum "  ] in\n";
	w ienum "  [@inline_let] let _ =\n";
	w ienum "    assert_norm (L.noRepeats (LP.list_map fst e))\n";
        w ienum "  in\n";
        w ienum "  [@inline_let] let _ = \n";
	w ienum "    assert_norm (L.noRepeats (LP.list_map snd e))\n";
	w ienum "  in e\n\n";

  (* Used in select() *)
  w o "noextract let %s_repr_parser = %s\n\n" n (pcombinator_name repr_t);
  w o "noextract let %s_repr_serializer = %s\n\n" n (scombinator_name repr_t);
  wh o "inline_for_extraction noextract let %s_repr_parser32 = %s\n\n" n (pcombinator32_name repr_t);
  wh o "inline_for_extraction noextract let %s_repr_serializer32 = %s\n\n" n (scombinator32_name repr_t);
  wnp o "inline_for_extraction noextract let %s_repr_size32 = %s\n\n" n (size32_name repr_t);
  wl o "inline_for_extraction noextract let %s_repr_validator = %s\n\n" n (validator_name repr_t);
  wl o "inline_for_extraction noextract let %s_repr_jumper = %s\n\n" n (jumper_name repr_t);
  wl o "inline_for_extraction noextract let %s_repr_reader = %s\n\n" n (leaf_reader_name repr_t);
  wl o "inline_for_extraction noextract let %s_repr_writer = %s\n\n" n (leaf_writer_name repr_t);
  wp o "inline_for_extraction noextract let %s_repr_validator = %s\n\n" n (pulse_validator_name repr_t);
  wp o "inline_for_extraction noextract let %s_repr_jumper = %s\n\n" n (pulse_jumper_name repr_t);
    wp o "inline_for_extraction noextract let %s_repr_reader = %s\n\n" n (pulse_leaf_reader_name repr_t);
  wp o "inline_for_extraction noextract let %s_repr_writer = %s\n\n" n (pulse_leaf_writer_name repr_t);

  write_api o i true is_private (if is_open then MetadataTotal else MetadataDefault) n blen blen;

  (* Synth *)
  if is_open then
   begin
  	w o "inline_for_extraction %slet synth_%s (x:LP.maybe_enum_key %s_enum) : %s = \n" (if !emit_pulse then "noextract " else "") n n n;
  	w o "  match x with\n";
  	w o "  | LP.Known k -> k\n";
  	w o "  | LP.Unknown y ->\n";
  	w o "    [@inline_let] let v : %s = y in\n" (compile_type repr_t);
  	w o "    [@inline_let] let _ = assert_norm (LP.list_mem v (LP.list_map snd %s_enum) == known_%s_repr v) in\n" n n;
    w o "    Unknown_%s v\n\n" n;
  	w o "inline_for_extraction %slet synth_%s_inv (x:%s) : LP.maybe_enum_key %s_enum = \n" (if !emit_pulse then "noextract " else "") n n n;
  	w o "  match x with\n";
  	w o "  | Unknown_%s y ->\n" n;
  	w o "    [@inline_let] let v : %s = y in\n" (compile_type repr_t);
  	w o "    [@inline_let] let _ = assert_norm (LP.list_mem v (LP.list_map snd %s_enum) == known_%s_repr v) in\n" n n;
  	w o "    LP.Unknown v\n";
  	w o "  | x ->\n";
    w o "    [@inline_let] let x1 : %s = x in\n" n;
    w o "    [@inline_let] let _ : squash(not (Unknown_%s? x1) ==> LP.list_mem x1 (LP.list_map fst %s_enum)) =\n" n n;
    w o "      _ by (LP.synth_maybe_enum_key_inv_unknown_tac x1)\n";
    w o "    in\n";
    w o "    LP.Known (x1 <: LP.enum_key %s_enum)\n\n" n;
    w o "let lemma_synth_%s_inv' () : Lemma\n" n;
    w o "  (LP.synth_inverse synth_%s_inv synth_%s)\n" n n;
    w o "= LP.forall_maybe_enum_key %s_enum (fun x -> synth_%s_inv (synth_%s x) == x)\n" n n n;
    w o "    (_ by (LP.forall_maybe_enum_key_known_tac ()))\n";
    w o "    (_ by (LP.forall_maybe_enum_key_unknown_tac ()))\n\n";
  	w o "let lemma_synth_%s_inj () : Lemma\n" n;
  	w o "  (LP.synth_injective synth_%s) = \n" n;
    w o "  lemma_synth_%s_inv' ();\n" n;
    w o "  LP.synth_inverse_synth_injective synth_%s synth_%s_inv\n\n" n n;
    w o "#push-options \"--max_ifuel 0 --initial_ifuel 0 --max_fuel 0 --max_ifuel 0\"\n";
  	w o "let lemma_synth_%s_inv () : Lemma\n" n;
    w o "  (LP.synth_inverse synth_%s synth_%s_inv) = allow_inversion %s; ()\n\n" n n n;
    w o "#pop-options\n";
   end
  else
   begin
    w o "inline_for_extraction %slet synth_%s (x: LP.enum_key %s_enum) : Tot %s = x\n\n" (if !emit_pulse then "noextract " else "") n n n;
    w o "inline_for_extraction %slet synth_%s_inv (x: %s) : Tot (LP.enum_key %s_enum) =\n" (if !emit_pulse then "noextract " else "") n n n;
    w o "  [@inline_let] let _ : squash (LP.list_mem x (LP.list_map fst %s_enum)) =\n" n;
    w o "    _ by (LP.synth_maybe_enum_key_inv_unknown_tac x)\n";
    w o "  in\n";
    w o "  x\n\n";
  	w o "let lemma_synth_%s_inj () : Lemma\n" n;
  	w o "  (LP.synth_injective synth_%s) = ()\n\n" n;
  	w o "let lemma_synth_%s_inv () : Lemma\n" n;
    w o "  (LP.synth_inverse synth_%s synth_%s_inv) = ()\n\n" n n;
   end;

  (* Parse *)
  let maybe = if is_open then "maybe_" else "" in
	w o "noextract let parse_%s%s_key : LP.parser _ (LP.%senum_key %s_enum) =\n" maybe n maybe n;
  w o "  LP.parse_%senum_key %s_repr_parser %s_enum\n\n" maybe n n;
	w o "noextract let serialize_%s%s_key : LP.serializer parse_%s%s_key =\n" maybe n maybe n;
  w o "  LP.serialize_%senum_key %s_repr_parser %s_repr_serializer %s_enum\n\n" maybe n n n;

  (* Spec *)
	w o "noextract let %s_parser : LP.parser _ %s =\n" n n;
	w o "  lemma_synth_%s_inj ();\n" n;
  w o "  parse_%s%s_key `LP.parse_synth` synth_%s\n\n" maybe n n;
  w o "noextract let %s_serializer : LP.serializer %s_parser =\n" n n;
	w o "  lemma_synth_%s_inj ();\n  lemma_synth_%s_inv ();\n" n n;
	w o "  LP.serialize_synth _ synth_%s serialize_%s%s_key synth_%s_inv ()\n\n" n maybe n n;
  write_bytesize o is_private n;

  (* Intermediate *)
  wh o "let parse32_%s%s_key : LS.parser32 parse_%s%s_key =\n" maybe n maybe n;
  wh o "  FStar.Tactics.synth_by_tactic (LS.parse32_%senum_key_tac %s_repr_parser32 %s_enum)\n\n" maybe n n;
  wh o "let %s_parser32 : LS.parser32 %s_parser =\n" n n ;
  wh o "  lemma_synth_%s_inj ();\n" n;
  wh o "  LS.parse32_synth _ synth_%s (fun x->synth_%s x) parse32_%s%s_key ()\n\n" n n maybe n;
	wh o "let serialize32_%s%s_key : LS.serializer32 serialize_%s%s_key =\n" maybe n maybe n;
  (if is_open then (* FIXME: harmonize the tactic name in LowParse *)
    wh o "  FStar.Tactics.synth_by_tactic (LS.serialize32_maybe_enum_key_tac\n"
  else
    wh o "  FStar.Tactics.synth_by_tactic (LS.serialize32_enum_key_gen_tac\n");
  wh o "    %s_repr_serializer32 %s_enum)\n\n" n n;
  wh o "let %s_serializer32 : LS.serializer32 %s_serializer =\n" n n;
	wh o "  lemma_synth_%s_inj ();\n  lemma_synth_%s_inv ();\n" n n;
  wh o "  LS.serialize32_synth _ synth_%s _ serialize32_%s%s_key synth_%s_inv (fun x->synth_%s_inv x) ()\n\n" n maybe n n n;

  wnp o "let %s_size32 =\n" n;
  wnp o "  [@inline_let] let _ = assert_norm (LSZ.size32_constant_precond %s_serializer %dul) in\n" n blen;
  wnp o "  LSZ.size32_constant %s_serializer %dul ()\n\n" n blen;

  (* Low: validator *)
  if is_open then
    () (* validator not needed, since maybe_enum_key is total constant size *)
  else
   begin
    wl o "[@@ (LT.postprocess_with LT.pp_norm_tac)]\n";
    wl o "inline_for_extraction let validate_%s%s_key : LL.validator parse_%s%s_key =\n" maybe n maybe n;
    wl o "    LL.mk_validate_enum_key %s_repr_validator %s_repr_reader %s_enum\n\n" n n n;
    wl o "let %s_validator =\n" n;
    wl o "  lemma_synth_%s_inj ();\n" n;
    wl o "  LL.validate_synth validate_%s%s_key synth_%s ()\n\n" maybe n n
   end;

  (* Low: reader *)
  begin
    wl o "[@@ (LT.postprocess_with LT.pp_norm_tac) ]\n";
    if is_open then
      begin
        wl o "inline_for_extraction let read_maybe_%s_key : LL.leaf_reader parse_maybe_%s_key =\n" n n;
        wl o "    LL.mk_read_maybe_enum_key %s_repr_reader %s_enum\n\n" n n;
      end
    else
      begin
        wl o "inline_for_extraction let read_%s_key : LL.leaf_reader parse_%s_key =\n" n n;
        wl o "  LL.mk_read_enum_key %s_repr_reader %s_enum\n\n" n n;
      end
  end;
  wl i "val %s_reader: LL.leaf_reader %s_parser\n\n" n n;
  wl o "let %s_reader =\n" n;
  wl o " [@inline_let] let _ = lemma_synth_%s_inj () in\n" n;
  wl o " LL.read_synth' parse_%s%s_key synth_%s read_%s%s_key ()\n\n" maybe n n maybe n;

  (* Low: writer *)
  wl o "inline_for_extraction let write_%s%s_key : LL.leaf_writer_strong serialize_%s%s_key =\n" maybe n maybe n;
  wl o "  LL.write_%senum_key %s_repr_writer %s_enum (_ by (LP.enum_repr_of_key_tac %s_enum))\n\n" maybe n n n;
  wl o "inline_for_extraction let lserialize_%s%s_key : LL.serializer32 serialize_%s%s_key =\n" maybe n maybe n;
  wl o "  LL.serializer32_of_leaf_writer_strong_constant_size write_%s%s_key %dul ()\n\n" maybe n blen;
  wl i "val %s_writer: LL.leaf_writer_strong %s_serializer\n\n" n n;
  wl o "let %s_writer =\n" n;
  wl o "  [@inline_let] let _ = lemma_synth_%s_inj (); lemma_synth_%s_inv () in\n" n n;
  wl o "  LL.write_synth write_%s%s_key synth_%s synth_%s_inv (fun x -> synth_%s_inv x) ()\n\n" maybe n n n n;
  wl i "val %s_lserializer: LL.serializer32 %s_serializer\n\n" n n;
  wl o "let %s_lserializer = LL.serializer32_of_leaf_writer_strong_constant_size %s_writer %dul ()\n\n" n n blen;

  (* Pulse: validator *)
  if is_open then
    () (* validator not needed for open enums with constant-size repr *)
  else
   begin
    wp o "[@@ (LT.postprocess_with LT.pp_norm_tac)]\n";
    wp o "inline_for_extraction let validate_%s%s_key : LPS.validator parse_%s%s_key =\n" maybe n maybe n;
    wp o "    PPE.mk_validate_enum_key %s_repr_validator %s_repr_reader %s_enum ()\n\n" n n n;
    wp o "let %s_validator =\n" n;
    wp o "  lemma_synth_%s_inj ();\n" n;
    wp o "  LPC.validate_synth validate_%s%s_key synth_%s\n\n" maybe n n
   end;

  (* Pulse: reader *)
  begin
    wp o "[@@ (LT.postprocess_with LT.pp_norm_tac)]\n";
    if is_open then
      begin
        wp o "inline_for_extraction let read_maybe_%s_key : PPB.leaf_reader parse_maybe_%s_key =\n" n n;
        wp o "    PPE.mk_read_maybe_enum_key %s_repr_reader %s_enum\n\n" n n;
      end
    else
      begin
        wp o "inline_for_extraction let read_%s_key : PPB.leaf_reader parse_%s_key =\n" n n;
        wp o "  PPE.mk_read_enum_key %s_repr_reader %s_enum ()\n\n" n n;
      end
  end;
  wp i "val %s_reader: PPB.leaf_reader %s_parser\n\n" n n;
  wp o "let %s_reader =\n" n;
  wp o " lemma_synth_%s_inj ();\n" n;
  wp o " PPB.leaf_reader_of_reader (PPC.read_synth' (PPB.reader_of_leaf_reader read_%s%s_key) synth_%s synth_%s_inv)\n\n" maybe n n n;

  (* Pulse: writer *)
  wp o "inline_for_extraction let write_%s%s_key : LPS.l2r_leaf_writer (serialize_%s%s_key) =\n" maybe n maybe n;
  wp o "  LPPS.l2r_leaf_write_%senum_key %s_repr_writer %s_enum (_ by (LP.enum_repr_of_key_tac %s_enum))\n\n" maybe n n n;
  wp i "val %s_writer: LPS.l2r_leaf_writer %s_serializer\n\n" n n;
  wp o "let %s_writer =\n" n;
  wp o "  [@inline_let] let _ = lemma_synth_%s_inj (); lemma_synth_%s_inv () in\n" n n;
  wp o "  LPC.l2r_leaf_write_synth write_%s%s_key synth_%s synth_%s_inv (fun x -> synth_%s_inv x)\n\n" maybe n n n n;

  (* Pulse: structural leaf_size (parallel to writer) *)
  wp o "inline_for_extraction let size_%s%s_key : LPS.leaf_size (serialize_%s%s_key) =\n" maybe n maybe n;
  wp o "  LPS.leaf_size_constant_size serialize_%s%s_key %dsz (_ by (FStar.Tactics.norm [delta; iota; zeta; primops]; FStar.Tactics.smt ()))\n\n" maybe n blen;
  wp i "val %s_leaf_size: LPS.leaf_size %s_serializer\n\n" n n;
  wp o "let %s_leaf_size =\n" n;
  wp o "  [@inline_let] let _ = lemma_synth_%s_inj (); lemma_synth_%s_inv () in\n" n n;
  wp o "  LPC.leaf_size_synth size_%s%s_key synth_%s synth_%s_inv (fun x -> synth_%s_inv x)\n\n" maybe n n n n;

  (* Pulse: copyful parser + free *)
  emit_copyful_leaf o i n;

  (* Pulse: copyful safe writer (constant-size enum repr) *)
  if !emit_pulse then emit_copyful_safe_leaf_writer o i n blen;

  (* bytesize lemma *)
  wl i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == %d) [SMTPat (%s_bytesize x)]\n\n" n n n blen n;
  wl o "let %s_bytesize_eqn x = %s_bytesize_eq x; assert (FStar.Seq.length (LP.serialize %s_serializer x) <= %d); assert (%d <= FStar.Seq.length (LP.serialize %s_serializer x))\n\n" n n n blen blen n;
  ()

and compile_abstract tch o i n dn min max attrs =
  if !types_from = "" then w (type_channel tch i) "type %s = %s\n" n dn;
  let li = get_leninfo n in
  let has_lserializer = has_attr attrs "has_lserializer" in
  write_api o i has_lserializer false li.meta n min max;
  if has_lserializer
  then begin
      wl i "val %s_reader : LL.leaf_reader %s\n\n" n (pcombinator_name n);
      wl i "val %s_lserializer: LL.serializer32 %s\n\n" n (scombinator_name n);
  end
  
and compile_ite tch o i n sn fn tagn clen cval tt tf true_ctor_opt false_ctor_opt al =
  (* if-then-else has two independent backends: the Pulse (Seq-based, copyful)
     one and the legacy non-pulse (FStar.Bytes-based SLow / Low-star) one. They
     use incompatible discriminant tag representations (Seq.lseq vs FStar.Bytes),
     so they are emitted by separate functions selected here. This preserves the
     master non-pulse if-then-else codegen (tests/unittests.rfc t27) unchanged
     while giving -pulse the new Seq-native codegen. *)
  if !emit_pulse
  then compile_ite_pulse tch o i n sn fn tagn clen cval tt tf true_ctor_opt false_ctor_opt al
  else compile_ite_nonpulse tch o i n sn fn tagn clen cval tt tf al

and compile_ite_pulse tch o i n sn fn tagn clen cval tt tf true_ctor_opt false_ctor_opt al  =
  let is_private = has_attr al "private" in
  let li = get_leninfo (sn^"@"^fn) in
  let ncap = String.capitalize_ascii n in
  let tagt = sprintf "%s_%s" sn tagn in
  if clen = 0 then failwith "Tag cannot be empty in if-then-else.";
  (* Resolve the ADT constructor names: a custom label (capitalized) when given,
     otherwise the default <N>_true / <N>_false. The <n>_false record-type name
     is independent and always stays <n>_false. *)
  let true_ctor = match true_ctor_opt with
    | Some s -> String.capitalize_ascii s | None -> ncap ^ "_true" in
  let false_ctor = match false_ctor_opt with
    | Some s -> String.capitalize_ascii s | None -> ncap ^ "_false" in
  if true_ctor = false_ctor then
    failwith (sprintf "if-then-else %s: the true and false constructors must have distinct names (got %s)" n true_ctor);
  compile_ite_tag o i tagt clen is_private;

  let bl = hex_to_uy_list cval in
  (* [<n>_cst] is the discriminant tag constant, a [Seq.seq] built by
     [Seq.seq_of_list] over a literal byte list of length [clen]. It is marked
     [noextract]: it is a pure SPEC value used only in erased/ghost positions of
     the extracted code (the runtime tag comparison is performed byte-by-byte by
     [<n>_get_byte] + [LPITE.seqbytes_eq_test], never by reading [<n>_cst]). If
     it were extracted, KaRaMeL would lower the [Seq.seq] into a heap-allocated
     singleton-buffer linked list ([newbuf { hd; tl = newbuf { ... } }]) of depth
     [clen]; KaRaMeL's checker re-checks every [EBufCreate] initializer TWICE
     (Checker.check': [check_or_infer] then [check]), which is O(2^clen) and hangs
     extraction for large tags (e.g. a 32-byte tag => 2^32 checker traversals).
     Keeping it [noextract] avoids emitting the constant entirely. [<n>_cond] and
     [<n>_synth] are likewise SPEC-only (used by [parse_<n>_param] and the ghost
     [<n>_vmatch]/[<n>_conv]) and must be [noextract] too so the extracted code
     never refers back to the (now non-extracted) [<n>_cst]. *)
  w i "noextract let %s_cst : %s =\n  assert_norm (L.length [%s] == %d);\n  Seq.seq_of_list [%s]\n\n" n tagt bl clen bl;
  (* Under -pulse the executable representation is the Vec-based copyful lowtype
     ([<n>_low]/[<n>_lowtype] with [<n>_vmatch]/[<n>_conv]); the high-level
     if-then-else record [<n>_false] (carrying the [Seq]-based tag/payload) and
     the high sum [<n>] are referenced only by ghost/noextract spec code and the
     auto-generated discriminators, yet KaRaMeL still materialises them -- leaking
     an opaque [Seq.seq uint8] field as a [Prims_list] cons-list into the
     extracted C even though no runtime value is ever built from them.  Mark them
     noextract under -pulse (if-then-else is -pulse-only, but gate defensively). *)
  let nx = if !emit_pulse then "noextract " else "" in
  w i "%stype %s_false = {\n  tag: t:%s_%s{t <> %s_cst};\n  value: %s\n}\n\n" nx n n tagn n (compile_type tf);
  w i "%stype %s =\n  | %s of %s\n  | %s of %s_false\n\n" nx n true_ctor (compile_type tt) false_ctor n;

  (* Spec. The condition, payload type family, synth and the [parse_ifthenelse]
     parameter record are emitted to the INTERFACE (not the impl): the copyful
     [<n>_vmatch] (via [<n>_cond]) and [<n>_conv] (via [parse_<n>_param]) are
     transparent interface definitions referenced by an enclosing copyful
     struct's own interface, so their dependencies must be interface-visible.
     (if-then-else is -pulse-only, so this never affects a non-pulse interface.)

     These spec lets are emitted BEFORE [write_api], i.e. before the [<n>_parser],
     [<n>_serializer], [<n>_validator] and [<n>_jumper] vals: F* interleaves
     interface declarations into the implementation in interface order, so an
     interface [let] only becomes visible in the .fst after every preceding [val]
     has been implemented. The .fst definitions of [<n>_parser] etc. reference
     [parse_<n>_param], hence the param let must precede those vals in the
     interface, otherwise the .fst cannot see it (Identifier not found). *)
  w i "noextract let %s_cond (x:%s_%s) : Tot bool = x = %s_cst\n\n" n n tagn n;
  w i "inline_for_extraction let %s_payload (b:bool) : Tot Type =\n  if b then %s else %s\n\n" n (compile_type tt) (compile_type tf);
  w i "inline_for_extraction let parse_%s_payload (b:bool) : Tot (k: LP.parser_kind & LP.parser k (%s_payload b)) =\n" n n;
  w i "  if b then (| _ , %s |) else (| _, %s |)\n\n" (pcombinator_name tt) (pcombinator_name tf);
  w i "noextract let %s_synth (x:%s_%s) (y:%s_payload (%s_cond x)) : Tot %s =\n" n n tagn n n n;
  w i "  if %s_cond x then %s y else %s ({ tag = x; value = y })\n\n" n true_ctor false_ctor;
  w i "inline_for_extraction noextract let parse_%s_param = {\n" n;
  w i "  LP.parse_ifthenelse_tag_kind = _; LP.parse_ifthenelse_tag_t = _;\n";
  w i "  LP.parse_ifthenelse_tag_parser = %s; LP.parse_ifthenelse_tag_cond = %s_cond;\n" (pcombinator_name tagt) n;
  w i "  LP.parse_ifthenelse_payload_t = %s_payload; LP.parse_ifthenelse_payload_parser = parse_%s_payload;\n" n n;
  w i "  LP.parse_ifthenelse_t = _;  LP.parse_ifthenelse_synth = %s_synth;\n" n;
  w i "  LP.parse_ifthenelse_synth_injective = (fun t1 x1 t2 x2 -> ());\n}\n\n";

  write_api o i false is_private li.meta n (clen+li.min_len) (clen+li.max_len);

  w o "let _ : squash (LP.parse_ifthenelse_kind parse_%s_param == %s_parser_kind) =\n" n n;
  w o "  _ by (FStar.Tactics.norm [delta; iota; primops]; FStar.Tactics.trefl ())\n\n";
  w o "let %s_parser = LP.parse_ifthenelse parse_%s_param\n\n" n n;
  w o "inline_for_extraction let serialize_%s_payload (b:bool) : Tot (LP.serializer (dsnd (parse_%s_param.LP.parse_ifthenelse_payload_parser b))) =\n" n n;
  w o "  if b then %s else %s\n\n" (scombinator_name tt) (scombinator_name tf);
  w o "inline_for_extraction noextract let %s_synth_recip (x:%s) : GTot (t:%s_%s & (%s_payload (%s_cond t))) =\n" n n n tagn n n;
  w o "  match x with\n  | %s y -> (| %s_cst, y |)\n  | %s m -> (| m.tag, m.value |)\n\n" true_ctor n false_ctor;
  w o "inline_for_extraction noextract let serialize_%s_param : LP.serialize_ifthenelse_param parse_%s_param = {\n" n n;
  w o "  LP.serialize_ifthenelse_tag_serializer = %s;\n" (scombinator_name tagt);
  w o "  LP.serialize_ifthenelse_payload_serializer = serialize_%s_payload;\n" n;
  w o "  LP.serialize_ifthenelse_synth_recip = %s_synth_recip;\n" n;
  w o "  LP.serialize_ifthenelse_synth_inverse = (fun x -> ());\n}\n\n";
  w o "let %s_serializer = LP.serialize_ifthenelse serialize_%s_param\n\n" n n;
  write_bytesize o is_private n;

  (* Pulse executable codegen (Part B): the validator and jumper. The 32-byte
     discriminant tag has no scalar leaf reader, so we use the test-based
     if-then-else combinators: the discriminant condition (tag = <n>_cst) is
     computed in place over the validated tag region by [test_ifthenelse_tag_of_seqbytes_eq],
     whose [seqbytes]-equality bridge is discharged by [seqbytes_cond_prop_lseq_bytes].

     The byte-by-byte comparison loop in [seqbytes_eq_test] needs the constant
     tag byte at a *runtime* index [j : SizeT.t]. Reading it from the spec
     [<n>_cst] (a [Seq.seq]) via [Seq.index <n>_cst (SZ.v j)] is NOT extractable
     to C ([Seq.index] is ghost and [SZ.v] has no C implementation). Instead we
     emit a C-extractable [<n>_get_byte] callback: an [if]-chain on [j] returning
     the literal tag bytes, proved equal to [Seq.index <n>_cst (SZ.v j)]. The
     impossible fall-through (all [clen] values [0sz .. clen-1] are covered, and
     [SZ.v j < clen]) is discharged by [<n>_sz_contradiction]. *)
  let byte_lit k = Printf.sprintf "0x%c%cuy" cval.[2*k] cval.[2*k+1] in
  let neqs = Buffer.create 64 in
  for k = 0 to clen - 1 do
    if k > 0 then Buffer.add_string neqs " /\\ ";
    Buffer.add_string neqs (Printf.sprintf "~(j == %dsz)" k)
  done;
  wp o "let %s_sz_contradiction (j: FStar.SizeT.t)\n" n;
  wp o "  : Lemma (requires FStar.SizeT.v j < %d /\\ %s) (ensures False) = ()\n\n" clen (Buffer.contents neqs);
  wp o "#push-options \"--z3rlimit 16\"\n";
  wp o "inline_for_extraction\n";
  wp o "let %s_get_byte (j: FStar.SizeT.t { FStar.SizeT.v j < %d })\n" n clen;
  wp o "  : (b: FStar.UInt8.t { b == Seq.index %s_cst (FStar.SizeT.v j) }) =\n" n;
  wp o "  assert_norm (FStar.List.Tot.Base.length [%s] == %d);\n" bl clen;
  wp o "  FStar.Seq.Properties.lemma_seq_of_list_index [%s] (FStar.SizeT.v j);\n" bl;
  for k = 0 to clen - 1 do
    wp o "  if j = %dsz then (assert_norm (FStar.List.Tot.Base.index [%s] %d == %s); %s) else\n" k bl k (byte_lit k) (byte_lit k)
  done;
  wp o "  (%s_sz_contradiction j; 0uy)\n" n;
  wp o "#pop-options\n\n";
  wp o "let %s_test_cond () : Lemma (LPITE.test_seqbytes_cond_prop parse_%s_param %d %s_cst) =\n" n n clen n;
  wp o "  LPITE.seqbytes_cond_prop_lseq_bytes %d %s_cst\n\n" clen n;
  wp o "let %s_test : LPITE.test_ifthenelse_tag parse_%s_param =\n" n n;
  wp o "  LPITE.test_ifthenelse_tag_of_seqbytes_eq parse_%s_param %dsz %s_cst %s_get_byte (%s_test_cond ())\n\n" n clen n n n;
  wp o "let %s_validator = LPITE.validate_ifthenelse_test parse_%s_param %s_validator %s_test\n" n n tagt n;
  wp o "  (fun b -> if b then %s else %s) ()\n\n" (pulse_validator_name tt) (pulse_validator_name tf);
  wp o "let %s_jumper = LPITE.jump_ifthenelse_test parse_%s_param %s_jumper %s_test\n" n n tagt n;
  wp o "  (fun b -> if b then %s else %s) ()\n\n" (pulse_jumper_name tt) (pulse_jumper_name tf);

  (* Copyful (owned read/free/write/size + lowtype/mid/vmatch/conv) interface:
     lets this if-then-else type be used as a field of an enclosing copyful
     struct. Routes through the LowParse.PulseParse.IfThenElse copyful
     combinators. -pulse-only. *)
  if !emit_pulse then emit_copyful_ite o i n tagt tt tf;

  (* SLow (wh) and Low* (wl) backends are intentionally not emitted for
     if-then-else: this feature is -pulse-only (the driver errors out for the
     other backends, see prog_has_ifeq in quackyducky.ml). The former code here
     relied on FStar.Bytes-based combinators (e.g. valid_slice_equals_bytes) that
     are incompatible with the Seq-based discriminant tag/constant. *)

  (* bytesize decomposition (per-constructor, mirroring the sum [bytesize_eqn]
     lemmas): an if-then-else serializes as tag ++ payload, so its bytesize is the
     constant discriminant length [clen] plus the payload bytesize.  Discharged via
     [LP.length_serialize_ifthenelse] (tag ++ payload length split), the constant
     tag length ([<tagt>_bytesize_eqn] over the [lseq clen] discriminant), and the
     payload [_bytesize_eq].  These let an enclosing struct's [bytesize_eqn] (and
     downstream length proofs) decompose an if-then-else field by SMTPat. *)
  if not is_private then begin
    w i "val %s_bytesize_eqn_%s (x: %s) : Lemma (%s_bytesize (%s x) == %d + %s) [SMTPat (%s_bytesize (%s x))]\n\n"
      n true_ctor (compile_type tt) n true_ctor clen (bytesize_call tt "x") n true_ctor;
    w o "let %s_bytesize_eqn_%s x =\n" n true_ctor;
    w o "  %s_bytesize_eq (%s x);\n" n true_ctor;
    w o "  LP.length_serialize_ifthenelse serialize_%s_param (%s x);\n" n true_ctor;
    w o "  %s_bytesize_eq %s_cst;\n" tagt n;
    w o "  %s\n\n" (bytesize_eq_call tt "x");
    w i "val %s_bytesize_eqn_%s (m: %s_false) : Lemma (%s_bytesize (%s m) == %d + %s) [SMTPat (%s_bytesize (%s m))]\n\n"
      n false_ctor n n false_ctor clen (bytesize_call tf "m.value") n false_ctor;
    w o "let %s_bytesize_eqn_%s m =\n" n false_ctor;
    w o "  %s_bytesize_eq (%s m);\n" n false_ctor;
    w o "  LP.length_serialize_ifthenelse serialize_%s_param (%s m);\n" n false_ctor;
    w o "  %s_bytesize_eq m.tag;\n" tagt;
    w o "  %s\n\n" (bytesize_eq_call tf "m.value")
  end;
  ()

and compile_ite_nonpulse tch o i n sn fn tagn clen cval tt tf al  =
  let is_private = has_attr al "private" in
  let li = get_leninfo (sn^"@"^fn) in
  let ncap = String.capitalize_ascii n in
  let tagt = sprintf "%s_%s" sn tagn in
  if clen = 0 then failwith "Tag cannot be empty in if-then-else.";
  compile_typedef tch o i sn tagn (TypeSimple "opaque") (VectorFixed clen) None al;

  w i "let %s_cst : %s_%s =\n  let b = BY.bytes_of_hex \"%s\" in\n  assume(BY.length b == %d); b\n\n" n sn tagn cval clen;
  w i "type %s_false = {\n  tag: t:%s_%s{t <> %s_cst};\n  value: %s\n}\n\n" n n tagn n (compile_type tf);
  w i "type %s =\n  | %s_true of %s\n  | %s_false of %s_false\n\n" n ncap (compile_type tt) ncap n;
  write_api o i false is_private li.meta n (clen+li.min_len) (clen+li.max_len);

  (* Spec *)
  w o "inline_for_extraction let %s_cond (x:%s_%s) : Tot bool = x = %s_cst\n\n" n n tagn n;
  w o "inline_for_extraction let %s_payload (b:bool) : Tot Type =\n  if b then %s else %s\n\n" n (compile_type tt) (compile_type tf);
  w o "inline_for_extraction let parse_%s_payload (b:bool) : Tot (k: LP.parser_kind & LP.parser k (%s_payload b)) =\n" n n;
  w o "  if b then (| _ , %s |) else (| _, %s |)\n\n" (pcombinator_name tt) (pcombinator_name tf);
  w o "inline_for_extraction let %s_synth (x:%s_%s) (y:%s_payload (%s_cond x)) : Tot %s =\n" n n tagn n n n;
  w o "  if %s_cond x then %s_true y else %s_false ({ tag = x; value = y })\n\n" n ncap ncap;
  w o "inline_for_extraction noextract let parse_%s_param = {\n" n;
  w o "  LP.parse_ifthenelse_tag_kind = _; LP.parse_ifthenelse_tag_t = _;\n";
  w o "  LP.parse_ifthenelse_tag_parser = %s; LP.parse_ifthenelse_tag_cond = %s_cond;\n" (pcombinator_name tagt) n;
  w o "  LP.parse_ifthenelse_payload_t = %s_payload; LP.parse_ifthenelse_payload_parser = parse_%s_payload;\n" n n;
  w o "  LP.parse_ifthenelse_t = _;  LP.parse_ifthenelse_synth = %s_synth;\n" n;
  w o "  LP.parse_ifthenelse_synth_injective = (fun t1 x1 t2 x2 -> ());\n}\n\n";
  w o "let _ : squash (LP.parse_ifthenelse_kind parse_%s_param == %s_parser_kind) =\n" n n;
  w o "  _ by (FStar.Tactics.norm [delta; iota; primops]; FStar.Tactics.trefl ())\n\n";
  w o "let %s_parser = LP.parse_ifthenelse parse_%s_param\n\n" n n;
  w o "inline_for_extraction let serialize_%s_payload (b:bool) : Tot (LP.serializer (dsnd (parse_%s_param.LP.parse_ifthenelse_payload_parser b))) =\n" n n;
  w o "  if b then %s else %s\n\n" (scombinator_name tt) (scombinator_name tf);
  w o "inline_for_extraction let %s_synth_recip (x:%s) : GTot (t:%s_%s & (%s_payload (%s_cond t))) =\n" n n n tagn n n;
  w o "  match x with\n  | %s_true y -> (| %s_cst, y |)\n  | %s_false m -> (| m.tag, m.value |)\n\n" ncap n ncap;
  w o "inline_for_extraction noextract let serialize_%s_param : LP.serialize_ifthenelse_param parse_%s_param = {\n" n n;
  w o "  LP.serialize_ifthenelse_tag_serializer = %s;\n" (scombinator_name tagt);
  w o "  LP.serialize_ifthenelse_payload_serializer = serialize_%s_payload;\n" n;
  w o "  LP.serialize_ifthenelse_synth_recip = %s_synth_recip;\n" n;
  w o "  LP.serialize_ifthenelse_synth_inverse = (fun x -> ());\n}\n\n";
  w o "let %s_serializer = LP.serialize_ifthenelse serialize_%s_param\n\n" n n;
  write_bytesize o is_private n;

  (* Intermediate *)
  wh o "let %s_parser32 = LS.parse32_ifthenelse parse_%s_param %s\n" n n (pcombinator32_name tagt);
  wh o "  (fun x -> %s_cond x) (fun b -> if b then %s else %s)\n" n (pcombinator32_name tt) (pcombinator32_name tf);
  wh o "  (fun b -> if b then (fun _ pl -> %s_true pl) else (fun t pl -> %s_false ({ tag = t; value = pl; })))\n\n" ncap ncap;
  wh o "let %s_serializer32 = LS.serialize32_ifthenelse serialize_%s_param %s\n" n n (scombinator32_name tagt);
  wh o "  (fun x -> match x with %s_true _ -> %s_cst | %s_false m -> m.tag)\n" ncap n ncap;
  wh o "  (fun x -> %s_cond x) (fun b -> if b then (fun (%s_true y) -> y) else (fun (%s_false m) -> m.value))\n" n ncap ncap;
  wh o "  (fun b -> if b then %s else %s)\n\n" (scombinator32_name tt) (scombinator32_name tf);
  wh o "let %s_size32 = LSZ.size32_ifthenelse serialize_%s_param %s\n" n n (size32_name tagt);
  wh o "  (fun x -> match x with %s_true _ -> %s_cst | %s_false m -> m.tag)" ncap n ncap;
  wh o "  (fun x -> %s_cond x) (fun b -> if b then (fun (%s_true y) -> y) else (fun (%s_false m) -> m.value))\n" n ncap ncap;
  wh o "  (fun b -> if b then %s else %s)\n\n" (size32_name tt) (size32_name tf);

  (* Low *)
  wl o "inline_for_extraction let test_%s : LL.test_ifthenelse_tag parse_%s_param =" n n;
  wl o "  fun #_ #_ input pos -> LL.valid_slice_equals_bytes %s_cst input pos\n\n" n;
  wl o "let %s_validator = LL.validate_ifthenelse parse_%s_param %s\n" n n (validator_name tagt);
  wl o "  test_%s (fun b -> if b then %s else %s)\n\n" n (validator_name tt) (validator_name tf);
  wl o "let %s_jumper = LL.jump_ifthenelse parse_%s_param %s\n" n n (jumper_name tagt);
  wl o "  test_%s (fun b -> if b then %s else %s)\n\n" n (jumper_name tt) (jumper_name tf);
  wl i "val %s_elim (h:HS.mem) (#rrel: _) (#rel: _) (input:LL.slice rrel rel) (pos: U32.t) : Lemma\n" n;
  wl i "  (requires (LL.valid %s_parser h input pos))\n" n;
  wl i "  (ensures (\n    LL.valid %s h input pos /\\ (\n" (pcombinator_name tagt);
  wl i "    let x = LL.contents %s_parser h input pos in\n" n;
  wl i "    let y = LL.contents %s h input pos in\n" (pcombinator_name tagt);
  wl i "    y == (match x with | %s_true _ -> %s_cst | %s_false m -> m.tag))))\n\n" ncap n ncap;
  wl o "let %s_elim h #_ #_ input pos = LL.valid_ifthenelse_elim parse_%s_param h input pos\n\n" n n;
  wl i "val %s_test (#rrel: _) (#rel: _) (input:LL.slice rrel rel) (pos: U32.t) : HST.Stack bool\n" n;
  wl i "  (requires (fun h -> LL.valid %s_parser h input pos))\n" n;
  wl i "  (ensures (fun h res h' -> B.modifies B.loc_none h h' /\\\n";
  wl i "    (res == true <==> %s_true? (LL.contents %s_parser h input pos))))\n\n" ncap n;
  wl o "let %s_test #_ #_ input pos = let h = HST.get () in %s_elim h input pos; test_%s input pos\n\n" n n n;
  wl i "noextract let %s_clens_tag : LL.clens %s %s = {\n" n n (compile_type tagt);
  wl i "  LL.clens_cond = (fun x -> True);\n";
  wl i "  LL.clens_get = (fun x -> (match x with | %s_true _ -> %s_cst | %s_false m -> m.tag));\n\n" ncap n ncap;
  wl i "}\n\n";
  wl i "val %s_gaccessor_tag: LL.gaccessor %s_parser %s %s_clens_tag\n\n" n n (pcombinator_name tagt) n;
  wl o "let %s_gaccessor_tag = LL.gaccessor_ext (LL.gaccessor_ifthenelse_tag serialize_%s_param) %s_clens_tag ()\n\n" n n n;
  wl i "val %s_accessor_tag: LL.accessor %s_gaccessor_tag\n\n" n n;
  wl o "let %s_accessor_tag = LL.accessor_ext (LL.accessor_ifthenelse_tag serialize_%s_param) %s_clens_tag ()\n\n" n n n;
  wl i "noextract let %s_clens_true : LL.clens %s %s = {\n" n n (compile_type tt);
  wl i "  LL.clens_cond = (fun x -> %s_true? x);\n" ncap;
  wl i "  LL.clens_get = (fun x -> (match x with %s_true y -> y) <: Ghost %s (requires (%s_true? x)) (ensures (fun _ -> True)));\n}\n\n" ncap (compile_type tt) ncap;
  wl i "val %s_gaccessor_true: LL.gaccessor %s_parser %s %s_clens_true\n\n" n n (pcombinator_name tt) n;
  wl i "val %s_accessor_true: LL.accessor %s_gaccessor_true\n\n" n n;
  wl i "noextract let %s_clens_false : LL.clens %s %s = {\n" n n (compile_type tf);
  wl i "  LL.clens_cond = (fun x -> %s_false? x);\n" ncap;
  wl i "  LL.clens_get = (fun x -> (match x with %s_false m -> m.value) <: Ghost %s (requires (%s_false? x)) (ensures (fun _ -> True)));\n}\n\n" ncap (compile_type tf) ncap;
  wl i "val %s_gaccessor_false: LL.gaccessor %s_parser %s %s_clens_false\n\n" n n (pcombinator_name tf) n;
  wl i "val %s_accessor_false: LL.accessor %s_gaccessor_false\n\n" n n;
  wl o "let %s_gaccessor_true = LL.gaccessor_ext (LL.gaccessor_ifthenelse_payload serialize_%s_param true) %s_clens_true ()\n\n" n n n;
  wl o "let %s_accessor_true = LL.accessor_ext (LL.accessor_ifthenelse_payload serialize_%s_param %s true) %s_clens_true ()\n\n" n n (jumper_name tagt) n;
  wl o "let %s_gaccessor_false = LL.gaccessor_ext (LL.gaccessor_ifthenelse_payload serialize_%s_param false) %s_clens_false ()\n\n" n n n;
  wl o "let %s_accessor_false = LL.accessor_ext (LL.accessor_ifthenelse_payload serialize_%s_param %s false) %s_clens_false ()\n\n" n n (jumper_name tagt) n;
  wl i "val %s_intro_true (h: HS.mem) (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : Lemma\n" n;
  wl i "  (requires (LL.valid %s h input pos /\\ (\n" (pcombinator_name tagt);
  wl i "    let x = LL.contents %s h input pos in\n" (pcombinator_name tagt);
  wl i "    let pos1 = LL.get_valid_pos %s h input pos in\n" (pcombinator_name tagt);
  wl i "    x == %s_cst /\\ LL.valid %s h input pos1\n" n (pcombinator_name tt);
  wl i "  ))) (ensures (\n";
  wl i "    let pos1 = LL.get_valid_pos %s h input pos in\n" (pcombinator_name tagt);
  wl i "    LL.valid_content_pos %s_parser h input pos (%s_true (LL.contents %s h input pos1)) (LL.get_valid_pos %s h input pos1)\n  ))\n\n" n ncap (pcombinator_name tt) (pcombinator_name tt);
  wl o "let %s_intro_true h #_ #_ input pos = LL.valid_ifthenelse_intro parse_%s_param h input pos\n\n" n n;
  wl i "val %s_intro_false (h: HS.mem) (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : Lemma\n" n;
  wl i "  (requires (LL.valid %s h input pos /\\ (\n" (pcombinator_name tagt);
  wl i "    let x = LL.contents %s h input pos in\n" (pcombinator_name tagt);
  wl i "   let pos1 = LL.get_valid_pos %s h input pos in\n" (pcombinator_name tagt);
  wl i "    x =!= %s_cst /\\ LL.valid %s h input pos1\n" n (pcombinator_name tf);
  wl i "  ))) (ensures (\n";
  wl i "    let x = LL.contents %s h input pos in\n" (pcombinator_name tagt);
  wl i "    let pos1 = LL.get_valid_pos %s h input pos in\n" (pcombinator_name tagt);
  wl i "    LL.valid_content_pos %s_parser h input pos (%s_false ({ tag = x; value = (LL.contents %s h input pos1) })) (LL.get_valid_pos %s h input pos1)\n  ))\n\n" n ncap (pcombinator_name tf) (pcombinator_name tf);
  wl o "let %s_intro_false h #_ #_ input pos = LL.valid_ifthenelse_intro parse_%s_param h input pos\n\n" n n;
  ()

and compile_select tch o i n seln tagn tagt taga cl def al =
  let is_private = has_attr al "private" in
  let is_implicit = has_attr taga "implicit" in
  let has_fail_missing = has_attr al "failmissing" in (* autocomplete missing cases with Fail even if default is provided *)
  let li = get_leninfo n in
  let taglen = (get_leninfo tagt).max_len in (* assume tag is constant-sized *)
  let tn = compile_type tagt in
  let cprefix = String.capitalize_ascii seln in

  (* We need to substitute the whole type for encapsulating vlbytes *)
  if is_implicit then erased := SM.add n () !erased;

  (* Complete undefined cases in enum with Fail *)
  let (enum_fields, is_open) = try SM.find tn !fields with
    | _ -> failwith ("Type "^tn^" is not an enum and cannot be used in select()") in

  (* Auto-complete omitted cases, with default case if provided *)
  let cl = (fun l -> let r = ref [] in
    let dty = match def with Some d when not has_fail_missing -> d | _ -> "Fail" in
    let li_dty = sizeof (TypeSimple dty) in
    List.iter (function
      | EnumFieldSimple(cn, _) ->
        if not (List.mem_assoc cn l) then (
          if li_dty.meta <> MetadataTotal then li.meta <- MetadataDefault;
          r := (cn, dty) :: !r
        )
      | _ -> ()) enum_fields; l @ !r) cl in

  let def = if is_open then
    (if def = None then failwith ("Missing default case of open sum "^n) else def)
    else None in

  let prime = if is_implicit then "'" else "" in
  (* Under -pulse, the executable representation is the Vec-based copyful lowtype
     ([<n>_low]/[<n>_lowtype] with [<n>_vmatch]/[<n>_conv]); the high-level sum
     type [<n>] and its [tag_of_<n>] discriminator are only referenced from
     ghost/noextract spec code (the LowParse sum machinery is normalised into the
     lowtype-based copyful path), yet KaRaMeL still materialises the high type and
     its auto-generated discriminators -- leaking F* spec types (e.g. an opaque
     [Seq.seq uint8] case payload as a [Prims_list] cons-list) into the extracted
     C even though they are never used at runtime.  Mark them noextract under
     -pulse (mirroring the struct/vllist fix); the LowStar (non-pulse) path uses
     the high sum as its actual runtime representation, so they must stay
     extractable there. *)
  let nx = if !emit_pulse && not li.has_lserializer then "noextract " else "" in
  if !types_from = "" then begin
  w (type_channel tch i) "%stype %s%s =\n" nx n prime;
  List.iter (fun (case, ty) -> w (type_channel tch i) "  | %s_%s of %s\n" cprefix case (compile_type ty)) cl;
  (match def with Some d -> w (type_channel tch i) "  | %s_Unknown_%s: v:%s_repr{not (known_%s_repr v)} -> x:%s -> %s%s\n" cprefix tn tn tn (compile_type d) n prime | _ -> ());
  end;

  w i "\ninline_for_extraction %slet tag_of_%s (x:%s%s) : %s = match x with\n" nx n n prime (compile_type tagt);
  List.iter (fun (case, ty) -> w i "  | %s_%s _ -> %s\n" cprefix case (String.capitalize_ascii case)) cl;
  (match def with Some d -> w i "  | %s_Unknown_%s v _ -> Unknown_%s v\n" cprefix tn tn | _ -> ());
  w i "\n";

  if is_implicit then
    w i "%stype %s (k:%s) = x:%s'{tag_of_%s x == k}\n\n" nx n (compile_type tagt) n n;

  (* For sums under -pulse, emit the [as_enum_key] tag coercions to the interface
     BEFORE the parser/validator vals, so the transparent vmatch tag-helpers
     (and the impl's early sum machinery) can both see them. *)
  (match def with
   | None ->
     w (ipub i o) "inline_for_extraction unfold let %s_as_enum_key (x:%s) : Pure (LP.enum_key %s_enum)\n" tn tn tn;
     w (ipub i o) "  (requires norm [delta; zeta; iota; primops] (LP.list_mem x (LP.list_map fst %s_enum)) == true)" tn;
     w (ipub i o) " (ensures fun _ -> True) =\n";
     w (ipub i o) "  [@inline_let] let _ = norm_spec [delta; zeta; iota; primops] (LP.list_mem x (LP.list_map fst %s_enum)) in x\n\n" tn
   | Some _ ->
     w (ipub i o) "inline_for_extraction unfold let known_%s_as_enum_key\n" tn;
     w (ipub i o) "  (x: %s { norm [delta; zeta; iota; primops] (LP.list_mem x (LP.list_map fst %s_enum)) == true })\n" tn tn;
     w (ipub i o) "  : LP.enum_key %s_enum =\n" tn;
     w (ipub i o) "  [@inline_let] let _ = norm_spec [delta; zeta; iota; primops] (LP.list_mem x (LP.list_map fst %s_enum)) in x\n\n" tn;
     w (ipub i o) "inline_for_extraction let unknown_%s_as_enum_key (r:%s_repr) : Pure (LP.unknown_enum_repr %s_enum)\n" tn tn tn;
     w (ipub i o) "  (requires known_%s_repr r == false) (ensures fun _ -> True) =\n" tn;
     w (ipub i o) "  [@inline_let] let _ = assert_norm(LP.list_mem r (LP.list_map snd %s_enum) == known_%s_repr r) in r\n\n" tn tn);

  write_api o i li.has_lserializer is_private li.meta n li.min_len li.max_len ~param:(if is_implicit then Some tagt else None);
  let need_validator = need_validator li.meta li.min_len li.max_len in
  let need_jumper = need_jumper li.min_len li.max_len in

  (* FIXME(adl) scalability is still not great *)
  w o "// Need high Z3 limits for large sum types\n#set-options \"--z3rlimit %d\"\n\n" (60 * List.length cl);

  (** FIXME(adl) for now the t_sum of open and closed sums are independently generated,
  we may try to share more of the declarations between the two cases **)
  (match def with
  | None ->
    (*** Closed Enum ***)
    w o "inline_for_extraction let key_of_%s (x:%s%s) : LP.enum_key %s_enum =\n" n n prime tn;
    w o "  match x with\n";
    List.iter (fun (case, ty) -> w o "  | %s_%s _ -> %s_as_enum_key %s\n" cprefix case tn (String.capitalize_ascii case)) cl;
    w o "\ninline_for_extraction let %s_case_of_%s (x:%s) : Type0 =\n" n tn tn;
    w o "  match x with\n";
    List.iter (fun (case, ty) -> w o "  | %s -> %s\n" (String.capitalize_ascii case) (compile_type ty)) cl;
    w o "\nunfold inline_for_extraction let to_%s_case_of_%s (x:%s) (#x':%s) (y:%s_case_of_%s x')" n tn tn tn n tn;
    w o "  : Pure (norm [delta_only [(`%%%s_case_of_%s)]; iota] (%s_case_of_%s x))\n" n tn n tn;
    w o "  (requires (x == x')) (ensures (fun y' -> y' == y)) =\n";
    w o "  [@inline_let] let _ = norm_spec [delta_only [(`%%%s_case_of_%s)] ; iota] (%s_case_of_%s x) in y\n\n" n tn n tn;
    w o "unfold inline_for_extraction let %s_refine (k:LP.enum_key %s_enum) (x:%s%s)\n" n tn n prime;
    w o "  : Pure (LP.refine_with_tag key_of_%s k)" n;
    w o "  (requires norm [delta; iota; zeta] (key_of_%s x) == k) (ensures (fun y -> y == x)) =\n" n;
    w o "  [@inline_let] let _ = norm_spec [delta; iota; zeta] (key_of_%s x) in x\n\n" n;
    w o "%sinline_for_extraction let synth_%s_cases (x:LP.enum_key %s_enum) (y:%s_case_of_%s x)\n" (if !emit_pulse then "noextract " else "") n tn n tn;
    w o "  : LP.refine_with_tag key_of_%s x =\n  match x with\n" n;
    List.iter (fun (case, ty) -> w o "  | %s -> %s_refine x (%s_%s (to_%s_case_of_%s %s y))\n"
      (String.capitalize_ascii case) n cprefix case n tn (String.capitalize_ascii case)) cl;
    w o "\nunfold inline_for_extraction let from_%s_case_of_%s (#x':%s) (x:%s)\n" n tn tn tn;
    w o "  (y: norm [delta_only [(`%%%s_case_of_%s)]; iota] (%s_case_of_%s x))\n" n tn n tn;
    w o "  : Pure (%s_case_of_%s x') (requires (x == x')) (ensures (fun y' -> y' == y)) =\n" n tn;
    w o "  [@inline_let] let _ = norm_spec [delta_only [(`%%%s_case_of_%s)] ; iota] (%s_case_of_%s x) in y\n\n" n tn n tn;
    w o "let synth_%s_cases_recip_pre (k:LP.enum_key %s_enum)\n" n tn;
    w o "  (x:LP.refine_with_tag key_of_%s k) : GTot bool =\n  match k with\n" n;
    List.iter (fun (case, ty) -> w o "  | %s -> %s_%s? x\n" (String.capitalize_ascii case) cprefix case) cl;
    w o "\nlet synth_%s_cases_recip_pre_intro (k:LP.enum_key %s_enum) (x:LP.refine_with_tag key_of_%s k)\n" n tn n;
    w o "  : Lemma (synth_%s_cases_recip_pre k x == true) =\n" n;
    w o "  norm_spec [delta; iota] (synth_%s_cases_recip_pre k x)\n\n" n;
    w o "%sinline_for_extraction let synth_%s_cases_recip (k:LP.enum_key %s_enum)\n" (if !emit_pulse then "noextract " else "") n tn;
    w o "  (x:LP.refine_with_tag key_of_%s k) : (%s_case_of_%s k) =\n  match k with\n" n n tn;
    List.iter (fun (case, ty) ->
      w o "  | %s -> [@inline_let] let _ = synth_%s_cases_recip_pre_intro %s x in\n"
        (String.capitalize_ascii case) n (String.capitalize_ascii case);
      w o "    (match x with %s_%s y -> (from_%s_case_of_%s %s y))\n"
        cprefix case n tn (String.capitalize_ascii case)
    ) cl;
    w o "\ninline_for_extraction %slet %s_sum = LP.make_sum' %s_enum key_of_%s\n" (if !emit_pulse then "noextract " else "") n tn n;
    w o "  %s_case_of_%s synth_%s_cases synth_%s_cases_recip\n" n tn n n;
    w o "  (_ by (LP.make_sum_synth_case_recip_synth_case_tac ()))\n";
    w o "  (_ by (LP.synth_case_synth_case_recip_tac ()))\n\n";
    ()

  | Some def ->
    (*** Open enum ***)
    let tyd = compile_type def in
    w o "inline_for_extraction let unknown_enum_repr_%s_as_repr (r:LP.unknown_enum_repr %s_enum) : Pure %s_repr\n" tn tn tn;
    w o "  (requires True) (ensures fun r -> known_%s_repr r == false) =\n" tn;
    w o "  [@inline_let] let _ = assert_norm(LP.list_mem r (LP.list_map snd %s_enum) == known_%s_repr r) in r\n\n" tn tn;

    w o "inline_for_extraction let key_of_%s (x:%s%s) : LP.maybe_enum_key %s_enum =\n  match x with\n" n n prime tn;
    List.iter (fun (case, ty) ->
      let cn = String.capitalize_ascii case in
      w o "  | %s_%s _ -> LP.Known (known_%s_as_enum_key %s)\n" cprefix case tn cn
    ) cl;
    w o "  | %s_Unknown_%s v _ -> LP.Unknown (unknown_%s_as_enum_key v)\n\n" cprefix tn tn;

