      if need_validator then (
        wp o "[@@ (LT.postprocess_with LT.pp_norm_tac)]\nnoextract inline_for_extraction let %s_validator' = PPS.validate_dsum_cases_fn %s_sum parse_%s_cases validate_%s_cases %s (_ by (LP.dep_maybe_enum_destr_t_tac ())) (_ by (LP.enum_repr_of_key_tac %s_enum))\n\n" n n n n (pulse_validator_name def) tn;
        wp o "[@@ (LT.postprocess_with LT.pp_norm_tac)]\nlet %s_validator k = LPC.validate_synth (PPC.validate_compose_context synth_%s_inv (LP.refine_with_tag key_of_%s) %s_parser' %s_validator' k) (synth_%s k)\n\n" n tn n n n n
      );
      if need_jumper then (
        wl o "noextract inline_for_extraction let %s_jumper' = LL.jump_dsum_cases %s_sum parse_%s_cases jump_%s_cases %s (_ by (LP.dep_enum_destr_tac ()))\n\n" n n n n (jumper_name def);
        wl o "let %s_jumper k = LL.jump_synth (LL.jump_compose_context synth_%s_inv (LP.refine_with_tag key_of_%s) %s_parser' %s_jumper' k) (synth_%s k) ()\n\n" n tn n n n n
      );
      if need_jumper then (
        wp o "[@@ (LT.postprocess_with LT.pp_norm_tac)]\nnoextract inline_for_extraction let %s_jumper' = PPS.jump_dsum_cases_fn %s_sum parse_%s_cases jump_%s_cases %s (_ by (LP.dep_maybe_enum_destr_t_tac ())) (_ by (LP.enum_repr_of_key_tac %s_enum))\n\n" n n n n (pulse_jumper_name def) tn;
        wp o "[@@ (LT.postprocess_with LT.pp_norm_tac)]\nlet %s_jumper k = LPC.jump_synth (PPC.jump_compose_context synth_%s_inv (LP.refine_with_tag key_of_%s) %s_parser' %s_jumper' k) (synth_%s k)\n\n" n tn n n n n
      )
  ) else (* tag is not erased *)
   begin
    let same_kind = match def with
      | None -> sprintf "  assert_norm (LP.parse_sum_kind (LP.get_parser_kind %s_repr_parser) %s_sum parse_%s_cases == %s_parser_kind);\n" tn n n n
      | Some dt -> sprintf "  assert_norm (LP.parse_dsum_kind (LP.get_parser_kind %s_repr_parser) %s_sum parse_%s_cases (LP.get_parser_kind %s) == %s_parser_kind);\n" tn n n (pcombinator_name dt) n
      in
    let annot = if is_private then " : LP.parser "^n^"_parser_kind "^n else "" in
    w o "let %s_parser%s =\n%s" n annot same_kind;
    (match def with
    | None -> w o "  LP.parse_sum %s_sum %s_repr_parser parse_%s_cases\n\n" n tn n
    | Some dt -> w o "  LP.parse_dsum %s_sum %s_repr_parser parse_%s_cases %s\n\n" n tn n (pcombinator_name dt));

    let annot = if is_private then " : LP.serializer "^(pcombinator_name n) else "" in
    w o "let %s_serializer%s =\n%s" n annot same_kind;
    (match def with
    | None -> w o "  LP.serialize_sum %s_sum %s_repr_serializer serialize_%s_cases\n\n" n tn n
    | Some dt -> w o "  LP.serialize_dsum %s_sum %s_repr_serializer _ serialize_%s_cases _ %s\n\n" n tn n (scombinator_name dt));
    write_bytesize o is_private n  ~param:(if is_implicit then Some tagt else None);

    let annot = if is_private then " : LS.parser32 "^(pcombinator_name n) else "" in
    wh o "let %s_parser32%s =\n%s" n annot same_kind;
    (match def with
    | None ->
      wh o "  LS.parse32_sum2 %s_sum %s_repr_parser %s_repr_parser32 parse_%s_cases parse32_%s_cases (_ by (LP.enum_destr_tac %s_enum)) (_ by (LP.maybe_enum_key_of_repr_tac %s_enum))\n\n" n tn tn n n tn tn;
    | Some dt ->
      wh o "  LS.parse32_dsum %s_sum %s_repr_parser32\n" n tn;
      wh o "    _ parse32_%s_cases %s (_ by (LP.maybe_enum_destr_t_tac ()))\n\n" n (pcombinator32_name dt));

    let annot = if is_private then " : LS.serializer32 "^(scombinator_name n) else "" in
    wh o "let %s_serializer32%s =\n%s" n annot same_kind;
    (match def with
    | None ->
      wh o "  assert_norm (LS.serializer32_sum_gen_precond (LP.get_parser_kind %s_repr_parser) (LP.weaken_parse_cases_kind %s_sum parse_%s_cases));\n" tn n n;
      wh o "  LS.serialize32_sum2 %s_sum %s_repr_serializer %s_repr_serializer32 serialize_%s_cases serialize32_%s_cases (_ by (LP.dep_enum_destr_tac ())) (_ by (LP.enum_repr_of_key_tac %s_enum)) ()\n\n" n tn tn n n tn
    | Some dt ->
      wh o "  assert_norm (LS.serializer32_sum_gen_precond (LP.get_parser_kind %s_repr_parser) (LP.weaken_parse_dsum_cases_kind %s_sum parse_%s_cases %s_parser_kind));\n" tn n n n;
      wh o "  LS.serialize32_dsum %s_sum %s_repr_serializer (_ by (LS.serialize32_maybe_enum_key_tac %s_repr_serializer32 %s_enum ()))" n tn tn tn;
      wh o "    _ _ serialize32_%s_cases %s (_ by (LP.dep_enum_destr_tac ())) ()\n\n" n (scombinator32_name dt));

    let annot = if is_private then " : LSZ.size32 "^n else "" in
    ws li.has_lserializer o "let %s_size32%s =\n%s" n annot same_kind;
    (match def with
    | None ->
      ws li.has_lserializer o "  assert_norm (LSZ.size32_sum_gen_precond (LP.get_parser_kind %s_repr_parser) (LP.weaken_parse_cases_kind %s_sum parse_%s_cases));\n" tn n n;
      ws li.has_lserializer o "  LSZ.size32_sum2 %s_sum %s_repr_serializer %s_repr_size32 serialize_%s_cases size32_%s_cases (_ by (LP.dep_enum_destr_tac ())) (_ by (LP.enum_repr_of_key_tac %s_enum)) ()\n\n" n tn tn n n tn
    | Some dt ->
      ws li.has_lserializer o "  assert_norm (LSZ.size32_sum_gen_precond (LP.get_parser_kind %s_repr_parser) (LP.weaken_parse_dsum_cases_kind %s_sum parse_%s_cases %s_parser_kind));\n" tn n n n;
      ws li.has_lserializer o "  LSZ.size32_dsum %s_sum _ (_ by (LSZ.size32_maybe_enum_key_tac %s_repr_size32 %s_enum ()))\n" n tn tn;
      ws li.has_lserializer o "    _ _ size32_%s_cases %s (_ by (LP.dep_enum_destr_tac ())) ()\n\n" n (size32_name dt));

    if need_validator then
     begin
      let annot = if is_private then " : LL.validator "^(pcombinator_name n) else "" in
      wl o "let %s_validator%s =\n%s" n annot same_kind;
      (match def with
      | None ->
        wl o "  LL.validate_sum %s_sum %s_repr_validator %s_repr_reader parse_%s_cases validate_%s_cases (_ by (LP.dep_maybe_enum_destr_t_tac ()))\n\n" n tn tn n n;
      | Some dt ->
        wl o "  LL.validate_dsum %s_sum %s_repr_validator %s_repr_reader parse_%s_cases validate_%s_cases %s (_ by (LP.dep_maybe_enum_destr_t_tac ()))\n\n" n tn tn n n (validator_name dt));
     end;

    if need_validator then
     begin
      let annot = if is_private then " : LPS.validator "^(pcombinator_name n) else "" in
      wp o "let %s_validator%s =\n%s" n annot same_kind;
      (match def with
      | None ->
        wp o "  PPS.validate_sum %s_sum %s_repr_validator %s_repr_reader parse_%s_cases validate_%s_cases (_ by (LP.dep_maybe_enum_destr_t_tac ())) ()\n\n" n tn tn n n;
      | Some dt ->
        wp o "  PPS.validate_dsum %s_sum %s_repr_validator %s_repr_reader parse_%s_cases validate_%s_cases %s (_ by (LP.dep_maybe_enum_destr_t_tac ())) ()\n\n" n tn tn n n (pulse_validator_name dt));
     end;

    if need_jumper then
     begin
      let annot = if is_private then " : LL.jumper "^(pcombinator_name n) else "" in
      wl o "let %s_jumper%s =\n%s" n annot same_kind;
      (match def with
      | None ->
        wl o "  LL.jump_sum %s_sum %s_repr_jumper %s_repr_reader parse_%s_cases jump_%s_cases (_ by (LP.dep_maybe_enum_destr_t_tac ()))\n\n" n tn tn n n;
      | Some dt ->
        wl o "  LL.jump_dsum %s_sum %s_repr_jumper %s_repr_reader parse_%s_cases jump_%s_cases %s (_ by (LP.dep_maybe_enum_destr_t_tac ()))\n\n" n tn tn n n (jumper_name dt))
     end;

    if need_jumper then
     begin
      let annot = if is_private then " : LPS.jumper "^(pcombinator_name n) else "" in
      wp o "let %s_jumper%s =\n%s" n annot same_kind;
      (match def with
      | None ->
        wp o "  PPS.jump_sum %s_sum %s_repr_jumper %s_repr_reader parse_%s_cases jump_%s_cases (_ by (LP.dep_maybe_enum_destr_t_tac ())) ()\n\n" n tn tn n n;
      | Some dt ->
        wp o "  PPS.jump_dsum %s_sum %s_repr_jumper %s_repr_reader parse_%s_cases jump_%s_cases %s (_ by (LP.dep_maybe_enum_destr_t_tac ())) ()\n\n" n tn tn n n (pulse_jumper_name dt))
     end;

    if li.has_lserializer then begin
        let annot = if is_private then " : LL.leaf_reader "^(pcombinator_name n) else "" in
        wl i "val %s_reader : LL.leaf_reader %s\n\n" n (pcombinator_name n);
        wl o "let %s_reader%s =\n%s" n annot same_kind;
        (match def with
         | None ->
            wl o "  LL.read_sum %s_sum %s_repr_parser read_%s_key %s_repr_jumper parse_%s_cases read_%s_cases (_ by (LP.dep_enum_destr_tac ()))\n\n" n tn tn tn n n;
         | Some dt ->
            wl o "  LL.read_dsum %s_sum read_maybe_%s_key %s_repr_jumper\n" n tn tn;
            wl o "  parse_%s_cases read_%s_cases %s (_ by (LP.dep_enum_destr_tac ()))\n\n" n n (leaf_reader_name dt));

        (* Pulse: sum/dsum reader *)
        wp i "val %s_reader : PPB.leaf_reader %s\n\n" n (pcombinator_name n);
        wp o "let %s_reader =\n%s" n same_kind;
        (match def with
         | None ->
            wp o "  PPS.read_sum %s_sum %s_repr_reader %s_repr_jumper parse_%s_cases read_%s_cases (_ by (LP.dep_enum_destr_tac ())) (_ by (LP.dep_maybe_enum_destr_t_tac ())) () ()\n\n" n tn tn n n;
         | Some dt ->
            wp o "  PPS.read_dsum %s_sum read_maybe_%s_key %s_repr_jumper parse_%s_cases read_%s_cases %s (_ by (LP.dep_maybe_enum_destr_t_tac ())) (_ by (LP.enum_repr_of_key_tac %s_enum)) ()\n\n" n tn tn n n (pulse_leaf_reader_name dt) tn);

        (* Pulse: sum/dsum writer *)
        wp i "val %s_writer : LPS.l2r_leaf_writer %s_serializer\n\n" n n;
        wp o "let %s_writer =\n%s" n same_kind;
        (match def with
         | None ->
            wp o "  LPPS.l2r_leaf_write_sum %s_sum %s_repr_serializer write_%s_key serialize_%s_cases write_%s_cases (_ by (LP.dep_enum_destr_tac ()))\n\n" n tn tn n n;
         | Some dt ->
            wp o "  LPPS.l2r_leaf_write_dsum %s_sum %s_repr_serializer write_maybe_%s_key parse_%s_cases serialize_%s_cases write_%s_cases %s (_ by (LP.dep_enum_destr_tac ()))\n\n" n tn tn n n n (pulse_leaf_writer_name dt));

        (* Pulse: structural sum/dsum leaf_size (parallel to writer) *)
        wp i "val %s_leaf_size : LPS.leaf_size %s_serializer\n\n" n n;
        wp o "let %s_leaf_size =\n%s" n same_kind;
        (match def with
         | None ->
            wp o "  LPPS.leaf_size_sum %s_sum %s_repr_serializer size_%s_key serialize_%s_cases size_%s_cases (_ by (LP.dep_enum_destr_tac ())) (_ by (FStar.Tactics.norm [delta; iota; zeta; primops]; FStar.Tactics.smt ()))\n\n" n tn tn n n;
         | Some dt ->
            wp o "  LPPS.leaf_size_dsum %s_sum %s_repr_serializer size_maybe_%s_key parse_%s_cases serialize_%s_cases size_%s_cases %s (_ by (LP.dep_enum_destr_tac ())) (_ by (FStar.Tactics.norm [delta; iota; zeta; primops]; FStar.Tactics.smt ()))\n\n" n tn tn n n n (pulse_leaf_size_name dt));


        let annot = if is_private then " : LL.serializer32 "^(scombinator_name n) else "" in
        wl i "val %s_lserializer: LL.serializer32 %s\n\n" n (scombinator_name n);
        wl o "let %s_lserializer%s =\n%s" n annot same_kind;
        (match def with
         | None ->
            wl o "  LL.serialize32_sum %s_sum %s_repr_serializer lserialize_%s_key serialize_%s_cases lserialize_%s_cases (_ by (LP.dep_enum_destr_tac ()))\n\n" n tn tn n n
         | Some dt ->
            wl o "  assert_norm (LS.serializer32_sum_gen_precond (LP.get_parser_kind %s_repr_parser) (LP.weaken_parse_dsum_cases_kind %s_sum parse_%s_cases %s_parser_kind));\n" tn n n n;
            wl o "  LL.serialize32_dsum %s_sum %s_repr_serializer lserialize_maybe_%s_key parse_%s_cases serialize_%s_cases lserialize_%s_cases %s (_ by (LP.dep_enum_destr_tac ()))\n\n" n tn tn n n n (lscombinator_name dt))
    end;

    (* Pulse: copyful parser + free for non-implicit sums.
       For a fully leaf-readable sum (all payloads flat / by-value), the copyful
       parser is the existing leaf reader: it copies the whole value out of the
       input into a fresh, owned, buffer-free value (vmatch = pure equality, free
       = no-op). This works for both closed and open (default) sums. Sums with
       owned byte/list payloads need an owned low representation and are handled
       in a later layer. *)
    if !emit_pulse then begin
      if li.has_lserializer then begin
        emit_copyful_leaf o i n;
        emit_copyful_safe_leaf_writer_vl o i n
      end
      else if def = None then
        emit_copyful_owned_sum o i n tn cprefix cl
      else if not is_implicit then
        (match def with Some dt -> emit_copyful_owned_dsum o i n tn cprefix cl dt | None -> ())
    end;

    (* validity from sum to tag *)
      let maybe = match def with
        | None -> ""
        | _ -> "maybe_"
      in
      wl i "val lemma_valid_%s_valid_%s: #rrel: _ -> #rel: _ -> s:LL.slice rrel rel -> pos:U32.t -> h:HyperStack.mem -> Lemma\n" n tn;
      wl i "  (requires LL.valid %s_parser h s pos)\n" n;
      wl i "  (ensures (LL.valid %s_parser h s pos /\\ LL.contents %s_parser h s pos == tag_of_%s (LL.contents %s_parser h s pos)))\n" tn tn n n;
      wl i "  [SMTPat (LL.valid %s_parser h s pos)]\n\n" n;
      wl o "let lemma_valid_%s_valid_%s #_ #_ s pos h =\n%s" n tn same_kind;
      begin match def with
      | None ->
         wl o "  LL.valid_sum_elim_tag h %s_sum %s_repr_parser parse_%s_cases s pos;\n" n tn n
      | Some dt ->
         wl o "  LL.valid_dsum_elim_tag h %s_sum %s_repr_parser parse_%s_cases %s s pos;\n" n tn n (pcombinator_name dt)
      end;
      wl o "  lemma_synth_%s_inj ();\n" tn;
      wl o "  LL.valid_synth h parse_%s%s_key synth_%s s pos\n" maybe tn tn;
      wl o "\n";

      (* tag accessor *) 
      wl i "noextract let %s_clens_tag : LL.clens %s %s = {\n" n n tn;
      wl i "  LL.clens_cond = (fun _ -> True);\n";
      wl i "  LL.clens_get = (fun (x: %s) -> tag_of_%s x);\n" n n;
      wl i "}\n\n";
      wp i "noextract let %s_clens_tag : LowParse.CLens.clens %s %s = {\n" n n tn;
      wp i "  LowParse.CLens.clens_cond = (fun _ -> True);\n";
      wp i "  LowParse.CLens.clens_get = (fun (x: %s) -> tag_of_%s x);\n" n n;
      wp i "}\n\n";
      wl i "val %s_gaccessor_tag : LL.gaccessor %s_parser %s %s_clens_tag\n\n" n n (pcombinator_name tn) n;
      wl i "val %s_accessor_tag : LL.accessor %s_gaccessor_tag\n\n" n n;
      let print_tag_accessor g =
        let sum_tag_acc =
        match def with
        | None -> sprintf "LL.%saccessor_sum_tag %s_sum %s_repr_parser parse_%s_cases" g n tn n
        | Some dt -> sprintf "LL.%saccessor_dsum_tag %s_sum %s_repr_parser parse_%s_cases %s" g n tn n (pcombinator_name dt)
        in
        wl o "let %s_%saccessor_tag =\n" n g;
        wl o "%s" same_kind;
        wl o "  lemma_synth_%s_inj ();\n" tn;
        wl o "  lemma_synth_%s_inv ();\n" tn;
        wl o "  LL.%saccessor_ext\n" g;
        wl o "    (LL.%saccessor_compose\n" g;
        wl o "      (%s)\n" sum_tag_acc;
        wl o "      (LL.%saccessor_synth_inv parse_%s%s_key synth_%s synth_%s_inv ())\n" g maybe tn tn tn;
        wl o "    )\n";
        wl o "    %s_clens_tag\n" n;
        wl o "    ()\n\n";
        ()
      in
      print_tag_accessor "g";
      print_tag_accessor "";

      (* Pulse: tag accessor *)
      begin
        let sum_tag_acc = match def with
          | None -> sprintf "PPS.accessor_sum_tag %s_sum %s_repr_jumper parse_%s_cases ()" n tn n
          | Some dt -> sprintf "PPS.accessor_dsum_tag %s_sum %s_repr_jumper parse_%s_cases %s ()" n tn n (pcombinator_name dt)
        in
        wp i "val %s_accessor_tag : PPB.accessor %s_parser %s %s_clens_tag\n\n" n n (pcombinator_name tn) n;
        wp o "let %s_accessor_tag : PPB.accessor %s_parser %s %s_clens_tag =\n" n n (pcombinator_name tn) n;
        wp o "%s" same_kind;
        wp o "  lemma_synth_%s_inj ();\n" tn;
        wp o "  lemma_synth_%s_inv ();\n" tn;
        wp o "  PPC.accessor_ext\n";
        wp o "    (PPC.accessor_compose\n";
        wp o "      (%s)\n" sum_tag_acc;
        wp o "      (PPC.accessor_synth_fwd synth_%s synth_%s_inv)\n" tn tn;
        wp o "      ()\n";
        wp o "    )\n";
        wp o "    %s_clens_tag\n" n;
        wp o "    ()\n\n";
      end;

    (* bytesize *)
    begin match def with
    | None ->
       List.iter
         (function (case, ty) when ty <> "Fail" ->
           let constr = sprintf "%s_%s" cprefix case in
           w i "val %s_bytesize_eqn_%s (x: %s) : Lemma (%s_bytesize (%s x) == %d + %s) [SMTPat (%s_bytesize (%s x))]\n\n" n case (compile_type ty) n constr taglen (bytesize_call ty "x") n constr;
           w o "let %s_bytesize_eqn_%s x =\n" n case;
           w o "  %s\n" same_kind;
           w o "  LP.serialize_sum_eq %s_sum %s_repr_serializer serialize_%s_cases (%s x);\n" n tn n constr;
           w o "  (let ln = FStar.Seq.length (LP.serialize (LP.serialize_enum_key _ %s_repr_serializer (LP.sum_enum %s_sum)) (key_of_%s (%s x))) in assert (%d <= ln /\\ ln <= %d));\n" tn n n constr taglen taglen;
           w o "  %s\n\n" (bytesize_eq_call ty "x")
                 | _ -> ()
         )
         cl
    | Some dt ->
       let write_constr vbind vvar (case, ty) =
         if ty <> "Fail" then begin
           let constr = sprintf "%s_%s" cprefix case in
           w i "val %s_bytesize_eqn_%s %s (x: %s) : Lemma (%s_bytesize (%s %s x) == %d + %s) [SMTPat (%s_bytesize (%s %s x))]\n\n" n case vbind (compile_type ty) n constr vvar taglen (bytesize_call ty "x") n constr vvar;
           w o "let %s_bytesize_eqn_%s %s x =\n" n case vvar;
           w o "  %s\n" same_kind;
           w o "  LP.serialize_dsum_eq %s_sum %s_repr_serializer parse_%s_cases serialize_%s_cases %s %s (%s %s x) ;\n" n tn n n (pcombinator_name dt) (scombinator_name dt) constr vvar;
           w o "  let tg = LP.dsum_tag_of_data %s_sum (%s %s x) in\n" n constr vvar;
           if vvar = "" then
             w o "  assert_norm (tg == LP.Known (known_%s_as_enum_key %s));\n" tn (String.capitalize_ascii case)
           else
             w o "  assert_norm (tg == LP.Unknown (unknown_%s_as_enum_key %s));\n" tn vvar;
           w o "  (let ln = FStar.Seq.length (LP.serialize (LP.serialize_maybe_enum_key _ %s_repr_serializer (LP.dsum_enum %s_sum)) tg) in assert (%d <= ln /\\ ln <= %d));\n" tn n taglen taglen;
           w o "  %s\n\n" (bytesize_eq_call ty "x")
         end
       in
       List.iter (write_constr "" "") cl;
       write_constr (sprintf "(v: %s_repr { not (known_%s_repr v) } )" tn tn) "v" (sprintf "Unknown_%s" tn, dt)
    end;
    (* accessors *)
    begin
      let d = match def with None -> "" | _ -> "d" in
      let unknown_parser =
        match def with
        | None -> ""
        | Some dt -> pcombinator_name dt
        in
       List.iter
         (fun (case, ty) ->
           if ty <> "Fail" && ty <> "Empty" then
             begin
               let ty0 = compile_type ty in
               wl i "noextract let %s_clens_%s : LL.clens %s %s = {\n" n case n ty0;
               wl i "  LL.clens_cond = (fun (x: %s) -> tag_of_%s x == %s);\n" n n (String.capitalize_ascii case);
               wl i "  LL.clens_get = (fun (x: %s) -> (match x with %s_%s y -> y) <: (Ghost %s (requires (tag_of_%s x == %s)) (ensures (fun y -> True))));\n" n cprefix case ty0 n (String.capitalize_ascii case);
               wl i "}\n\n";
               wp i "noextract let %s_clens_%s : LowParse.CLens.clens %s %s = {\n" n case n ty0;
               wp i "  LowParse.CLens.clens_cond = (fun (x: %s) -> tag_of_%s x == %s);\n" n n (String.capitalize_ascii case);
               wp i "  LowParse.CLens.clens_get = (fun (x: %s) -> (match x with %s_%s y -> y) <: (Ghost %s (requires (tag_of_%s x == %s)) (ensures (fun y -> True))));\n" n cprefix case ty0 n (String.capitalize_ascii case);
               wp i "}\n\n";
               wl i "val %s_gaccessor_%s : LL.gaccessor %s_parser %s %s_clens_%s\n\n" n case n (pcombinator_name ty) n case;
               wl o "noextract let %s_clens'_%s : LL.clens %s %s = LL.clens_%ssum_payload %s_sum " n case n ty0 d n;
               if d = "" then
                 wl o "(%s_as_enum_key %s)\n\n" tn (String.capitalize_ascii case)
               else
                 wl o "(LL.Known (known_%s_as_enum_key %s))\n\n" tn (String.capitalize_ascii case);
               wl o "let %s_gaccessor'_%s : LL.gaccessor %s_parser %s %s_clens'_%s =\n" n case n (pcombinator_name ty) n case;
               let write_accessor' g parser_or_jumper =
                 wl o "[@inline_let] let _ = %s () in\n" same_kind;
                 wl o "  LL.%saccessor_clens_%ssum_payload\n" g d;
                 wl o "    %s_sum\n" n;
                 wl o "    %s_repr_%s\n" tn parser_or_jumper;
                 wl o "    parse_%s_cases\n" n;
                 if d = "" then
                   wl o "    (%s_as_enum_key %s)\n" tn (String.capitalize_ascii case)
                 else begin
                   wl o "    %s\n" unknown_parser;
                   wl o "    (LL.Known (known_%s_as_enum_key %s))\n" tn (String.capitalize_ascii case)
                 end;
                 wl o "\n"
               in
               write_accessor' "g" "parser";
               wl o "inline_for_extraction\n";
               wl o "let %s_accessor'_%s : LL.accessor %s_gaccessor'_%s =\n" n case n case;
               write_accessor' "" "jumper";
               wl o "let %s_clens_eq_%s : squash (LL.clens_eq %s_clens'_%s %s_clens_%s) =\n" n case n case n case;
               wl o "    (_ by (LL.sum_accessor_ext (`%s)))\n\n" n;
               let write_accessor g =
                 wl o "let %s_%saccessor_%s =\n" n g case;
                 wl o "  LL.%saccessor_ext\n" g;
                 wl o "    %s_%saccessor'_%s\n" n g case;
                 wl o "    %s_clens_%s\n" n case;
                 wl o "    %s_clens_eq_%s\n\n" n case
               in
               write_accessor "g";
               wl i "val %s_accessor_%s : LL.accessor %s_gaccessor_%s\n\n" n case n case;
               write_accessor "";
               (* Pulse: payload accessor *)
               begin
                 wp i "val %s_accessor_%s : PPB.accessor %s_parser %s %s_clens_%s\n\n" n case n (pcombinator_name ty) n case;
                 wp o "let %s_accessor_%s : PPB.accessor %s_parser %s %s_clens_%s =\n" n case n (pcombinator_name ty) n case;
                 (match d with
                 | "" ->
                   wp o "  PPC.accessor_ext\n";
                   wp o "    (PPS.accessor_clens_sum_payload %s_sum %s_repr_jumper parse_%s_cases (%s_as_enum_key %s) ())\n" n tn n tn (String.capitalize_ascii case);
                   wp o "    %s_clens_%s\n" n case;
                   wp o "    ()\n\n"
                 | _ ->
                   wp o "  PPC.accessor_ext\n";
                   wp o "    (PPS.accessor_clens_dsum_payload %s_sum %s_repr_jumper parse_%s_cases %s (LowParse.Spec.Enum.Known (known_%s_as_enum_key %s)) ())\n" n tn n unknown_parser tn (String.capitalize_ascii case);
                   wp o "    %s_clens_%s\n" n case;
                   wp o "    ()\n\n");
               end;
               ()
             end
         )
         cl;
       match def with
       | Some dt when dt <> "Empty" && dt <> "Fail" ->
          (* accessor to the default case payload *)
          let dt0 = compile_type dt in
          wl i "noextract let %s_clens_Unknown : LL.clens %s %s = {\n" n n dt0;
          wl i "  LL.clens_cond = (fun (x: %s) -> %s_Unknown_%s? x);\n" n cprefix tn;
          wl i "  LL.clens_get = (fun (x: %s) -> (match x with %s_Unknown_%s _ y -> y) <: (Ghost %s (requires (%s_Unknown_%s? x)) (ensures (fun y -> True))));\n" n cprefix tn dt0 cprefix tn;
          wl i "}\n\n";
          wp i "noextract let %s_clens_Unknown : LowParse.CLens.clens %s %s = {\n" n n dt0;
          wp i "  LowParse.CLens.clens_cond = (fun (x: %s) -> %s_Unknown_%s? x);\n" n cprefix tn;
          wp i "  LowParse.CLens.clens_get = (fun (x: %s) -> (match x with %s_Unknown_%s _ y -> y) <: (Ghost %s (requires (%s_Unknown_%s? x)) (ensures (fun y -> True))));\n" n cprefix tn dt0 cprefix tn;
          wp i "}\n\n";
          wl o "let %s_clens_eq_Unknown : squash (LL.clens_eq (LL.clens_dsum_unknown_payload %s_sum) %s_clens_Unknown) =\n" n n n;
          wl o "    (_ by (LL.sum_accessor_ext (`%s)))\n\n" n;
          let write_accessor g parser_or_jumper =
            wl o "let %s_%saccessor_Unknown =\n" n g;
            wl o "  [@inline_let] let _ = %s () in\n" same_kind;
            wl o "  LL.%saccessor_ext\n" g;
            wl o "    (LL.%saccessor_clens_dsum_unknown_payload\n" g;
            wl o "      %s_sum\n" n;
            wl o "      %s_repr_%s\n" tn parser_or_jumper;
            wl o "      parse_%s_cases\n" n;
            wl o "      %s\n" (pcombinator_name dt);
            wl o "    )\n";
            wl o "    %s_clens_Unknown\n" n;
            wl o "    %s_clens_eq_Unknown\n\n" n
          in
          wl i "val %s_gaccessor_Unknown : LL.gaccessor %s_parser %s %s_clens_Unknown\n\n" n n (pcombinator_name dt) n;
          write_accessor "g" "parser";
          wl i "val %s_accessor_Unknown : LL.accessor %s_gaccessor_Unknown\n\n" n n;
          write_accessor "" "jumper";
          (* Pulse: Unknown accessor *)
          begin
            wp i "val %s_accessor_Unknown : PPB.accessor %s_parser %s %s_clens_Unknown\n\n" n n (pcombinator_name dt) n;
            wp o "let %s_accessor_Unknown : PPB.accessor %s_parser %s %s_clens_Unknown =\n" n n (pcombinator_name dt) n;
            wp o "  PPC.accessor_ext\n";
            wp o "    (PPS.accessor_clens_dsum_unknown_payload %s_sum %s_repr_jumper parse_%s_cases %s ())\n" n tn n (pcombinator_name dt);
            wp o "    %s_clens_Unknown\n" n;
            wp o "    ()\n\n";
          end
       | _ -> ()
    end;
    (* finalizers *)
    let write_finalizer case =
      wl o "  [@inline_let] let _ = %s" same_kind;
      match def with
      | None ->
         wl o "    let tg = %s_as_enum_key %s in\n" tn (String.capitalize_ascii case);
         wl o "    let len = LL.serialized_length (LP.serialize_enum_key _ %s_repr_serializer (LP.sum_enum %s_sum)) tg in\n" tn n;
         wl o "    let pk = LP.get_parser_kind (LP.parse_enum_key %s_repr_parser (LP.sum_enum %s_sum)) in\n" tn n;
         wl o "    assert_norm (pk.LP.parser_kind_low == %d /\\ pk.LP.parser_kind_high == Some %d);\n" taglen taglen;
         wl o "    assert (%d <= len /\\ len <= %d);\n" taglen taglen;
         wl o "    assert_norm (pow2 32 == 4294967296)\n";
         wl o "  in\n";
         wl o "  LL.finalize_sum_case %s_sum %s_repr_serializer %s_repr_writer parse_%s_cases (_ by (LP.enum_repr_of_key_tac %s_enum)) (%s_as_enum_key %s) input pos\n\n" n tn tn n tn tn (String.capitalize_ascii case)
      | Some dt ->
         wl o "    let tg = known_%s_as_enum_key %s in\n" tn (String.capitalize_ascii case);
         wl o "    let len = LL.serialized_length (LP.serialize_enum_key _ %s_repr_serializer (LP.dsum_enum %s_sum)) tg in\n" tn n;
         wl o "    let pk = LP.get_parser_kind (LP.parse_enum_key %s_repr_parser (LP.dsum_enum %s_sum)) in\n" tn n;
         wl o "    assert_norm (pk.LP.parser_kind_low == %d /\\ pk.LP.parser_kind_high == Some %d);\n" taglen taglen;
         wl o "    assert (%d <= len /\\ len <= %d);\n" taglen taglen;
         wl o "    assert_norm (pow2 32 == 4294967296)\n";
         wl o "  in\n";
         wl o "  LL.finalize_dsum_case_known %s_sum %s_repr_serializer %s_repr_writer parse_%s_cases %s (_ by (LP.enum_repr_of_key_tac %s_enum)) (known_%s_as_enum_key %s) input pos\n\n" n tn tn n (pcombinator_name dt) tn tn (String.capitalize_ascii case)
    in
       List.iter
         (fun (case, ty) ->
           let constr = sprintf "%s_%s" cprefix case in
           let casep = pcombinator_name ty in
           match ty with
           | "Fail" -> () (* impossible case *)
           | "Empty" -> (* parse_empty is not in the user context, so we need to "inline" it here *)
              wl i "val finalize_%s_%s (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : HST.Stack unit\n" n case;
              wl i "  (requires (fun h ->\n";
              wl i "    assert_norm (pow2 32 == 4294967296);\n";
              wl i "    LL.live_slice h input /\\ U32.v pos + %d <= U32.v input.LL.len /\\ LL.writable input.LL.base (U32.v pos) (U32.v pos + %d) h))\n" taglen taglen;
              wl i "  (ensures (fun h _ h' ->\n";
              wl i "    assert_norm (pow2 32 == 4294967296);\n";
              wl i "    let pos_payload = pos `U32.add` %dul in\n" taglen;
              wl i "    B.modifies (LL.loc_slice_from_to input pos pos_payload) h h' /\\\n";
              wl i "    LL.valid_content_pos %s_parser h' input pos (%s ()) pos_payload\n" n constr;
              wl i "  ))\n\n";
              wl o "let finalize_%s_%s #_ #_ input pos =\n" n case;
              wl o "  let h = HST.get () in\n";
              wl o "  [@inline_let] let _ = LL.valid_facts LL.parse_empty h input (pos `U32.add` %dul) in\n" taglen;
              write_finalizer case
           | _ ->
              wl i "val finalize_%s_%s (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : HST.Stack unit\n" n case;
              wl i "  (requires (fun h ->\n";
              wl i "    assert_norm (pow2 32 == 4294967296);\n";
              wl i "U32.v pos + %d < 4294967296 /\\ LL.valid %s h input (pos `U32.add` %dul) /\\ LL.writable input.LL.base (U32.v pos) (U32.v pos + %d) h))\n" taglen casep taglen taglen;
              wl i "  (ensures (fun h _ h' ->\n";
              wl i "    assert_norm (pow2 32 == 4294967296);\n";
              wl i "    let pos_payload = pos `U32.add` %dul in\n" taglen;
              wl i "    B.modifies (LL.loc_slice_from_to input pos pos_payload) h h' /\\\n";
              wl i "    LL.valid_content_pos %s_parser h' input pos (%s (LL.contents %s h input pos_payload)) (LL.get_valid_pos %s h input pos_payload)\n" n constr casep casep;
              wl i "  ))\n\n";
              wl o "let finalize_%s_%s #_ #_ input pos =\n" n case;
              write_finalizer case
         )
         cl
     ;
       (* finalizer for unknown case *)
       begin match def with
       | Some dt when dt <> "Fail" ->
          let dp = pcombinator_name dt in
          wl i "val finalize_%s_Unknown_%s (v: %s_repr) (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : HST.Stack unit\n" n tn tn;
          wl i "  (requires (fun h ->\n";
          wl i "    assert_norm (pow2 32 == 4294967296);\n";
          if dt = "Empty" then
            wl i "    U32.v pos + %d <= U32.v input.LL.len /\\ LL.live_slice h input /\\ not (known_%s_repr v) /\\ LL.writable input.LL.base (U32.v pos) (U32.v pos + %d) h))\n" taglen tn taglen
          else
            wl i "  U32.v pos + %d < 4294967296 /\\ LL.valid %s h input (pos `U32.add` %dul) /\\ not (known_%s_repr v) /\\ LL.writable input.LL.base (U32.v pos) (U32.v pos + %d) h))\n" taglen dp taglen tn taglen
          ;
          wl i "  (ensures (fun h _ h' ->\n";
          wl i "    assert_norm (pow2 32 == 4294967296);\n";
          wl i "    let pos_payload = pos `U32.add` %dul in\n" taglen;
          wl i "    B.modifies (LL.loc_slice_from_to input pos pos_payload) h h' /\\\n";
          if dt = "Empty" then
            wl i "    LL.valid_content_pos %s_parser h' input pos (%s_Unknown_%s v ()) pos_payload\n" n cprefix tn
          else
            wl i "    LL.valid_content_pos %s_parser h' input pos (%s_Unknown_%s v (LL.contents %s h input pos_payload)) (LL.get_valid_pos %s h input pos_payload)\n" n cprefix tn dp dp
          ;
          wl i "  ))\n\n";
          wl o "let finalize_%s_Unknown_%s v #_ #_ input pos =\n" n tn;
          wl o "  [@inline_let] let _ =\n";
          wl o "    %s\n" same_kind;
          wl o "    let tg = unknown_%s_as_enum_key v in\n" tn;
          wl o "    let len = LL.serialized_length %s_repr_serializer tg in\n" tn;
          wl o "    assert (%d <= len /\\ len <= %d);\n" taglen taglen;
          wl o "    assert_norm (pow2 32 == 4294967296)\n";
          wl o "  in\n";
          if dt = "Empty" then begin
            wl o "  let h = HST.get () in\n";
            wl o "  [@inline_let] let _ = LL.valid_facts LL.parse_empty h input (pos `U32.add` %dul) in\n" taglen;
          end;
          wl o "  LL.finalize_dsum_case_unknown %s_sum %s_repr_serializer %s_repr_writer parse_%s_cases %s (unknown_%s_as_enum_key v) input pos\n\n" n tn tn n dp tn
       | _ -> ()
       end
  end

and compile_vldata o i is_private n ty li elem_li lenty smin smax =
  let (min, max) = li.min_len, li.max_len in
  let fits_in_bounds = smin <= elem_li.min_len && elem_li.max_len <= smax in
  let need_validator = is_private || need_validator li.meta li.min_len li.max_len in
  let need_jumper = is_private || need_jumper li.min_len li.max_len in
  if fits_in_bounds then
   begin
    w i "%stype %s = %s\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n (compile_type ty);
    write_api o i false is_private li.meta n min max;
    w o "let %s_parser' =\n" n;
    w o "  LP.parse_vlgen %d %d %s %s\n\n" smin smax (pcombinator_length_header_name lenty smin smax) (scombinator_name ty);
    let kind_eq = sprintf "(LP.get_parser_kind %s_parser' == %s_parser_kind)" n n in
    w o "let %s_kind_eq : squash %s = assert_norm %s\n\n" n kind_eq kind_eq;
    w o "let %s_parser = %s_parser'\n\n" n n;
    w o "let %s_serializer =\n" n;
    w o "  LP.serialize_vlgen %d %d %s %s\n\n" smin smax (scombinator_length_header_name lenty smin smax) (scombinator_name ty);
    write_bytesize o is_private n;
    wh o "let %s_parser32 =\n" n;
    wh o "  LS.parse32_vlgen %d %dul %d %dul %s %s %s\n\n" smin smin smax smax (pcombinator32_length_header_name lenty smin smax) (scombinator_name ty) (pcombinator32_name ty);
    wh o "let %s_serializer32 =\n" n;
    wh o "  LS.serialize32_vlgen %d %d %s %s\n\n" smin smax (scombinator32_length_header_name lenty smin smax) (scombinator32_name ty);
    wh o "let %s_size32 =\n" n;
    wh o "  LSZ.size32_vlgen %d %d %s %s\n\n" smin smax (size32_length_header_name lenty smin smax) (size32_name ty);
    if need_validator then (
      wl o "let %s_validator =\n" n;
      wl o "  LL.validate_vlgen %d %dul %d %dul %s %s %s %s\n\n" smin smin smax smax (validator_length_header_name lenty smin smax) (reader_length_header_name lenty smin smax) (scombinator_name ty) (validator_name ty);
    );
    if need_validator then (
      wp o "let %s_validator =\n" n;
      wp o "  PPVG.validate_vlgen %d %d %s %s %s %s ()\n\n" smin smax (pulse_validator_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax) (scombinator_name ty) (pulse_validator_name ty);
    );
    if need_jumper then (
      let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
      wl o "let %s_jumper%s =\n\n" n jumper_annot;
      wl o "  LL.jump_vlgen %d %d %s %s %s\n\n" smin smax (jumper_length_header_name lenty smin smax) (reader_length_header_name lenty smin smax) (scombinator_name ty)
    );
    if need_jumper then (
      let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
      wp o "let %s_jumper%s =\n" n jumper_annot;
      wp o "  PPVG.jump_vlgen %d %d %s %s %s ()\n\n" smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax) (scombinator_name ty)
    );
    (* accessor *)
    if ty <> "Empty" && ty <> "Fail" then begin
      wl i "val %s_gaccessor : LL.gaccessor %s_parser %s (LL.clens_id %s)\n\n" n n (pcombinator_name ty) (compile_type ty);
      wl o "let %s_gaccessor = LL.gaccessor_vlgen_payload %d %d %s %s\n\n" n smin smax (pcombinator_length_header_name lenty smin smax) (scombinator_name ty);
      wl i "val %s_accessor : LL.accessor %s_gaccessor\n\n" n n;
      wl o "let %s_accessor = LL.accessor_vlgen_payload %d %d %s %s\n\n" n smin smax (jumper_length_header_name lenty smin smax) (scombinator_name ty);
      wp i "val %s_accessor : PPB.accessor %s_parser %s (LowParse.CLens.clens_id %s)\n\n" n n (pcombinator_name ty) (compile_type ty);
      wp o "let %s_accessor = PPVG.accessor_vlgen_payload %d %d %s %s %s ()\n\n" n smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax) (scombinator_name ty);
      ()
    end;
    (if !emit_pulse then emit_copyful_vlgen_payload o i n ty smin smax lenty);
    (* TODO: intro lemmas *)
   ()
   end
  else
   begin
    let sizef =
      if basic_type ty then sprintf "Seq.length (LP.serialize %s x)" (scombinator_name ty)
      else bytesize_call ty "x" in
    w i "%stype %s = x:%s{let l = %s in %d <= l /\\ l <= %d}\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n (compile_type ty) sizef smin smax;
    w (ipub i o) "%stype %s' = LP.parse_bounded_vldata_strong_t %d %d %s\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n smin smax (scombinator_name ty);
    w (ipub i o) "inline_for_extraction %slet synth_%s (x: %s') : Tot %s =\n" (if !emit_pulse then "noextract " else "") n n n;
    w (ipub i o) "  [@inline_let] let _ = %s in x\n\n" (bytesize_eq_call ty "x");
    w (ipub i o) "inline_for_extraction %slet synth_%s_recip (x: %s) : Tot %s' =\n" (if !emit_pulse then "noextract " else "") n n n;
    w (ipub i o) "  [@inline_let] let _ = %s in x\n\n" (bytesize_eq_call ty "x");
    write_api o i false is_private li.meta n min max;
    w o "noextract let %s'_parser : LP.parser _ %s' =\n" n n;
    w o "  LP.parse_bounded_vlgen %d %d %s %s\n\n" smin smax (pcombinator_length_header_name lenty smin smax) (scombinator_name ty);
    let kind_eq = sprintf "(LP.get_parser_kind %s'_parser == %s_parser_kind)" n n in
    w o "let %s_kind_eq : squash %s = assert_norm %s\n\n" n kind_eq kind_eq;
    w o "let %s_parser = LP.parse_synth %s'_parser synth_%s\n\n" n n n;
    w o "noextract let %s'_serializer : LP.serializer %s'_parser =\n" n n;
    w o "  LP.serialize_bounded_vlgen %d %d %s %s\n\n" smin smax (scombinator_length_header_name lenty smin smax) (scombinator_name ty);
    w o "let %s_serializer = LP.serialize_synth _ synth_%s %s'_serializer synth_%s_recip ()\n\n" n n n n;
    write_bytesize o is_private n;
    wh o "inline_for_extraction noextract let %s'_parser32 : LS.parser32 %s'_parser =\n" n n;
    wh o "  LS.parse32_bounded_vlgen %d %dul %d %dul %s %s %s\n\n" smin smin smax smax (pcombinator32_length_header_name lenty smin smax) (scombinator_name ty) (pcombinator32_name ty);
    wh o "let %s_parser32 = LS.parse32_synth' _ synth_%s %s'_parser32 ()\n\n" n n n;
    wh o "inline_for_extraction noextract let %s'_serializer32 : LS.serializer32 %s'_serializer =\n" n n;
    wh o "  LS.serialize32_bounded_vlgen %d %d %s %s\n\n" smin smax (scombinator32_length_header_name lenty smin smax) (scombinator32_name ty);
    wh o "let %s_serializer32 = LS.serialize32_synth' _ synth_%s _ %s'_serializer32 synth_%s_recip ()\n\n" n n n n;
    wh o "inline_for_extraction noextract let %s'_size32 : LSZ.size32 %s'_serializer =\n" n n;
    wh o "  LSZ.size32_bounded_vlgen %d %d %s %s\n\n" smin smax (size32_length_header_name lenty smin smax) (size32_name ty);
    wh o "let %s_size32 = LSZ.size32_synth' _ synth_%s _ %s'_size32 synth_%s_recip ()\n\n" n n n n;
    if need_validator then (
      wl o "inline_for_extraction let %s'_validator : LL.validator %s'_parser =\n" n n;
      wl o "  LL.validate_bounded_vlgen %d %dul %d %dul %s %s %s %s\n\n" smin smin smax smax (validator_length_header_name lenty smin smax) (reader_length_header_name lenty smin smax) (scombinator_name ty) (validator_name ty);
      wl o "let %s_validator = LL.validate_synth %s'_validator synth_%s ()\n\n" n n n
    );
    if need_validator then (
      wp o "inline_for_extraction let %s'_validator : LPS.validator %s'_parser =\n" n n;
      wp o "  PPVG.validate_bounded_vlgen %d %d %s %s %s %s ()\n\n" smin smax (pulse_validator_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax) (scombinator_name ty) (pulse_validator_name ty);
      wp o "let %s_validator = LPC.validate_synth %s'_validator synth_%s\n\n" n n n
    );
    if need_jumper then (
      wl o "inline_for_extraction let %s'_jumper : LL.jumper %s'_parser =\n" n n;
      wl o "  LL.jump_bounded_vlgen %d %d %s %s %s\n\n" smin smax (jumper_length_header_name lenty smin smax) (reader_length_header_name lenty smin smax) (scombinator_name ty);
      let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
      wl o "let %s_jumper%s = LL.jump_synth %s'_jumper synth_%s ()\n\n" n jumper_annot n n
    );
    if need_jumper then (
      wp o "inline_for_extraction let %s'_jumper : LPS.jumper %s'_parser =\n" n n;
      wp o "  PPVG.jump_bounded_vlgen %d %d %s %s %s ()\n\n" smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax) (scombinator_name ty);
      let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
      wp o "let %s_jumper%s = LPC.jump_synth %s'_jumper synth_%s\n\n" n jumper_annot n n
    );
    (* TODO: intro lemmas *)
    (* accessor *)
    wl i "noextract let %s_clens : LL.clens %s %s = {\n" n n (compile_type ty);
    wl i "  LL.clens_cond = (fun _ -> True);\n";
    wl i "  LL.clens_get = (fun (x: %s) -> (x <: %s));\n" n (compile_type ty);
    wl i "}\n\n";
    wl i "val %s_gaccessor : LL.gaccessor %s_parser %s %s_clens\n\n" n n (pcombinator_name ty) n;
    let write_accessor g jumper_or_parser =
      wl o "let %s_%saccessor =\n" n g;
      wl o "  LL.%saccessor_ext\n" g;
      wl o "    (LL.%saccessor_compose\n" g;
      wl o "      (LL.%saccessor_synth %s'_parser synth_%s synth_%s_recip ())\n" g n n n;
      wl o "      (LL.%saccessor_bounded_vlgen_payload %d %d %s %s)\n" g smin smax jumper_or_parser (scombinator_name ty);
      wl o "    )\n";
      wl o "    %s_clens\n" n;
      wl o "    ()\n\n";
      () in
    write_accessor "g" (pcombinator_length_header_name lenty smin smax);
    wl i "val %s_accessor : LL.accessor %s_gaccessor\n\n" n n;
    write_accessor "" (jumper_length_header_name lenty smin smax);
    (* Pulse: accessor *)
    wp i "noextract let %s_clens : LowParse.CLens.clens %s %s = {\n" n n (compile_type ty);
    wp i "  LowParse.CLens.clens_cond = (fun _ -> True);\n";
    wp i "  LowParse.CLens.clens_get = (fun (x: %s) -> (x <: %s));\n" n (compile_type ty);
    wp i "}\n\n";
    wp i "val %s_accessor : PPB.accessor %s_parser %s %s_clens\n\n" n n (pcombinator_name ty) n;
    wp o "inline_for_extraction noextract let %s_vlgen_acc = PPVG.accessor_bounded_vlgen_payload %d %d %s %s %s ()\n\n" n smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax) (scombinator_name ty);
    wp o "inline_for_extraction noextract let %s_synth_acc : PPB.accessor %s_parser %s'_parser _ = PPC.accessor_synth_inv synth_%s synth_%s_recip\n\n" n n n n n;
    wp o "inline_for_extraction noextract let %s_composed_acc = PPC.accessor_compose %s_synth_acc %s_vlgen_acc ()\n\n" n n n;
    wp o "let %s_accessor : PPB.accessor %s_parser %s %s_clens = PPC.accessor_ext %s_composed_acc %s_clens ()\n\n" n n (pcombinator_name ty) n n n;
    (if !emit_pulse then emit_copyful_vlgen_payload_refined o i n ty smin smax lenty);
    ()
   end;
  (* TODO: lemma about bytesize *)
  ()

and compile_vllist o i is_private n ty li elem_li lenty smin smax =
  let need_validator = is_private || need_validator li.meta li.min_len li.max_len in
  let need_jumper = is_private || need_jumper li.min_len li.max_len in
  (if !emit_pulse
   then w i "noextract let %s_list_bytesize (x: list %s) : GTot nat = Seq.length (LP.serialize (LP.serialize_list _ %s) x)\n\n" n (compile_type ty) (scombinator_name ty)
   else begin
     w i "noextract val %s_list_bytesize: list %s -> GTot nat\n\n" n (compile_type ty);
     w o "let %s_list_bytesize x = Seq.length (LP.serialize (LP.serialize_list _ %s) x)\n\n" n (scombinator_name ty)
   end);
  (* Under -pulse, the executable representation is the Vec-based [<n>_lowtype]
     (see emit_copyful_vllist); the spec list type [<n>] and the [synth_<n>]
     coercions below are only used by ghost/noextract spec definitions, so mark
     them noextract to keep the F* cons-list out of the extracted C.  In the
     LowStar (non-pulse) path the list IS the runtime representation, so they
     must stay extractable there. *)
  w i "%stype %s = l:list %s{let x = %s_list_bytesize l in %d <= x /\\ x <= %d}\n\n" (if !emit_pulse then "noextract " else "") n (compile_type ty) n smin smax;
  w i "val %s_list_bytesize_nil : squash (%s_list_bytesize [] == 0)\n\n" n n;
  w o "let %s_list_bytesize_nil = LP.serialize_list_nil %s %s\n\n" n (pcombinator_name ty) (scombinator_name ty);
  w i "val %s_list_bytesize_cons (x: %s) (y: list %s) : Lemma (%s_list_bytesize (x :: y) == %s + %s_list_bytesize y) [SMTPat (%s_list_bytesize (x :: y))]\n\n" n (compile_type ty) (compile_type ty) n (bytesize_call ty "x") n n;
  w o "let %s_list_bytesize_cons x y = LP.serialize_list_cons %s %s x y; %s\n\n" n (pcombinator_name ty) (scombinator_name ty) (bytesize_eq_call ty "x");
  wl i "val %s_list_bytesize_eq (l: list %s) : Lemma (%s_list_bytesize l == LL.serialized_list_length %s l)\n\n" n (compile_type ty) n (scombinator_name ty);
  wl o "let %s_list_bytesize_eq l = LL.serialized_list_length_eq_length_serialize_list %s l\n\n" n (scombinator_name ty);
  wh i "val check_%s_list_bytesize (l: list %s) : Tot (b: bool {b == (let x = %s_list_bytesize l in %d <= x && x <= %d)})\n\n" n (compile_type ty) n smin smax;
  wh o "let check_%s_list_bytesize l =\n" n;
  wh o "  let x = LSZ.size32_list %s () l in\n" (size32_name ty);
  wh o "  %dul `U32.lte` x && x `U32.lte` %dul\n\n" smin smax;
  w (ipub i o) "%stype %s' = LP.parse_bounded_vldata_strong_t %d %d (LP.serialize_list _ %s)\n\n" (if !emit_pulse then "noextract " else "") n smin smax (scombinator_name ty);
  w (ipub i o) "inline_for_extraction %slet synth_%s (x: %s') : Tot %s = x\n\n" (if !emit_pulse then "noextract " else "") n n n;
  w (ipub i o) "inline_for_extraction %slet synth_%s_recip (x: %s) : Tot %s' = x\n\n" (if !emit_pulse then "noextract " else "") n n n;
  write_api o i false is_private li.meta n li.min_len li.max_len;
  w o "noextract let %s'_parser : LP.parser _ %s' =\n" n n;
  w o "  LP.parse_bounded_vlgen %d %d %s (LP.serialize_list _ %s)\n\n" smin smax (pcombinator_length_header_name lenty smin smax) (scombinator_name ty);
  let kind_eq = sprintf "(LP.get_parser_kind %s'_parser == %s_parser_kind)" n n in
  w o "let %s_kind_eq : squash %s = assert_norm %s\n\n" n kind_eq kind_eq;
  w o "let %s_parser = LP.parse_synth %s'_parser synth_%s\n\n" n n n;
  w o "noextract let %s'_serializer : LP.serializer %s'_parser =\n" n n;
  w o "  LP.serialize_bounded_vlgen %d %d %s (LP.serialize_list _ %s)\n\n" smin smax (scombinator_length_header_name lenty smin smax) (scombinator_name ty);
  w o "let %s_serializer = LP.serialize_synth _ synth_%s %s'_serializer synth_%s_recip ()\n\n" n n n n;
  write_bytesize o is_private n;
  wh o "inline_for_extraction noextract let %s'_parser32 : LS.parser32 %s'_parser =\n" n n;
  wh o "  LS.parse32_bounded_vlgen %d %dul %d %dul %s (LP.serialize_list _ %s) (LS.parse32_list %s)\n\n" smin smin smax smax (pcombinator32_length_header_name lenty smin smax) (scombinator_name ty) (pcombinator32_name ty);
  wh o "let %s_parser32 = LS.parse32_synth' _ synth_%s %s'_parser32 ()\n\n" n n n;
  wh o "inline_for_extraction noextract let %s'_serializer32 : LS.serializer32 %s'_serializer =\n" n n;
  wh o "  LS.serialize32_bounded_vlgen %d %d %s (LS.partial_serialize32_list _ %s %s ())\n\n" smin smax (scombinator32_length_header_name lenty smin smax) (scombinator_name ty) (scombinator32_name ty);
  wh o "let %s_serializer32 = LS.serialize32_synth' _ synth_%s _ %s'_serializer32 synth_%s_recip ()\n\n" n n n n;
  wh o "inline_for_extraction noextract let %s'_size32 : LSZ.size32 %s'_serializer =\n" n n;
  wh o "  LSZ.size32_bounded_vlgen %d %d %s (LSZ.size32_list %s ())\n\n" smin smax (size32_length_header_name lenty smin smax) (size32_name ty);
  wh o "let %s_size32 = LSZ.size32_synth' _ synth_%s _ %s'_size32 synth_%s_recip ()\n\n" n n n n;
  if need_validator then (
    wl o "inline_for_extraction let %s'_validator : LL.validator %s'_parser =\n" n n;
    wl o "  LL.validate_bounded_vlgen %d %dul %d %dul %s %s (LP.serialize_list _ %s) (LL.validate_list %s ())\n\n" smin smin smax smax (validator_length_header_name lenty smin smax) (reader_length_header_name lenty smin smax) (scombinator_name ty) (validator_name ty);
    wl o "let %s_validator = LL.validate_synth %s'_validator synth_%s ()\n\n" n n n
  );
  if need_validator then (
    wp o "inline_for_extraction let %s'_validator : LPS.validator %s'_parser =\n" n n;
    wp o "  PPVG.validate_bounded_vlgen %d %d %s %s (LP.serialize_list _ %s) (PPLS.validate_list %s ()) ()\n\n" smin smax (pulse_validator_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax) (scombinator_name ty) (pulse_validator_name ty);
    wp o "let %s_validator = LPC.validate_synth %s'_validator synth_%s\n\n" n n n
  );
  if need_jumper then (
    wl o "inline_for_extraction let %s'_jumper : LL.jumper %s'_parser =\n" n n;
    wl o "  LL.jump_bounded_vlgen %d %d %s %s (LP.serialize_list _ %s)\n\n" smin smax (jumper_length_header_name lenty smin smax) (reader_length_header_name lenty smin smax) (scombinator_name ty);
    let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
    wl o "let %s_jumper%s = LL.jump_synth %s'_jumper synth_%s ()\n\n" n jumper_annot n n
  );
  if need_jumper then (
    wp o "inline_for_extraction let %s'_jumper : LPS.jumper %s'_parser =\n" n n;
    wp o "  PPVG.jump_bounded_vlgen %d %d %s %s (LP.serialize_list _ %s) ()\n\n" smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax) (scombinator_name ty);
    let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
    wp o "let %s_jumper%s = LPC.jump_synth %s'_jumper synth_%s\n\n" n jumper_annot n n
  );
  (* TODO: intro lemmas *)
  (* TODO: accessor *)
  (if !emit_pulse then emit_copyful_vllist o i n ty smin smax lenty);
  ()
  
and compile_vlbytes o i is_private n li lenty smin smax =
  let (min, max) = li.min_len, li.max_len in
  let need_validator = is_private || need_validator li.meta li.min_len li.max_len in
  let need_jumper = is_private || need_jumper li.min_len li.max_len in
  if !emit_pulse then begin
    (* Pulse, Seq-native (no FStar.Bytes): the byte payload is a [Seq.seq byte]
       refinement framed by a GENERIC (variable-width) length header. The high
       [<n>] type is spec-only (the executable representation is the Vec-based
       lowtype), so it is [noextract]. *)
    w i "noextract type %s = LP.parse_bounded_seq_vlbytes_t %d %d\n\n" n smin smax;
    write_api o i false is_private li.meta n min max;
    w o "noextract let %s_parser = LP.parse_bounded_seq_vlgenbytes %d %d %s\n\n" n smin smax (pcombinator_length_header_name lenty smin smax);
    w o "noextract let %s_serializer = LP.serialize_bounded_seq_vlgenbytes %d %d %s\n\n" n smin smax (scombinator_length_header_name lenty smin smax);
    write_bytesize o is_private n;
    if need_validator then
      wp o "let %s_validator = LSeqB.validate_bounded_seq_vlgenbytes %d %d %s %s ()\n\n" n smin smax (pulse_validator_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax);
    if need_jumper then begin
        let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
        wp o "let %s_jumper%s = LSeqB.jump_bounded_seq_vlgenbytes %d %d %s %s ()\n\n" n jumper_annot smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax)
      end;
    (* Pulse: Seq-native copyful parser + free (+ safe writer/size for bcvli headers) *)
    let vlgenbytes_writer, vlgenbytes_size =
      if lenty = "bitcoin_varint" then
        let ssk = scombinator_length_header_name lenty smin smax in
        let hsize = sprintf "(fun x -> PPBCVLI.bounded_bcvli_size %d %d x)" smin smax in
        let hw = sprintf "(PPBCVLI.l2r_leaf_write_bounded_bcvli %d %d ())" smin smax in
        let prelude = "" in
        Some (sprintf "%sLSeqB.l2r_safe_writer_bounded_seq_vlgenbytes %d %dul %d %dul %s %s %s" prelude smin smin smax smax ssk hsize hw),
        Some (sprintf "%sLSeqB.l2r_safe_size_bounded_seq_vlgenbytes %d %dul %d %dul %s %s" prelude smin smin smax smax ssk hsize)
      else None, None
    in
    emit_copyful_seqbytes_vl o i n (sprintf "LSeqB.copyful_parse_bounded_seq_vlgenbytes %d %d %s %s ()" smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax)) (sprintf "LSeqB.seq_vlbytes_conv %d %d" smin smax)
      ?writer:vlgenbytes_writer ?size:vlgenbytes_size
  end else begin
  w i "type %s = b:bytes{%d <= length b /\\ length b <= %d}\n\n" n smin smax;
  write_api o i false is_private li.meta n min max;
  w o "noextract let %s_parser = LP.parse_bounded_vlgenbytes %d %d %s\n\n" n smin smax (pcombinator_length_header_name lenty smin smax);
  w o "noextract let %s_serializer = LP.serialize_bounded_vlgenbytes %d %d %s\n\n" n smin smax (scombinator_length_header_name lenty smin smax);
  write_bytesize o is_private n;
  wh o "let %s_parser32 = LS.parse32_bounded_vlgenbytes %d %dul %d %dul %s\n\n" n smin smin smax smax (pcombinator32_length_header_name lenty smin smax);
  wh o "let %s_serializer32 = LS.serialize32_bounded_vlgenbytes %d %d %s\n\n" n smin smax (scombinator32_length_header_name lenty smin smax);
  wh o "let %s_size32 = LSZ.size32_bounded_vlgenbytes %d %d %s\n\n" n smin smax (size32_length_header_name lenty smin smax);
  if need_validator then
    wl o "let %s_validator = LL.validate_bounded_vlgenbytes %d %dul %d %dul %s %s\n\n" n smin smin smax smax (validator_length_header_name lenty smin smax) (reader_length_header_name lenty smin smax);
  if need_validator then
    wp o "let %s_validator = PPBY.validate_bounded_vlgenbytes %d %d %s %s\n\n" n smin smax (pulse_validator_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax);
  if need_jumper then begin
      let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
      wl o "let %s_jumper%s = LL.jump_bounded_vlgenbytes %d %d %s %s\n\n" n jumper_annot smin smax (jumper_length_header_name lenty smin smax) (reader_length_header_name lenty smin smax)
    end;
  if need_jumper then begin
      let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
      wp o "let %s_jumper%s = PPBY.jump_bounded_vlgenbytes %d %d %s %s\n\n" n jumper_annot smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax)
    end;
  (* Pulse: copyful parser + free (+ safe writer/size for bcvli headers) *)
  let vlgenbytes_writer, vlgenbytes_size =
    if lenty = "bitcoin_varint" then
      let ssk = scombinator_length_header_name lenty smin smax in
      let hsize = sprintf "(fun x -> PPBCVLI.bounded_bcvli_size %d %d x)" smin smax in
      let hw = sprintf "(PPBCVLI.l2r_leaf_write_bounded_bcvli %d %d ())" smin smax in
      let prelude = "" in
      Some (sprintf "%sPPBY.l2r_safe_writer_bounded_vlgenbytes %d %dul %d %dul %s %s %s" prelude smin smin smax smax ssk hsize hw),
      Some (sprintf "%sPPBY.l2r_safe_size_bounded_vlgenbytes %d %dul %d %dul %s %s" prelude smin smin smax smax ssk hsize)
    else None, None
  in
  emit_copyful_bytes o i n (sprintf "PPBY.copyful_parse_bounded_vlgenbytes %d %d %s %s" smin smax (pulse_jumper_length_header_name lenty smin smax) (pulse_reader_length_header_name lenty smin smax)) (sprintf "PPBY.vlbytes_conv %d %d" smin smax)
    ?writer:vlgenbytes_writer ?size:vlgenbytes_size
  end


and compile_typedef tch o i tn fn (ty:type_t) vec def al =
  let n = if tn = "" then String.uncapitalize_ascii fn else tn^"_"^fn in
  let qname = if tn = "" then String.uncapitalize_ascii fn else tn^"@"^fn in
  let is_private = has_attr al "private" in
  let elem_li = sizeof ty in
  let li = get_leninfo qname in
  let need_validator = is_private || need_validator li.meta li.min_len li.max_len in
  let need_jumper = is_private || need_jumper li.min_len li.max_len in
  let (ty, vec) =
    (* Rewriting for some implifications, eg opaque+vldata=vlbytes *)
    match ty, vec with
    | _, VectorFixedCount k ->
      if li.min_len = li.max_len then (ty, VectorFixed li.max_len)
      else failwith "Can't declare array of variable length elements"
    | TypeSimple(t), VectorVldata vl when SM.mem (compile_type t) !erased ->
      let (len_len_min, len_len_max, max_len) = basic_bounds vl in
      TypeSimple("opaque"),
      VectorRange(max 0 (li.min_len-len_len_min),
                  min (assume_some max_len) (max 0 (li.max_len-len_len_max)),
                  Some vl)
    | TypeSimple("opaque"), VectorVldata vl ->
      let (_, _, max_len) = basic_bounds vl in
      TypeSimple("opaque"), VectorRange(0, assume_some max_len, Some vl)
    | _ -> ty, vec in
  match ty with
  | TypeIfeq _ -> failwith "Unsupported if-then-else, must to appear in a struct after a tag"
  | TypeSelect _ -> failwith "Unsupported select, must appear in a struct after an enum tag"
  | TypeSimple ty ->
    match vec with
    (* Type aliasing *)
    | VectorNone ->
      if !types_from = "" then w (type_channel tch i) "%stype %s = %s\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n (compile_type ty);
      write_api o i li.has_lserializer is_private li.meta n li.min_len li.max_len;
      w o "noextract let %s_parser = %s\n\n" n (pcombinator_name ty);
      w o "noextract let %s_serializer = %s\n\n" n (scombinator_name ty);
      write_bytesize o is_private n;
      wh o "let %s_parser32 = %s\n\n" n (pcombinator32_name ty);
      wh o "let %s_serializer32 = %s\n\n" n (scombinator32_name ty);
      ws li.has_lserializer o "let %s_size32 = %s\n\n" n (size32_name ty);
      (if need_validator then
        wl o "let %s_validator = %s\n\n" n (validator_name ty));
      (if need_jumper then
         let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
         wl o "let %s_jumper%s = %s\n\n" n jumper_annot (jumper_name ty));
      if li.has_lserializer then begin
          wl i "val %s_reader : LL.leaf_reader %s\n\n" n (pcombinator_name n);
          wl o "let %s_reader = %s\n\n" n (leaf_reader_name ty);
          wl i "val %s_lserializer : LL.serializer32 %s\n\n" n (scombinator_name n);
          wl o "let %s_lserializer = %s\n\n" n (lscombinator_name ty)
      end;
      (* Pulse: validator, jumper, reader for type aliases *)
      (if need_validator then
        wp o "let %s_validator = %s\n\n" n (pulse_validator_name ty));
      (if need_jumper then
         let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
         wp o "let %s_jumper%s = %s\n\n" n jumper_annot (pulse_jumper_name ty));
      if li.has_lserializer then begin
        wp i "val %s_reader : PPB.leaf_reader %s_parser\n\n" n n;
        wp o "let %s_reader = %s\n\n" n (pulse_leaf_reader_name ty);
        wp i "val %s_writer : LPS.l2r_leaf_writer %s_serializer\n\n" n n;
        wp o "let %s_writer = %s\n\n" n (pulse_leaf_writer_name ty);
        wp i "val %s_leaf_size : LPS.leaf_size %s_serializer\n\n" n n;
        wp o "let %s_leaf_size = %s\n\n" n (pulse_leaf_size_name ty)
      end;
      (* Pulse: copyful parser + free for type aliases *)
      wp i "let %s_lowtype = %s\n\n" n (copyful_lowtype_name ty);
      wp i "noextract let %s_mid = %s\n\n" n (copyful_mid_name ty);
      wp i "let %s_vmatch = %s\n\n" n (copyful_vmatch_name ty);
      wp i "noextract let %s_conv = %s\n\n" n (copyful_conv_name ty);
      wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
      wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
      wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv = %s\n\n" n n n n (copyful_read_name ty);
      wp o "let free_%s : PPB.free_t %s_vmatch = %s\n\n" n n (copyful_free_name ty);
      if !emit_pulse && copyful_writer_available ty then begin
        wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
        wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv = %s\n\n" n n n n (copyful_writer_name ty);
        register_writer n
      end;
      w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == %s) [SMTPat (%s_bytesize x)]\n\n" n n n (bytesize_call ty "x") n;
      w o "let %s_bytesize_eqn x = %s\n\n" n (bytesize_eq_call ty "x");
      if ty <> "Empty" && ty <> "Fail"
      then begin
          w i "val %s_parser_serializer_eq (_: unit) : Lemma (%s_parser == %s /\\ %s_serializer == %s)\n\n" n n (pcombinator_name ty) n (scombinator_name ty);
          w o "let %s_parser_serializer_eq _ = ()\n\n" n
        end;
      ()

    (* Should be rewritten during normalization *)
    | VectorFixedCount _
    | VectorSymbolic _ -> failwith "not supported"

    | VectorCount(low, high, repr) ->
      let repr_t = match repr with None -> "uint32" | Some t -> t in
      w i "inline_for_extraction noextract let min_count = %d\ninline_for_extraction noextract let max_count = %d\n" low high;
      w i "%stype %s = l:list %s{%d <= L.length l /\\ L.length l <= %d}\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n (compile_type ty) low high;
      write_api o i false is_private li.meta n li.min_len li.max_len;
      w o "let %s_parser' = LP.parse_vclist %d %d %s %s\n\n" n low high (pcombinator_name repr_t) (pcombinator_name ty);
      w o "private let kind_eq : squash (LP.get_parser_kind %s_parser' == %s_parser_kind) = _ by (FStar.Tactics.trefl ())\n\n" n n;
      w o "private let type_eq : squash (%s == LP.vlarray %s %d %d) = _ by (FStar.Tactics.trefl ())\n\n" n (compile_type ty) low high;
      w o "let %s_parser = %s_parser'\n" n n;
      w o "let %s_serializer = LP.serialize_vclist %d %d %s %s\n\n" n low high (scombinator_name repr_t) (scombinator_name ty);
      write_bytesize o is_private n;
      wh o "let %s_parser32 = LS.parse32_vclist %dul %dul %s %s\n\n" n low high (pcombinator32_name repr_t) (pcombinator32_name ty);
      wh o "let %s_serializer32 =\n  [@inline_let] let _ = assert_norm (LS.serialize32_vclist_precond %d %d (LP.get_parser_kind %s) (LP.get_parser_kind %s)) in\n" n low high (pcombinator_name repr_t) (pcombinator_name ty);
      wh o "  LS.serialize32_vclist %d %d %s %s\n\n" low high (scombinator32_name repr_t) (scombinator32_name ty);
      wh o "let %s_size32 =\n  [@inline_let] let _ = assert_norm (LS.serialize32_vclist_precond %d %d (LP.get_parser_kind %s) (LP.get_parser_kind %s)) in\n" n low high (pcombinator_name repr_t) (pcombinator_name ty);
      wh o "  LSZ.size32_vclist %d %d %s %s\n\n" low high (size32_name repr_t) (size32_name ty);
      wl o "let %s_validator = LL.validate_vclist %dul %dul %s %s %s\n\n" n low high (validator_name repr_t) (leaf_reader_name repr_t) (validator_name ty);
      wp o "let %s_validator = PPVCL.validate_vclist %dul %dul %s %s %s ()\n\n" n low high (pulse_validator_name repr_t) (pulse_leaf_reader_name repr_t) (pulse_validator_name ty);
      let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
      wl o "let %s_jumper%s =\n" n jumper_annot;
      wl o "  LL.jump_vclist %d %d %s %s %s\n\n" low high (jumper_name repr_t) (leaf_reader_name repr_t) (jumper_name ty);
      let jumper_annot_p = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
      wp o "let %s_jumper%s =\n" n jumper_annot_p;
      wp o "  PPVCL.jump_vclist %dul %dul %s %s %s ()\n\n" low high (pulse_jumper_name repr_t) (pulse_leaf_reader_name repr_t) (pulse_jumper_name ty);
      (if !emit_pulse then emit_copyful_vclist o i n ty low high repr_t);
      (* finalizer, count, i-th accessor TODO *)
      ()

    | VectorVldata lenty when has_bounded_length_parsers lenty -> (* TODO: generalize once parse_bounded_integer is refactored into a parser to bounded_int32 in LowParse *)
       let (_, _, smax) = basic_bounds lenty in
       if compile_type ty = "U8.t"
       then
         compile_vlbytes o i is_private n li lenty 0 (assume_some smax)
       else
         compile_vldata o i is_private n ty li elem_li lenty 0 (assume_some smax)

    | VectorVldata vl ->
      let (len_len_min, len_len_max, smax) = basic_bounds vl in
      let smax = assume_some smax in
      let (min, max) = li.min_len, li.max_len in
      let fits_in_bounds = elem_li.max_len <= smax in
      let needs_synth = not fits_in_bounds in
      if fits_in_bounds then
       begin
        w i "%stype %s = %s\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n (compile_type ty);
        write_api o i false is_private li.meta n min max;
        w o "let %s_parser =\n" n;
        w o "  LP.parse_bounded_vldata %d %d %s\n\n" 0 smax (pcombinator_name ty);
        w o "let %s_serializer =\n" n;
        w o "  LP.serialize_bounded_vldata %d %d %s\n\n" 0 smax (scombinator_name ty);
        write_bytesize o is_private n;
        wh o "let %s_parser32 =\n" n;
        wh o "  LS.parse32_bounded_vldata %d %dul %d %dul %s\n\n" 0 0 smax smax (pcombinator32_name ty);
        wh o "let %s_serializer32 =\n" n;
        wh o "  LS.serialize32_bounded_vldata %d %d %s\n\n" 0 smax (scombinator32_name ty);
        wh o "let %s_size32 =\n" n;
        wh o "  LSZ.size32_bounded_vldata %d %d %s %dul\n\n" 0 smax (size32_name ty) (log256 smax);
        if need_validator then (
          wl o "let %s_validator =\n" n;
          wl o "  LL.validate_bounded_vldata %d %d %s ()\n\n" 0 smax (validator_name ty);
        );
        if need_validator then (
          wp o "let %s_validator =\n" n;
          wp o "  PPVD.validate_bounded_vldata %d %d %s (PPBI.leaf_read_bounded_integer_%d ())\n\n" 0 smax (pulse_validator_name ty) (log256 smax);
        );
        if need_jumper then (
          let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
          wl o "let %s_jumper%s =\n\n" n jumper_annot;
          wl o "  LL.jump_bounded_vldata %d %d %s ()\n\n" 0 smax (pcombinator_name ty)
        );
        if need_jumper then (
          let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
          wp o "let %s_jumper%s =\n" n jumper_annot;
          wp o "  PPVD.jump_bounded_vldata %d %d %s (PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer (LP.log256' %d)) (PPBI.leaf_read_bounded_integer_%d ()))\n\n" 0 smax (pcombinator_name ty) smax (log256 smax)
        );
        (* Pulse accessor *)
        if ty <> "Empty" && ty <> "Fail" then
         begin
          wp i "val %s_accessor : PPB.accessor %s_parser %s (PPVD.clens_id %s)\n\n" n n (pcombinator_name ty) (compile_type ty);
          wp o "let %s_accessor = PPVD.accessor_bounded_vldata_payload %d %d (PPBI.leaf_read_bounded_integer_%d ())\n\n" n 0 smax (log256 smax);
         end;
        (* accessor *)
        if ty <> "Empty" && ty <> "Fail" then
         begin
          wl i "val %s_gaccessor : LL.gaccessor %s_parser %s (LL.clens_id %s)\n\n" n n (pcombinator_name ty) (compile_type ty);
          wl o "let %s_gaccessor = LL.gaccessor_bounded_vldata_payload %d %d %s\n\n" n 0 smax (pcombinator_name ty);
          wl i "val %s_accessor : LL.accessor %s_gaccessor\n\n" n n;
          wl o "let %s_accessor = LL.accessor_bounded_vldata_payload %d %d %s\n\n" n 0 smax (pcombinator_name ty);
          ()
         end;
        (* finalizer *)
        begin match ty with
        | "Fail" -> () (* impossible *)
        | "Empty" ->
            wl i "val %s_finalize (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : HST.Stack unit\n" n;
            wl i "  (requires (fun h ->\n";
            wl i "    U32.v pos + %d <= U32.v input.LL.len /\\\n" len_len_max;
            wl i "    LL.writable input.LL.base (U32.v pos) (U32.v pos + %d) h /\\\n" len_len_max;
            wl i "    LL.live_slice h input\n";
            wl i "  ))\n";
            wl i "  (ensures (fun h _ h' ->\n";
            wl i "    B.modifies (LL.loc_slice_from_to input pos (pos `U32.add` %dul)) h h' /\\\n" len_len_max;
            wl i "    LL.valid_pos %s_parser h' input pos (pos `U32.add` %dul)\n" n len_len_max;
            wl i "  ))\n\n";
            wl o "let %s_finalize #_ #_ input pos =\n" n;
            wl o "  let h = HST.get () in\n";
            wl o "  [@inline_let] let _ = LL.valid_facts LL.parse_empty h input (pos `U32.add` %dul) in\n" len_len_max;
            wl o "  LL.finalize_bounded_vldata %d %d LL.parse_empty input pos (pos `U32.add` %dul) \n\n" 0 smax len_len_max
        | _ ->
            wl i "val %s_finalize (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) (pos' : U32.t) : HST.Stack unit\n" n;
            wl i "  (requires (fun h ->\n";
            wl i "    U32.v pos + %d <= U32.v input.LL.len /\\\n" len_len_max;
            wl i "    LL.writable input.LL.base (U32.v pos) (U32.v pos + %d) h /\\\n" len_len_max;
            wl i "    LL.valid_pos %s h input (pos `U32.add` %dul) pos'\n" (pcombinator_name ty) len_len_max;
            wl i "  ))\n";
            wl i "  (ensures (fun h _ h' ->\n";
            wl i "    B.modifies (LL.loc_slice_from_to input pos (pos `U32.add` %dul)) h h' /\\\n" len_len_max;
            wl i "    LL.valid_content_pos %s_parser h' input pos (LL.contents %s h input (pos `U32.add` %dul)) pos'\n" n (pcombinator_name ty) len_len_max;
            wl i "  ))\n\n";
            wl o "let %s_finalize #_ #_ input pos pos' =\n" n;
            wl o "  LL.finalize_bounded_vldata %d %d %s input pos pos'\n\n" 0 smax (pcombinator_name ty)
        end;
        (if !emit_pulse then emit_copyful_bounded_vldata_payload o i n ty smax);
        ()
       end
      else
       begin
        let sizef =
          if basic_type ty then sprintf "Seq.length (LP.serialize %s x)" (scombinator_name ty)
          else bytesize_call ty "x" in
        w i "%stype %s = x:%s{let l = %s in %d <= l /\\ l <= %d}\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n (compile_type ty) sizef 0 smax;
        wh i "val check_%s_bytesize (x: %s) : Tot (b: bool {b == (let l = %s in %d <= l && l <= %d)})\n\n" n (compile_type ty) sizef 0 smax;
        wh o "let check_%s_bytesize x =\n" n;
        wh o "  [@inline_let] let _ = %s in\n" (bytesize_eq_call (compile_type ty) "x");
        wh o "  let l = %s x in\n" (size32_name ty);
        wh o "  %dul `U32.lte` l && l `U32.lte` %dul\n\n" 0 smax;
        w (ipub i o) "%stype %s' = LP.parse_bounded_vldata_strong_t %d %d %s\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n 0 smax (scombinator_name ty);
        w (ipub i o) "inline_for_extraction %slet synth_%s (x: %s') : Tot %s =\n" (if !emit_pulse then "noextract " else "") n n n;
        w (ipub i o) "  [@inline_let] let _ = %s in x\n\n" (bytesize_eq_call ty "x");
        w (ipub i o) "inline_for_extraction %slet synth_%s_recip (x: %s) : Tot %s' =\n" (if !emit_pulse then "noextract " else "") n n n;
        w (ipub i o) "  [@inline_let] let _ = %s in x\n\n" (bytesize_eq_call ty "x");
        write_api o i false is_private li.meta n min max;
        w o "noextract let %s'_parser : LP.parser _ %s' =\n" n n;
        w o "  LP.parse_bounded_vldata_strong %d %d %s\n\n" 0 smax (scombinator_name ty);
        w o "let %s_parser = LP.parse_synth %s'_parser synth_%s\n\n" n n n;
        w o "noextract let %s'_serializer : LP.serializer %s'_parser =\n" n n;
        w o "  LP.serialize_bounded_vldata_strong %d %d %s\n\n" 0 smax (scombinator_name ty);
        w o "let %s_serializer = LP.serialize_synth _ synth_%s %s'_serializer synth_%s_recip ()\n\n" n n n n;
        write_bytesize o is_private n;
        wh o "inline_for_extraction let %s'_parser32 : LS.parser32 %s'_parser =\n" n n;
        wh o "  LS.parse32_bounded_vldata_strong %d %dul %d %dul %s %s\n\n" 0 0 smax smax (scombinator_name ty) (pcombinator32_name ty);
        wh o "let %s_parser32 = LS.parse32_synth' _ synth_%s %s'_parser32 ()\n\n" n n n;
        wh o "inline_for_extraction noextract let %s'_serializer32 : LS.serializer32 %s'_serializer =\n" n n;
        wh o "  LS.serialize32_bounded_vldata_strong %d %d %s\n\n" 0 smax (scombinator32_name ty);
        wh o "let %s_serializer32 = LS.serialize32_synth' _ synth_%s _ %s'_serializer32 synth_%s_recip ()\n\n" n n n n;
        wh o "inline_for_extraction noextract let %s'_size32 : LSZ.size32 %s'_serializer =\n" n n;
        wh o "  LSZ.size32_bounded_vldata_strong %d %d %s %dul\n\n" 0 smax (size32_name ty) (log256 smax);
        wh o "let %s_size32 = LSZ.size32_synth' _ synth_%s _ %s'_size32 synth_%s_recip ()\n\n" n n n n;
        if need_validator then (
          wl o "inline_for_extraction let %s'_validator : LL.validator %s'_parser =\n" n n;
          wl o "  LL.validate_bounded_vldata_strong %d %d %s %s ()\n\n" 0 smax (scombinator_name ty) (validator_name ty);
          wl o "let %s_validator = LL.validate_synth %s'_validator synth_%s ()\n\n" n n n
        );
        if need_validator then (
          wp o "inline_for_extraction let %s'_validator : LPS.validator %s'_parser =\n" n n;
          wp o "  PPVD.validate_bounded_vldata_strong %d %d %s %s (PPBI.leaf_read_bounded_integer_%d ())\n\n" 0 smax (scombinator_name ty) (pulse_validator_name ty) (log256 smax);
          wp o "let %s_validator = LPC.validate_synth %s'_validator synth_%s\n\n" n n n
        );
        if need_jumper then (
          wl o "inline_for_extraction let %s'_jumper : LL.jumper %s'_parser =\n" n n;
          wl o "  LL.jump_bounded_vldata_strong %d %d %s ()\n\n" 0 smax (scombinator_name ty);
          let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
          wl o "let %s_jumper%s = LL.jump_synth %s'_jumper synth_%s ()\n\n" n jumper_annot n n
        );
        if need_jumper then (
          wp o "inline_for_extraction let %s'_jumper : LPS.jumper %s'_parser =\n" n n;
          wp o "  PPVD.jump_bounded_vldata_strong %d %d %s (PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer (LP.log256' %d)) (PPBI.leaf_read_bounded_integer_%d ()))\n\n" 0 smax (scombinator_name ty) smax (log256 smax);
          let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
          wp o "let %s_jumper%s = LPC.jump_synth %s'_jumper synth_%s\n\n" n jumper_annot n n
        );
        (* Pulse: accessor *)
        (* Pulse: accessor *)
        wp i "noextract let %s_clens : LowParse.CLens.clens %s %s = {\n" n n (compile_type ty);
        wp i "  LowParse.CLens.clens_cond = (fun _ -> True);\n";
        wp i "  LowParse.CLens.clens_get = (fun (x: %s) -> (x <: %s));\n" n (compile_type ty);
        wp i "}\n\n";
        wp i "val %s_accessor : PPB.accessor %s_parser %s %s_clens\n\n" n n (pcombinator_name ty) n;
        wp o "let %s_accessor =\n" n;
        wp o "  PPC.accessor_ext\n";
        wp o "    (PPC.accessor_compose\n";
        wp o "      (PPC.accessor_synth synth_%s synth_%s_recip)\n" n n;
        wp o "      (PPVD.accessor_bounded_vldata_strong_payload %d %d %s (PPBI.leaf_read_bounded_integer_%d ())) ())\n" 0 smax (scombinator_name ty) (log256 smax);
        wp o "    %s_clens ()\n\n" n;
        (* finalizer *)
        if ty = "Empty" || ty = "Fail" then failwith "vldata empty/fail should have been in the 'bounds OK' case";
        wl i "val %s_finalize (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) (pos'  : U32.t) : HST.Stack unit\n"  n;
        wl i "  (requires (fun h ->\n" ;
        wl i "     U32.v pos + %d < 4294967296 /\\ (\n" len_len_max;
        wl i "     let pos_payload = pos `U32.add` %dul in\n" len_len_max;
        wl i "     LL.writable input.LL.base (U32.v pos) (U32.v pos + %d) h /\\\n"  len_len_max;
        wl i "     LL.valid_pos %s h input pos_payload pos' /\\ (\n" (pcombinator_name ty);
        wl i "     let len_payload = U32.v pos' - U32.v pos_payload in\n";
        wl i "     let x = LL.contents %s h input pos_payload in\n" (pcombinator_name ty);
        wl i "     let len_ser = %s in\n" (bytesize_call ty "x");
        wl i "     ((%d <= len_payload /\\ len_payload <= %d) \\/ (%d <= len_ser /\\ len_ser <= %d))\n" 0 smax 0 smax;
        wl i "  ))))\n";
        wl i "  (ensures (fun h _ h' ->\n";
        wl i "    let x = LL.contents %s h input (pos `U32.add` %dul) in\n" (pcombinator_name ty) len_len_max;
        wl i "    let len_ser = %s in\n" (bytesize_call ty "x");
        wl i "    B.modifies (LL.loc_slice_from_to input pos (pos `U32.add` %dul)) h h' /\\\n" len_len_max;
        wl i "    %d <= len_ser /\\ len_ser <= %d /\\\n" 0 smax;
        wl i "    LL.valid_content_pos %s_parser h' input pos x pos'\n" n;
        wl i "  ))\n\n";
        wl o "let %s_finalize #_ #_ input pos pos' =\n" n;
        wl o "  let h = HST.get () in\n";
        wl o "  [@inline_let] let _ =\n";
        wl o "    let x = LL.contents %s h input (pos `U32.add` %dul) in\n" (pcombinator_name ty) len_len_max;
        wl o "    %s\n" (bytesize_eq_call ty "x");
        wl o "  in\n";
        wl o "  LL.finalize_bounded_vldata_strong %d %d %s input pos pos';\n" 0 smax (scombinator_name ty);
        wl o "  let h = HST.get () in\n";
        wl o "  LL.valid_synth h %s'_parser synth_%s input pos\n\n" n n;
        (* accessor *)
        wl i "noextract let %s_clens : LL.clens %s %s = {\n" n n (compile_type ty);
        wl i "  LL.clens_cond = (fun _ -> True);\n";
        wl i "  LL.clens_get = (fun (x: %s) -> (x <: %s));\n" n (compile_type ty);
        wl i "}\n\n";
        wl i "val %s_gaccessor : LL.gaccessor %s_parser %s %s_clens\n\n" n n (pcombinator_name ty) n;
        let write_accessor g =
          wl o "let %s_%saccessor =\n" n g;
          wl o "  LL.%saccessor_ext\n" g;
          wl o "    (LL.%saccessor_compose\n" g;
          wl o "      (LL.%saccessor_synth %s'_parser synth_%s synth_%s_recip ())\n" g n n n;
          wl o "      (LL.%saccessor_bounded_vldata_strong_payload %d %d %s)\n" g 0 smax (scombinator_name ty);
          wl o "    )\n";
          wl o "    %s_clens\n" n;
          wl o "    ()\n\n";
          ()
        in
        write_accessor "g";
        wl i "val %s_accessor : LL.accessor %s_gaccessor\n\n" n n;
        write_accessor "";
        ()
       end;
      (if !emit_pulse && needs_synth then emit_copyful_bounded_vldata_payload_refined o i n ty smax);
      (* lemma about bytesize *)
      w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == %d + %s) [SMTPat (%s_bytesize x)]\n\n" n n n li.len_len (bytesize_call ty "x") n;
      w o "let %s_bytesize_eqn x =\n" n;
      (if needs_synth then w o "  LP.serialize_synth_eq _ synth_%s %s'_serializer synth_%s_recip () x;\n" n n n);
      w o "  %s\n\n" (bytesize_eq_call ty "x");
      ()

    (* Fixed-length bytes *)
    | VectorFixed k when (compile_type ty = "U8.t") && !emit_pulse ->
      (* Pulse: Seq-native fixed-length bytes (no FStar.Bytes). The high-level
         value is a plain [Seq.lseq FStar.UInt8.t k]; the spec is built over
         [parse_lseq_bytes]/[serialize_lseq_bytes] and the copyful tag block uses
         the LowParse.Pulse.SeqBytes combinators.  The executable representation is
         the Vec-based [<n>_lowtype = PPBY.lvec uint8]; the high [Seq.lseq] type is
         referenced only by noextract/GTot specs and (phantom) parser indices, so
         mark it noextract to keep KaRaMeL from emitting a [Prims_list__uint8_t]
         cons-list typedef.  (This branch is -pulse-only, see the guard above.) *)
      w i "noextract type %s = Seq.lseq FStar.UInt8.t %d\n\n" n k;
      write_api o i false is_private li.meta n li.min_len li.max_len;
      w o "noextract let %s_parser = LP.parse_lseq_bytes %d\n\n" n k;
      w o "noextract let %s_serializer = LP.serialize_lseq_bytes %d\n\n" n k;
      write_bytesize o is_private n;
      w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == Seq.length x) [SMTPat (%s_bytesize x)]\n\n" n n n n;
      w o "let %s_bytesize_eqn x = ()\n\n" n;
      emit_copyful_seqbytes o i n k;
      ()

    (* Fixed-length bytes *)
    | VectorFixed k when (compile_type ty = "U8.t") ->
      w i "type %s = lbytes %d\n\n" n k;
      write_api o i false is_private li.meta n li.min_len li.max_len;
      w o "noextract let %s_parser = LP.parse_flbytes %d\n\n" n k;
      w o "noextract let %s_serializer = LP.serialize_flbytes %d\n\n" n k;
      write_bytesize o is_private n;
      wh o "let %s_parser32 = LS.parse32_flbytes %d %dul\n\n" n k k;
      wh o "let %s_serializer32 = LS.serialize32_flbytes %d\n\n" n k;
      wh o "let %s_size32 = LSZ.size32_constant %s_serializer %dul ()\n\n" n n k;
      (* validator and jumper not needed unless private, we are total constant size *)
      if is_private then
       begin
        wl o "let %s_validator = LL.validate_flbytes %d %dul\n\n" n k k;
        wl o "let %s_jumper : LL.jumper %s_parser = LL.jump_flbytes %d %dul\n\n" n n k k
       end;
      (* Pulse: copyful parser + free *)
      emit_copyful_bytes o i n (sprintf "PPBY.copyful_parse_flbytes %d" k) (sprintf "PPBY.flbytes_conv %d" k)
        ~writer:(sprintf "PPBY.l2r_safe_writer_flbytes %d %dsz" k k)
        ~size:(sprintf "PPBY.l2r_safe_size_flbytes %d %dsz" k k);
      w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == BY.length x) [SMTPat (%s_bytesize x)]\n\n" n n n n;
      w o "let %s_bytesize_eqn x = ()\n\n" n;
      (* intro *)
      wl i "val %s_intro (h: HS.mem) (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : Lemma\n" n;
      wl i "  (requires (\n";
      wl i "    LL.live_slice h input /\\\n";
      wl i "    U32.v pos + %d <= U32.v input.LL.len\n" k;
      wl i "  ))\n";
      wl i "  (ensures (\n";
      wl i "    LL.valid_content_pos %s_parser h input pos (BY.hide (LL.bytes_of_slice_from_to h input pos (pos `U32.add` %dul))) (pos `U32.add` %dul)\n" n k k;
      wl i "  ))\n\n";
      wl o "let %s_intro h #_ #_ input pos =\n" n;
      wl o "  LL.valid_flbytes_intro h %d input pos\n\n" k;
      (* elim *)
      wl i "val %s_elim (h: HS.mem) (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : Lemma\n" n;
      wl i "  (requires (LL.valid %s_parser h input pos))\n" n;
      wl i "  (ensures (\n";
      wl i "    U32.v pos + %d <= U32.v input.LL.len /\\\n" k;
      wl i "    LL.valid_content_pos %s_parser h input pos (BY.hide (LL.bytes_of_slice_from_to h input pos (pos `U32.add` %dul))) (pos `U32.add` %dul)\n" n k k;
      wl i "  ))\n\n";
      wl o "let %s_elim h #_ #_ input pos =\n" n;
      wl o "  LL.valid_flbytes_elim h %d input pos\n\n" k;
      ()

    (* Fixed length list *)
    | VectorFixed k when elem_li.min_len = elem_li.max_len ->
      w i "unfold let %s_pred (l:list %s) (n:nat) : GTot prop = L.length l == n\n" n (compile_type ty);
      w i "%stype %s = l:list %s{%s_pred l %d}\n\n" (if !emit_pulse then "noextract " else "") n (compile_type ty) n li.min_count;
      write_api o i false is_private li.meta n li.min_len li.max_len;
      w o "%stype %s' = LP.array %s %d\n\n" (if !emit_pulse then "noextract " else "") n (compile_type ty) li.min_count;
      w o "private let %s_eq () : Lemma (%s' == %s) =\n" n n n;
      w o "  assert(%s'==%s) by (FStar.Tactics.norm [delta_only [`%%(LP.array); `%%(%s); `%%(%s')]]; FStar.Tactics.trefl ())\n\n" n n n n;
      w o "noextract let %s'_parser = LP.parse_array %s %d %d\n\n" n (scombinator_name ty) k li.min_count;
      w o "let %s_parser = %s_eq(); LP.coerce (LP.parser %s_parser_kind %s) %s'_parser\n\n" n n n n n;
      w o "noextract let %s'_serializer = LP.serialize_array %s %d %d ()\n\n" n (scombinator_name ty) k li.min_count;
      w o "let %s_serializer = %s_eq(); LP.coerce (LP.serializer %s_parser) %s'_serializer\n\n" n n n n;
      write_bytesize o is_private n;
      wh o "inline_for_extraction let %s'_parser32 = LS.parse32_array %s %s %d %dul %d ()\n\n"
        n (scombinator_name ty) (pcombinator32_name ty) k k li.min_count;
      wh o "let %s_parser32 = %s_eq(); LP.coerce (LS.parser32 %s_parser) %s'_parser32\n\n" n n n n;
      wh o "inline_for_extraction noextract let %s'_serializer32 =\n" n;
      wh o "  LS.serialize32_array #_ #_ #_ #%s %s %d %d ()\n\n" (scombinator_name ty) (scombinator32_name ty) k li.min_count;
      wh o "let %s_serializer32 = %s_eq(); LP.coerce (LS.serializer32 %s_serializer) %s'_serializer32\n\n" n n n n;
      wh o "let %s_size32 = LSZ.size32_array %s %d %dul %d ()\n" n (scombinator_name ty) k k li.min_count;
      (if need_validator then
        wl o "let %s_validator = LL.validate_array %s %s %d %dul %d ()\n\n" n (scombinator_name ty) (validator_name ty) k k li.min_count);
      (* jumper not needed unless private, we are constant size *)
      (if is_private then
        wl o "let %s_jumper : LL.jumper %s_parser = LL.jump_array %s %d %dul %d ()\n\n" n n (scombinator_name ty) k k li.min_count);
      wl i "noextract let clens_%s_nth (i: nat { i < %d } ) : LL.clens %s %s = {\n" n li.min_count n (compile_type ty);
      wl i "  LL.clens_cond = (fun _ -> True);\n";
      wl i "  LL.clens_get = (fun (l: %s) -> L.index l i);\n" n;
      wl i "}\n\n";
      wl i "val %s_nth_ghost (i: nat {i < %d}) : LL.gaccessor %s_parser %s (clens_%s_nth i)\n\n" n li.max_count n (pcombinator_name ty) n;
      wl o "let %s_nth_ghost i = LL.array_nth_ghost %s %d %d i\n\n" n (scombinator_name ty) li.max_len li.max_count;
      wl i "inline_for_extraction val %s_nth (i: U32.t { U32.v i < %d } ) : LL.accessor (%s_nth_ghost (U32.v i))\n\n" n li.max_count n;
      wl o "let %s_nth i = LL.array_nth %s %d %d i\n\n" n (scombinator_name ty) li.max_len li.max_count;
      (* intro lemma *)
      wl i "val %s_intro (h: HS.mem) (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos pos' : U32.t) : Lemma\n" n;
      wl i "  (requires (\n";
      wl i "     LL.valid_list %s h input pos pos' /\\\n" (pcombinator_name ty);
      wl i "     (L.length (LL.contents_list %s h input pos pos') == %d \\/ U32.v pos' - U32.v pos == %d)\n" (pcombinator_name ty) li.max_count li.max_len;
      wl i "  ))\n";
      wl i "  (ensures (\n";
      wl i "    let x = LL.contents_list %s h input pos pos' in\n" (pcombinator_name ty);
      wl i "    L.length x = %d /\\\n" li.max_count;
      wl i "    U32.v pos' - U32.v pos == %d /\\\n" li.max_len;
      wl i "    LL.valid_content_pos %s_parser h input pos x pos'\n" n;
      wl i "  ))\n\n";
      wl o "let %s_intro h #_ #_ input pos pos' = %s_eq (); LL.valid_list_valid_array %s %d %dul %d () h input pos pos'\n\n" n n (scombinator_name ty) li.max_len li.max_len li.max_count;
      (* elim lemma *)
      wl i "val %s_elim (h: HS.mem) (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : Lemma\n" n;
      wl i "  (requires (LL.valid %s_parser h input pos))\n" n;
      wl i "  (ensures (\n";
      wl i "    let pos' = LL.get_valid_pos %s_parser h input pos in\n" n;
      wl i "    U32.v pos' - U32.v pos == %d /\\\n" li.max_len;
      wl i "    LL.valid_list %s h input pos pos' /\\\n" (pcombinator_name ty);
      wl i "    LL.contents_list %s h input pos pos' == LL.contents %s_parser h input pos\n" (pcombinator_name ty) n;
      wl i "  ))\n";
      wl o "let %s_elim h #_ #_ input pos = %s_eq (); LL.valid_array_valid_list %s %d %dul %d () h input pos\n\n" n n (scombinator_name ty) li.max_len li.max_len li.max_count;
      (* lemmas about bytesize *)
      w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == L.length x `FStar.Mul.op_Star` %d) [SMTPat (%s_bytesize x)]\n\n" n n n elem_li.min_len n;
      w o "let %s_bytesize_eqn x =\n" n;
      w o "  assert_norm (LP.fldata_array_precond (LP.get_parser_kind %s) %d %d == true);\n" (pcombinator_name ty) li.max_len li.max_count;
      w o "  LP.length_serialize_array %s %d %d () x\n\n"(scombinator_name ty) li.max_len li.max_count;
      (if !emit_pulse then emit_copyful_array o i n ty li.max_len li.max_count);
      ()

    (* Fixed bytelen list of variable length elements *)
    | VectorFixed(k) ->
      (if !emit_pulse
       then w i "noextract let %s_list_bytesize (x: list %s) : GTot nat = Seq.length (LP.serialize (LP.serialize_list _ %s) x)\n\n" n (compile_type ty) (scombinator_name ty)
       else begin
         w i "noextract val %s_list_bytesize: list %s -> GTot nat\n\n" n (compile_type ty);
         w o "let %s_list_bytesize x = Seq.length (LP.serialize (LP.serialize_list _ %s) x)\n\n" n (scombinator_name ty)
       end);
      w i "%stype %s = l:list %s{%s_list_bytesize l == %d}\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n (compile_type ty) n k;
      w (ipub i o) "%stype %s' = LP.parse_fldata_strong_t (LP.serialize_list _ %s) %d\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n (scombinator_name ty) k;
      w (ipub i o) "let %s_eq () : Lemma (%s' == %s) = assert_norm (%s' == %s)\n\n" n n n n n;
      write_api o i false is_private li.meta n li.min_len li.max_len;
      w o "noextract let %s'_parser : LP.parser _ %s' =\n" n n;
      w o "  LP.parse_fldata_strong (LP.serialize_list _ %s) %d\n\n" (scombinator_name ty) k;
      w o "let %s_parser = %s_eq (); LP.coerce (LP.parser %s_parser_kind %s) %s'_parser\n\n" n n n n n;
      w o "noextract let %s'_serializer : LP.serializer %s'_parser =\n" n n;
      w o "  LP.serialize_fldata_strong (LP.serialize_list _ %s) %d\n\n" (scombinator_name ty) k;
      w o "let %s_serializer = %s_eq () ; LP.coerce (LP.serializer %s_parser) %s'_serializer\n\n" n n n n;
      write_bytesize o is_private n;
      wh o "inline_for_extraction noextract let %s'_parser32 : LS.parser32 %s'_parser =\n" n n;
      wh o "  LS.parse32_fldata_strong (LP.serialize_list _ %s) (LS.parse32_list %s) %d %dul\n\n" (scombinator_name ty) (pcombinator32_name ty) k k;
      wh o "let %s_parser32 = %s_eq (); LP.coerce (LS.parser32 %s_parser) %s'_parser32\n\n" n n n n;
      wh o "inline_for_extraction noextract let %s'_serializer32 : LS.serializer32 %s'_serializer =\n" n n;
      wh o "  LS.serialize32_fldata_strong (LS.partial_serialize32_list _ %s %s ()) %d\n\n" (scombinator_name ty) (scombinator32_name ty) k;
      wh o "let %s_serializer32 = %s_eq (); LP.coerce (LS.serializer32 %s_serializer) %s'_serializer32\n\n" n n n n;
      wh o "inline_for_extraction noextract let %s'_size32 : LSZ.size32 %s'_serializer =\n" n n;
      wh o "  LSZ.size32_fldata_strong (LP.serialize_list _ %s) %d %dul\n\n" (scombinator_name ty) k k;
      wh o "let %s_size32 = %s_eq (); LP.coerce (LSZ.size32 %s_serializer) %s'_size32\n\n" n n n n;
      wl o "inline_for_extraction let %s'_validator : LL.validator %s'_parser =\n" n n;
      wl o "  LL.validate_fldata_strong (LL.serialize_list _ %s) (LL.validate_list %s ()) %d %dul\n\n" (scombinator_name ty) (validator_name ty) k k;
      wl o "let %s_validator = %s_eq (); LP.coerce (LL.validator %s_parser) %s'_validator\n\n" n n n n;
      wp o "inline_for_extraction let %s'_validator : LPS.validator %s'_parser =\n" n n;
      wp o "  PPFD.validate_fldata_strong (LP.serialize_list _ %s) (PPLS.validate_list %s ()) %dsz\n\n" (scombinator_name ty) (pulse_validator_name ty) k;
      wp o "let %s_validator = %s_eq (); LP.coerce (LPS.validator %s_parser) %s'_validator\n\n" n n n n;
      (* jumper not needed unless private, we are constant size *)
      if is_private then
       begin
        wl o "inline_for_extraction let %s'_jumper : LL.jumper %s'_parser =\n" n n;
        wl o "  LL.jump_fldata_strong (LL.serialize_list _ %s) %d %dul\n\n" (scombinator_name ty) k k;
        wl o "let %s_jumper : LL.jumper %s_parser = %s_eq (); LP.coerce (LL.jumper %s_parser) %s'_jumper\n\n" n n n n n
       end;
      (* Copyful parser/free for fldata-of-list (a fixed-byte-length container of
         variable-length elements, e.g. [t x[k]]): the generated refined type [<n>]
         and [parse_fldata_strong_t] ([<n>']) are only propositionally equal (via
         [<n>_eq]), so the FLData-payload copyful parser/free are re-indexed from
         [<n>'] to [<n>] via the value-level PPB.copyful_parse_ext / PPB.free_ext
         combinators. *)
      (if !emit_pulse then emit_copyful_vectorfixed_list o i n ty k)

    (* Variable length bytes *)
    | VectorRange (low, high, Some lenty) when has_bounded_length_parsers lenty -> (* TODO: generalize once parse_bounded_integer is refactored into a parser to bounded_int32 in LowParse *)
       if compile_type ty = "U8.t"
       then
         compile_vlbytes o i is_private n li lenty low high
       else
         compile_vllist o i is_private n ty li elem_li lenty low high
      
    (* Variable length bytes (Pulse, Seq-native: no FStar.Bytes) *)
    | VectorRange (low, high, repr)
      when compile_type ty = "U8.t" && !emit_pulse &&
        (match repr with None -> true
        | Some t -> let (_,lm,_) = basic_bounds t in lm = log256 high) ->
      w i "inline_for_extraction noextract let min_len = %d\ninline_for_extraction noextract let max_len = %d\n" low high;
      (* Under -pulse the executable byte representation is the Vec-based lowtype
         ([<n>_lowtype = PPBY.lvec uint8]); the high-level type [<n>] is the spec
         [Seq.seq uint8] refinement, referenced only by noextract/GTot specs and
         (phantom) parser indices, never built at runtime.  Mark it noextract so
         KaRaMeL does not lower it to a [Prims_list__uint8_t] cons-list typedef.
         (This whole branch is -pulse-only, see the guard above.) *)
      w i "noextract type %s = LP.parse_bounded_seq_vlbytes_t %d %d\n\n" n low high;
      write_api o i false is_private li.meta n li.min_len li.max_len;
      w o "noextract let %s_parser = LP.parse_bounded_seq_vlbytes %d %d\n\n" n low high;
      w o "noextract let %s_serializer = LP.serialize_bounded_seq_vlbytes %d %d\n\n" n low high;
      write_bytesize o is_private n;
      if need_validator then
        wp o "let %s_validator = LSeqB.validate_bounded_seq_vlbytes %d %d (PPBI.leaf_read_bounded_integer_%d ())\n\n" n low high (log256 high);
      if need_jumper then begin
        let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
        wp o "let %s_jumper%s = LSeqB.jump_bounded_seq_vlbytes %d %d (PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer (LP.log256' %d)) (PPBI.leaf_read_bounded_integer_%d ()))\n\n" n jumper_annot low high high (log256 high)
      end;
      (* Pulse: Seq-native copyful parser + free *)
      emit_copyful_seqbytes_vl o i n (sprintf "LSeqB.copyful_parse_bounded_seq_vlbytes %d %d (PPBI.leaf_read_bounded_integer_%d ())" low high (log256 high)) (sprintf "LSeqB.seq_vlbytes_conv %d %d" low high)
        ~writer:(sprintf "LSeqB.l2r_safe_writer_bounded_seq_vlbytes %d %dul %d %dul %dsz" low low high high (log256 high))
        ~size:(sprintf "LSeqB.l2r_safe_size_bounded_seq_vlbytes %d %dul %d %dul %dsz" low low high high (log256 high));
      w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == %d + Seq.length x) [SMTPat (%s_bytesize x)]\n\n" n n n li.len_len n;
      w o "let %s_bytesize_eqn x = LP.length_serialize_bounded_seq_vlbytes %d %d x\n\n" n low high;
      ()

    (* Variable length bytes *)
    | VectorRange (low, high, repr)
      when compile_type ty = "U8.t" &&
        (match repr with None -> true
        | Some t -> let (_,lm,_) = basic_bounds t in lm = log256 high) ->
      w i "inline_for_extraction noextract let min_len = %d\ninline_for_extraction noextract let max_len = %d\n" low high;
      w i "type %s = b:bytes{%d <= length b /\\ length b <= %d}\n\n" n low high;
      write_api o i false is_private li.meta n li.min_len li.max_len;
      w o "noextract let %s_parser = LP.parse_bounded_vlbytes %d %d\n\n" n low high;
      w o "noextract let %s_serializer = LP.serialize_bounded_vlbytes %d %d\n\n" n low high;
      write_bytesize o is_private n;
      wh o "let %s_parser32 = LS.parse32_bounded_vlbytes %d %dul %d %dul\n\n" n low low high high;
      wh o "let %s_serializer32 = LS.serialize32_bounded_vlbytes %d %d\n\n" n low high;
      wh o "let %s_size32 = LSZ.size32_bounded_vlbytes %d %d\n\n" n low high;
      if need_validator then
        wl o "let %s_validator = LL.validate_bounded_vlbytes %d %d\n\n" n low high;
      if need_validator then
        wp o "let %s_validator = PPBY.validate_bounded_vlbytes %d %d (PPBI.leaf_read_bounded_integer_%d ())\n\n" n low high (log256 high);
      if need_jumper then begin
        let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
        wl o "let %s_jumper%s = LL.jump_bounded_vlbytes %d %d\n\n" n jumper_annot low high
      end;
      if need_jumper then begin
        let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
        wp o "let %s_jumper%s = PPBY.jump_bounded_vlbytes %d %d (PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer (LP.log256' %d)) (PPBI.leaf_read_bounded_integer_%d ()))\n\n" n jumper_annot low high high (log256 high)
      end;
      (* Pulse: copyful parser + free *)
      emit_copyful_bytes o i n (sprintf "PPBY.copyful_parse_bounded_vlbytes %d %d (PPBI.leaf_read_bounded_integer_%d ())" low high (log256 high)) (sprintf "PPBY.vlbytes_conv %d %d" low high)
        ~writer:(sprintf "PPBY.l2r_safe_writer_bounded_vlbytes %d %dsz %d %dsz %dsz" low low high high (log256 high))
        ~size:(sprintf "PPBY.l2r_safe_size_bounded_vlbytes %d %dsz %d %dsz %dsz" low low high high (log256 high));
      w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == %d + BY.length x) [SMTPat (%s_bytesize x)]\n\n" n n n li.len_len n;
      w o "let %s_bytesize_eqn x = LP.length_serialize_bounded_vlbytes %d %d x\n\n" n low high;
      (* length *)
      wl i "val %s_length (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : HST.Stack U32.t\n" n;
      wl i "  (requires (fun h -> LL.valid %s_parser h input pos))\n" n;
      wl i "  (ensures (fun h res h' ->\n";
      wl i "    let x = LL.contents %s_parser h input pos in\n" n;
      wl i "    B.modifies B.loc_none h h' /\\\n";
      wl i "    U32.v pos + %d + U32.v res == U32.v (LL.get_valid_pos %s_parser h input pos) /\\\n" li.len_len n;
      wl i "    res == BY.len x /\\\n";
      wl i "    LL.bytes_of_slice_from_to h input (pos `U32.add` %dul) ((pos `U32.add` %dul) `U32.add` res) == BY.reveal x\n" li.len_len li.len_len;
      wl i "  ))\n\n";
      wl o "let %s_length #_ #_ input pos =\n" n;
      wl o "  [@inline_let] let _ = assert_norm (%s == LP.parse_bounded_vlbytes_t %d %d) in\n" n low high;
      wl o "  LL.bounded_vlbytes_payload_length %d %d input pos\n\n" low high;
      (* finalizer *)
      wl i "val %s_finalize (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) (len: U32.t) : HST.Stack U32.t\n\n" n;
      wl i "  (requires (fun h ->\n";
      wl i "    LL.live_slice h input /\\\n";
      wl i "    %d <= U32.v len /\\ U32.v len <= %d /\\\n" low high;
      wl i "    U32.v pos + %d + U32.v len <= U32.v input.LL.len /\\\n" li.len_len;
      wl i "    LL.writable input.LL.base (U32.v pos) (U32.v pos + %d) h\n" li.len_len;
      wl i "  ))\n";
      wl i "  (ensures (fun h pos' h' ->\n";
      wl i "    let pos_payload = pos `U32.add` %dul in\n" li.len_len;
      wl i "    B.modifies (LL.loc_slice_from_to input pos pos_payload) h h' /\\\n";
      wl i "    LL.valid_content_pos %s_parser h' input pos (BY.hide (LL.bytes_of_slice_from_to h input pos_payload (pos_payload `U32.add` len))) pos' /\\\n" n;
      wl i "    U32.v pos' == U32.v pos_payload + U32.v len\n";
      wl i "  ))\n\n";
      wl o "let %s_finalize #_ #_ input pos len =\n" n;
      wl o "  [@inline_let] let _ = assert_norm (%s == LP.parse_bounded_vlbytes_t %d %d) in\n" n low high;
      wl o "  LL.finalize_bounded_vlbytes %d %d input pos len\n\n" low high;
      ()

    (* Variable length bytes where the size of the length is explicit
       (Pulse, Seq-native: no FStar.Bytes). This is the explicit-oversized-header
       analog of the tight Seq-native branch above: the fixed-width header [repr]
       exceeds [log256' high], so it goes through the [_gen] combinators. Reached
       only under -pulse (the tight -pulse case is caught above; the non-pulse
       explicit-header case falls through to the FStar.Bytes branch below). *)
    | VectorRange (low, high, repr) when (compile_type ty = "U8.t") && !emit_pulse ->
      let trepr = match repr with Some t -> t | None -> failwith "Missing vlbytes size repr (QD bug?)" in
      let (_, repr, _) = basic_bounds trepr in
      w i "inline_for_extraction noextract let min_len = %d\ninline_for_extraction noextract let max_len = %d\n" low high;
      (* Under -pulse the executable byte representation is the Vec-based lowtype;
         the high [<n>] type is the spec [Seq.seq uint8] refinement, spec-only, so
         mark it noextract (see the tight branch above). *)
      w i "noextract type %s = LP.parse_bounded_seq_vlbytes_t %d %d\n\n" n low high;
      write_api o i false is_private li.meta n li.min_len li.max_len;
      w o "noextract let %s_parser = LP.parse_bounded_seq_vlbytes_gen %d %d %d\n\n" n low high repr;
      w o "noextract let %s_serializer = LP.serialize_bounded_seq_vlbytes_gen %d %d %d\n\n" n low high repr;
      write_bytesize o is_private n;
      if need_validator then
        wp o "let %s_validator = LSeqB.validate_bounded_seq_vlbytes' %d %d %d (PPBI.leaf_read_bounded_integer_%d ())\n\n" n low high repr repr;
      if need_jumper then begin
        let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
        wp o "let %s_jumper%s = LSeqB.jump_bounded_seq_vlbytes' %d %d %d (PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer %d) (PPBI.leaf_read_bounded_integer_%d ()))\n\n" n jumper_annot low high repr repr repr
      end;
      (* Pulse: Seq-native copyful parser + free + safe writer/size *)
      emit_copyful_seqbytes_vl o i n (sprintf "LSeqB.copyful_parse_bounded_seq_vlbytes' %d %d %d (PPBI.leaf_read_bounded_integer_%d ())" low high repr repr) (sprintf "LSeqB.seq_vlbytes_conv %d %d" low high)
        ~writer:(sprintf "LSeqB.l2r_safe_writer_bounded_seq_vlbytes' %d %dul %d %dul %d %dsz" low low high high repr repr)
        ~size:(sprintf "LSeqB.l2r_safe_size_bounded_seq_vlbytes' %d %dul %d %dul %d %dsz" low low high high repr repr);
      w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == %d + Seq.length x) [SMTPat (%s_bytesize x)]\n\n" n n n repr n;
      w o "let %s_bytesize_eqn x = LP.length_serialize_bounded_seq_vlbytes_gen %d %d %d x\n\n" n low high repr;
      ()

    (* Variable length bytes where the size of the length is explicit *)
    | VectorRange (low, high, repr) when (compile_type ty = "U8.t") ->
      let trepr = match repr with Some t -> t | None -> failwith "Missing vlbytes size repr (QD bug?)" in
      let (_, repr, _) = basic_bounds trepr in
      w i "inline_for_extraction noextract let min_len = %d\ninline_for_extraction noextract let max_len = %d\n" low high;
      w i "type %s = b:bytes{%d <= length b /\\ length b <= %d}\n\n" n low high;
      write_api o i false is_private li.meta n li.min_len li.max_len;
      w o "noextract let %s_parser = LP.parse_bounded_vlbytes' %d %d %d\n\n" n low high repr;
      w o "noextract let %s_serializer = LP.serialize_bounded_vlbytes' %d %d %d\n\n" n low high repr;
      write_bytesize o is_private n;
      wh o "let %s_parser32 = LS.parse32_bounded_vlbytes' %d %dul %d %dul %d\n\n" n low low high high repr;
      wh o "let %s_serializer32 = LS.serialize32_bounded_vlbytes' %d %d %d\n\n" n low high repr;
      wh o "let %s_size32 = LSZ.size32_bounded_vlbytes' %d %d %d\n\n" n low high repr;
      if need_validator then
        wl o "let %s_validator = LL.validate_bounded_vlbytes' %d %d %d\n\n" n low high repr;
      if need_validator then
        wp o "let %s_validator = PPBY.validate_bounded_vlbytes' %d %d %d (PPBI.leaf_read_bounded_integer_%d ())\n\n" n low high repr repr;
      if need_jumper then begin
        let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
        wl o "let %s_jumper%s = LL.jump_bounded_vlbytes' %d %d %d\n\n" n jumper_annot low high repr
      end;
      if need_jumper then begin
        let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
        wp o "let %s_jumper%s = PPBY.jump_bounded_vlbytes' %d %d %d (PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer %d) (PPBI.leaf_read_bounded_integer_%d ()))\n\n" n jumper_annot low high repr repr repr
      end;
      (* Pulse: copyful parser + free *)
      emit_copyful_bytes o i n (sprintf "PPBY.copyful_parse_bounded_vlbytes' %d %d %d (PPBI.leaf_read_bounded_integer_%d ())" low high repr repr) (sprintf "PPBY.vlbytes_conv %d %d" low high)
        ~writer:(sprintf "PPBY.l2r_safe_writer_bounded_vlbytes' %d %dsz %d %dsz %d %dsz" low low high high repr repr)
        ~size:(sprintf "PPBY.l2r_safe_size_bounded_vlbytes' %d %dsz %d %dsz %d %dsz" low low high high repr repr);
      w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == %d + BY.length x) [SMTPat (%s_bytesize x)]\n\n" n n n repr n;
      w o "let %s_bytesize_eqn x = LP.length_serialize_bounded_vlbytes' %d %d %d x\n\n" n low high repr;
      (* length *)
      wl i "val %s_length (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : HST.Stack U32.t\n" n;
      wl i "  (requires (fun h -> LL.valid %s_parser h input pos))\n" n;
      wl i "  (ensures (fun h res h' ->\n";
      wl i "    let x = LL.contents %s_parser h input pos in\n" n;
      wl i "    B.modifies B.loc_none h h' /\\\n";
      wl i "    U32.v pos + %d + U32.v res == U32.v (LL.get_valid_pos %s_parser h input pos) /\\\n" repr n;
      wl i "    res == BY.len x /\\\n";
      wl i "    LL.bytes_of_slice_from_to h input (pos `U32.add` %dul) ((pos `U32.add` %dul) `U32.add` res) == BY.reveal x\n" repr repr;
      wl i "  ))\n\n";
      wl o "let %s_length #_ #_ input pos =\n" n;
      wl o "  [@inline_let] let _ = assert_norm (%s == LP.parse_bounded_vlbytes_t %d %d) in\n" n low high;
      wl o "  LL.bounded_vlbytes'_payload_length %d %d %d input pos\n\n" low high repr;
      (* finalizer *)
      wl i "val %s_finalize (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) (len: U32.t) : HST.Stack U32.t\n\n" n;
      wl i "  (requires (fun h ->\n";
      wl i "    LL.live_slice h input /\\\n";
      wl i "    %d <= U32.v len /\\ U32.v len <= %d /\\\n" low high;
      wl i "    U32.v pos + %d + U32.v len <= U32.v input.LL.len /\\\n" repr;
      wl i "    LL.writable input.LL.base (U32.v pos) (U32.v pos + %d) h\n" repr;
      wl i "  ))\n";
      wl i "  (ensures (fun h pos' h' ->\n";
      wl i "    let pos_payload = pos `U32.add` %dul in\n" repr;
      wl i "    B.modifies (LL.loc_slice_from_to input pos pos_payload) h h' /\\\n";
      wl i "    LL.valid_content_pos %s_parser h' input pos (BY.hide (LL.bytes_of_slice_from_to h input pos_payload (pos_payload `U32.add` len))) pos' /\\\n" n;
      wl i "    U32.v pos' == U32.v pos_payload + U32.v len\n";
      wl i "  ))\n\n";
      wl o "let %s_finalize #_ #_ input pos len =\n" n;
      wl o "  [@inline_let] let _ = assert_norm (%s == LP.parse_bounded_vlbytes_t %d %d) in\n" n low high;
      wl o "  LL.finalize_bounded_vlbytes' %d %d %d input pos len\n\n" low high repr;
      ()

    (* Variable length list of fixed-length elements *)
    | VectorRange (low, high, _) when elem_li.min_len = elem_li.max_len ->
      w i "inline_for_extraction noextract let min_count = %d\ninline_for_extraction noextract let max_count = %d\n" li.min_count li.max_count;
      (* Under -pulse the executable representation is the Vec-based array lowtype
         (emit_copyful_vlarray); keep the spec list type noextract so the F*
         cons-list stays out of the extracted C (LowStar accessors, emitted only
         in the non-pulse path, still need it). *)
      w i "%stype %s = l:list %s{%d <= L.length l /\\ L.length l <= %d}\n\n" (if !emit_pulse then "noextract " else "") n (compile_type ty) li.min_count li.max_count;
      write_api o i false is_private li.meta n li.min_len li.max_len;
      w o "private let pre : squash (LP.vldata_vlarray_precond %d %d %s %d %d == true) = _ by (FStar.Tactics.trefl ())\n\n" low high (pcombinator_name ty) li.min_count li.max_count;
      w o "let %s_parser =\n" n;
      w o "  LP.parse_vlarray %d %d %s %d %d ()\n\n" low high (scombinator_name ty) li.min_count li.max_count;
      w o "let %s_serializer =\n" n;
      w o "  LP.serialize_vlarray %d %d %s %d %d ()\n\n" low high (scombinator_name ty) li.min_count li.max_count;
      write_bytesize o is_private n;
      wh o "let %s_parser32 =\n" n;
      wh o "  LS.parse32_vlarray %d %dul %d %dul %s %s %d %d ()\n\n" low low high high (scombinator_name ty) (pcombinator32_name ty) li.min_count li.max_count;
      wh o "let %s_serializer32 =\n" n;
      wh o "  LS.serialize32_vlarray %d %d #_ #_ #_ #%s %s %d %d ()\n\n" low high (scombinator_name ty) (scombinator32_name ty) li.min_count li.max_count;
      wh o "let %s_size32 =\n" n;
      wh o "  [@inline_let] let _ = assert_norm (LP.vldata_vlarray_precond %d %d %s %d %d == true) in\n" low high (pcombinator_name ty) li.min_count li.max_count;
      wh o "  LSZ.size32_vlarray %d %d %s %d %d () %dul %dul\n\n" low high (scombinator_name ty) li.min_count li.max_count li.len_len elem_li.min_len;
      if need_validator then begin
        wl o "let %s_validator =\n" n;
        wl o " LL.validate_vlarray %d %d %s %s %d %d () %dul\n\n" low high (scombinator_name ty) (validator_name ty) li.min_count li.max_count li.len_len
      end;
      if need_validator then begin
        wp o "let %s_validator =\n" n;
        wp o " PPAR.validate_vlarray %d %d %s %s %d %d () (PPBI.leaf_read_bounded_integer_%d ()) ()\n\n" low high (scombinator_name ty) (pulse_validator_name ty) li.min_count li.max_count (log256 high)
      end;
      if need_jumper then begin
        let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
        wl o "let %s_jumper%s =\n" n jumper_annot;
        wl o " LL.jump_vlarray %d %d %s %d %d () %dul\n\n" low high (scombinator_name ty) li.min_count li.max_count li.len_len
      end;
      if need_jumper then begin
        let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
        wp o "let %s_jumper%s =\n" n jumper_annot;
        wp o " PPAR.jump_vlarray %d %d %s %d %d () (PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer (LP.log256' %d)) (PPBI.leaf_read_bounded_integer_%d ())) ()\n\n" low high (scombinator_name ty) li.min_count li.max_count high (log256 high)
      end;
      (* finalizer *)
      wl i "inline_for_extraction val finalize_%s (#rrel: _) (#rel: _) (sl: LL.slice rrel rel) (pos pos' : U32.t) : HST.Stack unit\n" n;
      wl i "(requires (fun h ->\n";
      wl i "  U32.v pos + %d < 4294967296 /\\\n" li.len_len;
      wl i "  LL.writable sl.LL.base (U32.v pos) (U32.v pos + %d) h /\\\n" li.len_len;
      wl i "  LL.valid_list %s h sl (pos `U32.add` %dul) pos' /\\ (\n" (pcombinator_name ty) li.len_len;
      wl i "  let count = L.length (LL.contents_list %s h sl (pos `U32.add` %dul) pos') in\n" (pcombinator_name ty) li.len_len;
      wl i "  let len = U32.v pos' - (U32.v pos + %d) in\n" li.len_len;
      wl i "  ((%d <= len /\\ len <= %d) \\/ (%d <= count /\\ count <= %d))\n" low high li.min_count li.max_count;
      wl i ")))\n";
      wl i "(ensures (fun h _ h' ->\n";
      wl i "  B.modifies (LL.loc_slice_from_to sl pos (pos `U32.add` %dul)) h h' /\\ (\n" li.len_len;
      wl i "  let l = LL.contents_list %s h sl (pos `U32.add` %dul) pos' in\n" (pcombinator_name ty) li.len_len;
      wl i "  %d <= L.length l /\\ L.length l <= %d /\\\n" li.min_count li.max_count;
      wl i "  LL.valid_content_pos %s_parser h' sl pos l pos'\n" n;
      wl i ")))\n\n";
      wl o "let _ : squash (%s == LL.vlarray %s %d %d) = _ by (FStar.Tactics.trefl ())\n\n" n (compile_type ty) li.min_count li.max_count;
      wl o "let finalize_%s #_ #_ sl pos pos' =\n" n;
      wl o "  LL.finalize_vlarray %d %d %s %d %d sl pos pos'\n\n" low high (scombinator_name ty) li.min_count li.max_count;
      (* length (elem count) and elim *)
      wl i "val %s_count (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : HST.Stack U32.t\n" n;
      wl i "  (requires (fun h -> LL.valid %s_parser h input pos))\n" n;
      wl i "  (ensures (fun h res h' ->\n";
      wl i "    let x = LL.contents %s_parser h input pos in\n" n;
      wl i "    let pos' = LL.get_valid_pos %s_parser h input pos in\n" n;
      wl i "    B.modifies B.loc_none h h' /\\\n";
      wl i "    U32.v res == L.length x /\\\n";
      wl i "    U32.v pos' == U32.v pos + %d + (U32.v res `FStar.Mul.op_Star` %d) /\\\n" li.len_len elem_li.min_len;
      wl i "    LL.valid_list %s h input (pos `U32.add` %dul) pos' /\\\n" (pcombinator_name ty) li.len_len;
      wl i "    LL.contents_list %s h input (pos `U32.add` %dul) pos' == x\n" (pcombinator_name ty) li.len_len;
      wl i "  ))\n";
      wl o "let %s_count #_ #_ input pos = LL.vlarray_list_length %d %d %s %d %d input pos\n\n" n low high (scombinator_name ty) li.min_count li.max_count;
      (* nth *)
      wl i "noextract let %s_clens_nth (i: nat) : Tot (LL.clens %s %s) = {\n" n n (compile_type ty);
      wl i "  LL.clens_cond = (fun (l: %s) -> i < L.length l);\n" n;
      wl i "  LL.clens_get = (fun (l: %s) -> L.index l i);\n" n;
      wl i "}\n\n";
      wl i "val %s_nth_ghost (i: nat) : Tot (LL.gaccessor %s_parser %s (%s_clens_nth i))\n\n" n n (pcombinator_name ty) n;
      wl o "let %s_nth_ghost i = LL.vlarray_nth_ghost %d %d %s %d %d i\n\n" n low high (scombinator_name ty) li.min_count li.max_count;
      wl i "val %s_nth (i: U32.t) : Tot (LL.accessor (%s_nth_ghost (U32.v i)))\n\n" n n;
      wl o "let %s_nth i = LL.vlarray_nth %d %d %s %d %d i\n\n" n low high (scombinator_name ty) li.min_count li.max_count;
      (* lemmas about bytesize *)
      w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == %d + (L.length x `FStar.Mul.op_Star` %d)) [SMTPat (%s_bytesize x)]\n\n" n n n li.len_len elem_li.min_len n;
      w o "let %s_bytesize_eqn x = LP.length_serialize_vlarray %d %d %s %d %d () x\n\n" n low high (scombinator_name ty) li.min_count li.max_count;
      (if !emit_pulse then emit_copyful_vlarray o i n ty low high li.min_count li.max_count);
      ()

    (* Variable length list of variable length elements *)
    | VectorRange(low, high, _) ->
      let (min, max) = (li.min_len-li.len_len), (li.max_len-li.len_len) in
      (if !emit_pulse
       then w i "noextract let %s_list_bytesize (x: list %s) : GTot nat = Seq.length (LP.serialize (LP.serialize_list _ %s) x)\n\n" n (compile_type ty) (scombinator_name ty)
       else begin
         w i "noextract val %s_list_bytesize: list %s -> GTot nat\n\n" n (compile_type ty);
         w o "let %s_list_bytesize x = Seq.length (LP.serialize (LP.serialize_list _ %s) x)\n\n" n (scombinator_name ty)
       end);
      (* Under -pulse the executable representation is the Vec-based lowtype;
         keep the spec list type and synth coercions noextract so the F* cons-list
         does not leak into the extracted C (the LowStar path needs them). *)
      w i "%stype %s = l:list %s{let x = %s_list_bytesize l in %d <= x /\\ x <= %d}\n\n" (if !emit_pulse then "noextract " else "") n (compile_type ty) n min max;
      w i "val %s_list_bytesize_nil : squash (%s_list_bytesize [] == 0)\n\n" n n;
      w o "let %s_list_bytesize_nil = LP.serialize_list_nil %s %s\n\n" n (pcombinator_name ty) (scombinator_name ty);
      w i "val %s_list_bytesize_cons (x: %s) (y: list %s) : Lemma (%s_list_bytesize (x :: y) == %s + %s_list_bytesize y) [SMTPat (%s_list_bytesize (x :: y))]\n\n" n (compile_type ty) (compile_type ty) n (bytesize_call ty "x") n n;
      w o "let %s_list_bytesize_cons x y = LP.serialize_list_cons %s %s x y; %s\n\n" n (pcombinator_name ty) (scombinator_name ty) (bytesize_eq_call ty "x");
      wl i "val %s_list_bytesize_eq (l: list %s) : Lemma (%s_list_bytesize l == LL.serialized_list_length %s l)\n\n" n (compile_type ty) n (scombinator_name ty);
      wl o "let %s_list_bytesize_eq l = LL.serialized_list_length_eq_length_serialize_list %s l\n\n" n (scombinator_name ty);
      wh i "val check_%s_list_bytesize (l: list %s) : Tot (b: bool {b == (let x = %s_list_bytesize l in %d <= x && x <= %d)})\n\n" n (compile_type ty) n min max;
      wh o "let check_%s_list_bytesize l =\n" n;
      wh o "  let x = LSZ.size32_list %s () l in\n" (size32_name ty);
      wh o "  %dul `U32.lte` x && x `U32.lte` %dul\n\n" min max;
      w (ipub i o) "%stype %s' = LP.parse_bounded_vldata_strong_t %d %d (LP.serialize_list _ %s)\n\n" (if !emit_pulse then "noextract " else "") n min max (scombinator_name ty);
      w (ipub i o) "inline_for_extraction %slet synth_%s (x: %s') : Tot %s = x\n\n" (if !emit_pulse then "noextract " else "") n n n;
      w (ipub i o) "inline_for_extraction %slet synth_%s_recip (x: %s) : Tot %s' = x\n\n" (if !emit_pulse then "noextract " else "") n n n;
      write_api o i false is_private li.meta n li.min_len li.max_len;
      w o "noextract let %s'_parser : LP.parser _ %s' =\n" n n;
      w o "  LP.parse_bounded_vldata_strong %d %d (LP.serialize_list _ %s)\n\n" min max (scombinator_name ty);
      w o "let %s_parser = %s'_parser `LP.parse_synth` synth_%s \n\n" n n n;
      w o "noextract let %s'_serializer : LP.serializer %s'_parser =\n" n n;
      w o "  LP.serialize_bounded_vldata_strong %d %d (LP.serialize_list _ %s)\n\n" min max (scombinator_name ty);
      w o "let %s_serializer = LP.serialize_synth _ synth_%s %s'_serializer synth_%s_recip ()\n\n" n n n n;
      write_bytesize o is_private n;
      wh o "inline_for_extraction noextract let %s'_parser32 : LS.parser32 %s'_parser =\n" n n;
      wh o "  LS.parse32_bounded_vldata_strong %d %dul %d %dul (LP.serialize_list _ %s) (LS.parse32_list %s)\n\n" min min max max (scombinator_name ty) (pcombinator32_name ty);
      wh o "let %s_parser32 = LS.parse32_synth' _ synth_%s %s'_parser32 ()\n\n" n n n;
      wh o "inline_for_extraction noextract let %s'_serializer32 : LS.serializer32 %s'_serializer =\n" n n;
      wh o "  LS.serialize32_bounded_vldata_strong %d %d (LS.partial_serialize32_list _ %s %s ())\n\n" min max (scombinator_name ty) (scombinator32_name ty);
      wh o "let %s_serializer32 = LS.serialize32_synth' _ synth_%s _ %s'_serializer32 synth_%s_recip ()\n\n" n n n n;
      wh o "inline_for_extraction noextract let %s'_size32 : LSZ.size32 %s'_serializer =\n" n n;
      wh o "  LSZ.size32_bounded_vldata_strong %d %d (LSZ.size32_list %s ()) %dul\n\n" min max (size32_name ty) li.len_len;
      wh o "let %s_size32 = LSZ.size32_synth' _ synth_%s _ %s'_size32 synth_%s_recip ()\n\n" n n n n;
      if need_validator then begin
        wl o "inline_for_extraction let %s'_validator : LL.validator %s'_parser =\n" n n;
        wl o "  LL.validate_bounded_vldata_strong %d %d (LP.serialize_list _ %s) (LL.validate_list %s ()) ()\n\n" min max (scombinator_name ty) (validator_name ty);
        wl o "let %s_validator = LL.validate_synth %s'_validator synth_%s ()\n\n" n n n
      end;
      if need_validator then begin
        wp o "inline_for_extraction let %s'_validator : LPS.validator %s'_parser =\n" n n;
        wp o "  PPVD.validate_bounded_vldata_strong %d %d (LP.serialize_list _ %s) (PPLS.validate_list %s ()) (PPBI.leaf_read_bounded_integer_%d ())\n\n" min max (scombinator_name ty) (pulse_validator_name ty) (log256 max);
        wp o "let %s_validator = LPC.validate_synth %s'_validator synth_%s\n\n" n n n
      end;
      if need_jumper then begin
        wl o "inline_for_extraction let %s'_jumper : LL.jumper %s'_parser =\n" n n;
        wl o "  LL.jump_bounded_vldata_strong %d %d (LP.serialize_list _ %s) ()\n\n" min max (scombinator_name ty);
        let jumper_annot = if is_private then sprintf " : LL.jumper %s_parser" n else "" in
        wl o "let %s_jumper%s = LL.jump_synth %s'_jumper synth_%s ()\n\n" n jumper_annot n n
      end;
      if need_jumper then begin
        wp o "inline_for_extraction let %s'_jumper : LPS.jumper %s'_parser =\n" n n;
        wp o "  PPVD.jump_bounded_vldata_strong %d %d (LP.serialize_list _ %s) (PPB.serialized_of_leaf_reader (LP.serialize_bounded_integer (LP.log256' %d)) (PPBI.leaf_read_bounded_integer_%d ()))\n\n" min max (scombinator_name ty) max (log256 max);
        let jumper_annot = if is_private then sprintf " : LPS.jumper %s_parser" n else "" in
        wp o "let %s_jumper%s = LPC.jump_synth %s'_jumper synth_%s\n\n" n jumper_annot n n
      end;
      (* finalizer *)
      wl i "val finalize_%s (#rrel: _) (#rel: _) (sl: LL.slice rrel rel) (pos pos' : U32.t) : HST.Stack unit\n" n;
      wl i "(requires (fun h ->\n";
      wl i "  U32.v pos + %d < 4294967296 /\\\n" li.len_len;
      wl i "  LL.writable sl.LL.base (U32.v pos) (U32.v pos + %d) h /\\\n" li.len_len;
      wl i "  LL.valid_list %s h sl (pos `U32.add` %dul) pos' /\\ (\n" (pcombinator_name ty) li.len_len;
      wl i "  let len = U32.v pos' - (U32.v pos + %d) in\n" li.len_len;
      wl i "  let len_ser = %s_list_bytesize (LL.contents_list %s h sl (pos `U32.add` %dul) pos') in\n" n (pcombinator_name ty) li.len_len;
      wl i "  ((%d <= len /\\ len <= %d) \\/ (%d <= len_ser /\\ len_ser <= %d))\n" low high low high;
      wl i ")))\n";
      wl i "(ensures (fun h _ h' ->\n";
      wl i "  B.modifies (LL.loc_slice_from_to sl pos (pos `U32.add` %dul)) h h' /\\ (\n" li.len_len;
      wl i "  let l = LL.contents_list %s h sl (pos `U32.add` %dul) pos' in\n" (pcombinator_name ty) li.len_len;
      wl i "  %s_list_bytesize l == U32.v pos' - (U32.v pos + %d) /\\\n" n li.len_len;
      wl i "  LL.valid_content_pos %s_parser h' sl pos l pos'\n" n;
      wl i ")))\n\n";
      wl o "let finalize_%s #_ #_ sl pos pos' =\n" n;
      wl o "  LL.finalize_bounded_vldata_strong_list %d %d %s sl pos pos';\n" low high (scombinator_name ty);
      wl o "  let h = HST.get () in\n";
      wl o "  LL.valid_synth h %s'_parser synth_%s sl pos\n\n" n n;
      (* elim *)
      wl i "val %s_elim (h: HS.mem) (#rrel: _) (#rel: _) (input: LL.slice rrel rel) (pos: U32.t) : Lemma\n" n;
      wl i "  (requires (LL.valid %s_parser h input pos))\n" n;
      wl i "  (ensures (\n";
      wl i "    let pos' = LL.get_valid_pos %s_parser h input pos in\n" n;
      wl i "    U32.v pos + %d <= U32.v pos' /\\ (\n" li.len_len;
      wl i "    let pos1 = pos `U32.add` %dul in\n" li.len_len;
      wl i "    LL.valid_list %s h input pos1 pos' /\\\n" (pcombinator_name ty);
      wl i "    LL.contents_list %s h input pos1 pos' == LL.contents %s_parser h input pos\n" (pcombinator_name ty) n;
      wl i "  )))\n\n";
      wl o "let %s_elim h #_ #_ input pos =\n" n;
      wl o "  LL.valid_synth h %s'_parser synth_%s input pos;\n" n n;
      wl o "  LL.valid_bounded_vldata_strong_list_valid_list %d %d %s %s input pos h\n\n" low high (pcombinator_name ty) (scombinator_name ty);
      (* lemmas about bytesize *)
      w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == %d + %s_list_bytesize x) [SMTPat (%s_bytesize x)]\n\n" n n n li.len_len n n;
      w o "let %s_bytesize_eqn x = LP.serialize_synth_eq %s'_parser synth_%s %s'_serializer synth_%s_recip () x" n n n n n;
      (if !emit_pulse then emit_copyful_vldata_list o i n ty min max);
      ()

and compile_struct tch o i n (fl: struct_field_t list) (al:attr list) =
  let li = get_leninfo n in
  let is_private = has_attr al "private" in

  
  (* Hoist all constructed types (select, vector, etc) into
     sub-definitions using private attribute in implementation *)
  let fields = List.map (fun (al, ty, fn, vec, def) ->
    if has_attr al "implicit" then failwith "Only tags of select() can be implicit currently";
    let fn0 = String.uncapitalize_ascii fn in
    match ty, vec with
    | TypeSimple ty, VectorNone -> (fn0, ty)
    | _ ->
      let n' = sprintf "%s_%s" n fn in
      let p = Typedef (al, ty, fn, vec, def) in
      let (o', i') = open_files n' in
      compile tch o' i' n p;
      w i "(* Type of field %s*)\ninclude %s\n\n" fn (module_name n');
      w o "(* Type of field %s*)\nopen %s\n\n" fn (module_name n');
      (* compile_typedef o i n fn ty vec def ("private"::al); *)
      (fn0, n')) fl in

  (* we assume that the 0 and 1 cases have already normalized by `compile` *)
  assert (List.length fields >= 2);
  
  (* application type *)
  (* Under -pulse, the executable representation is the Vec-based copyful lowtype
     ([<n>_lowtype]); the high-level record [<n>], its tuple [<n>'], and the
     [synth_<n>]/[synth_<n>_recip] coercions below are only referenced from
     ghost/noextract spec code (the copyful/validate/jump/writer combinators take
     the synth as GTot), yet KaRaMeL still materialises them -- leaking F* spec
     types (e.g. a [Seq.seq uint8] opaque field as a [Prims_list] cons-list) into
     the extracted C even though they are never used at runtime.  Mark them
     noextract under -pulse (mirroring the vllist/vlarray fix); the LowStar
     (non-pulse) path uses the record as its actual runtime representation, so
     they must stay extractable there. *)
  if !types_from = "" then begin
    w (type_channel tch i) "%stype %s = {\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n;
    List.iter (fun (fn, ty) ->
      w (type_channel tch i) "  %s : %s;\n" fn (compile_type ty)) fields;
    w (type_channel tch i) "}\n\n";
  end;

  (* Tuple type for nondep_then combination *)
  let tfields = List.fold_left btree_insert (TLeaf (List.hd fields)) (List.tl fields) in
  let tuple =
    btree_fold
      (fun s _ (_, ty) -> sprintf "%s%s" s (compile_type ty))
      (fun s -> sprintf "%s(" s)
      (fun s -> sprintf "%s & " s)
      (fun s -> sprintf "%s)" s)
      (fun _ -> ())
      (fun _ -> ())
      ""
      ()
      tfields
  in
  w (ipub i o) "%stype %s' = %s\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n tuple;

  (* synthethizer for tuple type *)
  let synth_arg =
    btree_fold
      (fun s _ (fn, _) -> sprintf "%s%s" s fn)
      (fun s -> sprintf "%s(" s)
      (fun s -> sprintf "%s," s)
      (fun s -> sprintf "%s)" s)
      (fun _ -> ())
      (fun _ -> ())
      ""
      ()
      tfields
  in
  let synth_body = List.fold_left (fun acc (fn, ty) -> sprintf "%s    %s = %s;\n" acc fn fn) "" fields in
  w (ipub i o) "inline_for_extraction %slet synth_%s (x: %s') : %s =\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n n n;
  w (ipub i o) "  match x with %s -> {\n" synth_arg;
  w (ipub i o) "%s" synth_body;
  w (ipub i o) "  }\n\n";
  
  let synth_recip_body =
    btree_fold
      (fun s _ (fn, _) -> sprintf "%sx.%s" s fn)
      (fun s -> sprintf "%s(" s)
      (fun s -> sprintf "%s," s)
      (fun s -> sprintf "%s)" s)
      (fun _ -> ())
      (fun _ -> ())
      ""
      ()
      tfields
  in
  w (ipub i o) "inline_for_extraction %slet synth_%s_recip (x: %s) : %s' = %s\n\n" (if !emit_pulse && not li.has_lserializer then "noextract " else "") n n n synth_recip_body;

  (* Write parser API *)
  write_api o i li.has_lserializer is_private li.meta n li.min_len li.max_len;

  (* synthetizer injectivity and inversion lemmas *)
  let nfields = List.length fields in
  if nfields > 4 then
    w o "#push-options \"--max_ifuel %d\"\n" (nfields * 2);
  w o "let synth_%s_recip_inverse () : Lemma (LP.synth_inverse synth_%s_recip synth_%s) = ()\n\n" n n n;
  if nfields > 4 then
    w o "#pop-options\n\n";
  w o "let synth_%s_injective () : Lemma (LP.synth_injective synth_%s) =\n" n n;
  w o "  LP.synth_inverse_synth_injective synth_%s_recip synth_%s;\n" n n;
  w o "  synth_%s_recip_inverse ()\n\n" n;
  w o "let synth_%s_inverse () : Lemma (LP.synth_inverse synth_%s synth_%s_recip) =\n" n n n;
  w o "  assert_norm (LP.synth_inverse synth_%s synth_%s_recip)\n\n" n n;
  w o "let synth_%s_recip_injective () : Lemma (LP.synth_injective synth_%s_recip) =\n" n n;
  w o "  synth_%s_recip_inverse ();\n" n;
  w o "  LP.synth_inverse_synth_injective synth_%s synth_%s_recip\n\n" n n;

  (* main parser combinator type *)
  let combinator ret bind =
    btree_fold
      (fun s _ (_, ty) -> sprintf "%s%s" s (ret ty))
      (fun s -> sprintf "%s(" s)
      (fun s -> sprintf "%s `%s` " s bind)
      (fun s -> sprintf "%s)" s)
      (fun _ -> ())
      (fun _ -> ())
      ""
      ()
      tfields
  in
  let parser = combinator pcombinator_name "LP.nondep_then" in
  w o "noextract let %s'_parser : LP.parser _ %s' = %s\n\n" n n parser;

  w o "noextract let %s'_parser_kind = LP.get_parser_kind %s'_parser\n\n" n n;
  w o "let %s_parser =\n  synth_%s_injective ();\n  assert_norm (%s_parser_kind == %s'_parser_kind);\n" n n n n;
  w o "  %s'_parser `LP.parse_synth` synth_%s\n\n" n n;

  (* main serializer type *)
  let serializer = combinator scombinator_name "LP.serialize_nondep_then" in
  w o "noextract let %s'_serializer : LP.serializer %s'_parser = %s\n\n" n n serializer;
  w o "let %s_serializer =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
  w o "  [@inline_let] let _ = synth_%s_inverse () in\n" n;
  w o "  [@inline_let] let _ = assert_norm (%s_parser_kind == %s'_parser_kind) in\n" n n;
  w o "  LP.serialize_synth _ synth_%s %s'_serializer synth_%s_recip ()\n\n" n n n;
  write_bytesize o is_private n;

  (* main parser32 *)
  let parser32 = combinator pcombinator32_name "LS.parse32_nondep_then" in
  wh o "inline_for_extraction let %s'_parser32 : LS.parser32 %s'_parser = %s\n\n" n n parser32;
  wh o "let %s_parser32 =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
  wh o "  [@inline_let] let _ = assert_norm (%s_parser_kind == %s'_parser_kind) in\n" n n;
  wh o "  LS.parse32_synth _ synth_%s (fun x -> synth_%s x) %s'_parser32 ()\n\n" n n n;

  (* serialize32 *)
  let serializer32 = combinator scombinator32_name "LS.serialize32_nondep_then" in
  wh o "inline_for_extraction let %s'_serializer32 : LS.serializer32 %s'_serializer = %s\n\n" n n serializer32;
  wh o "let %s_serializer32 =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
  wh o "  [@inline_let] let _ = synth_%s_inverse () in\n" n;
  wh o "  [@inline_let] let _ = assert_norm (%s_parser_kind == %s'_parser_kind) in\n" n n;
  wh o "  LS.serialize32_synth _ synth_%s _ %s'_serializer32 synth_%s_recip (fun x -> synth_%s_recip x) ()\n\n" n n n n;

  let size32 = combinator size32_name "LSZ.size32_nondep_then" in
  ws li.has_lserializer o "inline_for_extraction let %s'_size32 : LSZ.size32 %s'_serializer = %s\n\n" n n size32;
  ws li.has_lserializer o "let %s_size32 =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
  ws li.has_lserializer o "  [@inline_let] let _ = synth_%s_inverse () in\n" n;
  ws li.has_lserializer o "  [@inline_let] let _ = assert_norm (%s_parser_kind == %s'_parser_kind) in\n" n n;
  ws li.has_lserializer o "  LSZ.size32_synth _ synth_%s _ %s'_size32 synth_%s_recip (fun x -> synth_%s_recip x) ()\n\n" n n n n;

  (* validator *)
  if need_validator li.meta li.min_len li.max_len then
   begin
    let validator = combinator validator_name "LL.validate_nondep_then" in
    wl o "inline_for_extraction let %s'_validator : LL.validator %s'_parser = %s\n\n" n n validator;
    wl o "let %s_validator =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
    wl o "  [@inline_let] let _ = assert_norm (%s_parser_kind == %s'_parser_kind) in\n" n n;
    wl o "  LL.validate_synth %s'_validator synth_%s ()\n\n" n n
   end;

  (* Pulse: validator *)
  if need_validator li.meta li.min_len li.max_len then
   begin
    let validator = combinator pulse_validator_name "PPC.validate_nondep_then" in
    wp o "inline_for_extraction let %s'_validator : LPS.validator %s'_parser = %s\n\n" n n validator;
    wp o "let %s_validator =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
    wp o "  [@inline_let] let _ = assert_norm (%s_parser_kind == %s'_parser_kind) in\n" n n;
    wp o "  LPC.validate_synth %s'_validator synth_%s\n\n" n n
   end;

  (* jumper *)
  if need_jumper li.min_len li.max_len then
   begin
    let jumper = combinator jumper_name "LL.jump_nondep_then" in
    wl o "inline_for_extraction let %s'_jumper : LL.jumper %s'_parser = %s\n\n" n n jumper;
    wl o "let %s_jumper =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
    wl o "  [@inline_let] let _ = assert_norm (%s_parser_kind == %s'_parser_kind) in\n" n n;
    wl o "  LL.jump_synth %s'_jumper synth_%s ()\n\n" n n
   end;

  (* Pulse: jumper *)
  if need_jumper li.min_len li.max_len then
   begin
    let jumper = combinator pulse_jumper_name "LPC.jump_nondep_then" in
    wp o "inline_for_extraction let %s'_jumper : LPS.jumper %s'_parser = %s\n\n" n n jumper;
    wp o "let %s_jumper =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
    wp o "  [@inline_let] let _ = assert_norm (%s_parser_kind == %s'_parser_kind) in\n" n n;
    wp o "  LPC.jump_synth %s'_jumper synth_%s\n\n" n n
   end;

  (* lserialize *)
  if li.has_lserializer then begin
      let rec mk_jumper_reader = function
        | TLeaf (_, ty) -> (jumper_name ty, leaf_reader_name ty)
        | TNode (_, tl, tr) ->
           let (jl, rl) = mk_jumper_reader tl in
           let (jr, rr) = mk_jumper_reader tr in
           let j = sprintf "(%s `LL.jump_nondep_then` %s)" jl jr in
           let r = sprintf "(LL.read_nondep_then %s %s %s)" jl rl rr in
           (j, r)
      in
      let (_, reader) = mk_jumper_reader tfields in
      wl i "val %s_reader : LL.leaf_reader %s_parser\n\n" n n;
      wl o "inline_for_extraction let %s'_reader : LL.leaf_reader %s'_parser = %s\n\n" n n reader;
      wl o "let %s_reader =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
      wl o "  [@inline_let] let _ = assert_norm (%s_parser_kind == %s'_parser_kind) in\n" n n;
      wl o "  LL.read_synth _ synth_%s (fun x -> synth_%s x) %s'_reader ()\n\n" n n n;

      (* Pulse: struct reader *)
      let rec mk_pulse_reader = function
        | TLeaf (_, ty) -> (pulse_jumper_name ty, pulse_leaf_reader_name ty)
        | TNode (_, tl, tr) ->
           let (jl, rl) = mk_pulse_reader tl in
           let (jr, rr) = mk_pulse_reader tr in
           let j = sprintf "(LPC.jump_nondep_then %s %s)" jl jr in
           let r = sprintf "(PPC.leaf_read_nondep_then %s %s %s ())" rl jl rr in
           (j, r)
      in
      let (_, pulse_reader) = mk_pulse_reader tfields in
      wp i "val %s_reader : PPB.leaf_reader %s_parser\n\n" n n;
      wp o "inline_for_extraction let %s'_reader : PPB.leaf_reader %s'_parser = %s\n\n" n n pulse_reader;
      wp o "let %s_reader =\n  synth_%s_injective ();\n" n n;
      wp o "  assert_norm (%s_parser_kind == %s'_parser_kind);\n" n n;
      wp o "  PPB.leaf_reader_of_reader (PPC.read_synth' (PPB.reader_of_leaf_reader %s'_reader) synth_%s synth_%s_recip)\n\n" n n n;

      (* Pulse: struct writer *)
      if li.has_lserializer then begin
        let rec mk_pulse_writer = function
          | TLeaf (_, ty) -> pulse_leaf_writer_name ty
          | TNode (_, tl, tr) ->
             let wl = mk_pulse_writer tl in
             let wr = mk_pulse_writer tr in
             sprintf "(LPC.l2r_leaf_write_nondep_then %s %s ())" wl wr
        in
        let pulse_writer = mk_pulse_writer tfields in
        wp i "val %s_writer : LPS.l2r_leaf_writer %s_serializer\n\n" n n;
        wp o "inline_for_extraction let %s'_writer : LPS.l2r_leaf_writer %s'_serializer = %s\n\n" n n pulse_writer;
        wp o "let %s_writer =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
        wp o "  [@inline_let] let _ = synth_%s_inverse () in\n" n;
        wp o "  LPC.l2r_leaf_write_synth %s'_writer synth_%s synth_%s_recip (fun x -> synth_%s_recip x)\n\n" n n n n;

        (* Pulse: structural struct leaf_size (parallel to writer) *)
        let rec mk_pulse_leaf_size = function
          | TLeaf (_, ty) -> pulse_leaf_size_name ty
          | TNode (_, tl, tr) ->
             let sl = mk_pulse_leaf_size tl in
             let sr = mk_pulse_leaf_size tr in
             sprintf "(LPC.leaf_size_pair %s () %s (_ by (FStar.Tactics.norm [delta; iota; zeta; primops]; FStar.Tactics.smt ())))" sl sr
        in
        let pulse_leaf_size = mk_pulse_leaf_size tfields in
        wp i "val %s_leaf_size : LPS.leaf_size %s_serializer\n\n" n n;
        wp o "inline_for_extraction let %s'_leaf_size : LPS.leaf_size %s'_serializer = %s\n\n" n n pulse_leaf_size;
        wp o "let %s_leaf_size =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
        wp o "  [@inline_let] let _ = synth_%s_inverse () in\n" n;
        wp o "  LPC.leaf_size_synth %s'_leaf_size synth_%s synth_%s_recip (fun x -> synth_%s_recip x)\n\n" n n n n;
      end;

      let serializer32 = combinator lscombinator_name "LL.serialize32_nondep_then" in
      wl i "val %s_lserializer : LL.serializer32 %s_serializer\n\n" n n;
      wl o "inline_for_extraction let %s'_lserializer : LL.serializer32 %s'_serializer = %s\n\n" n n serializer32;
      wl o "let %s_lserializer =\n  [@inline_let] let _ = synth_%s_injective () in\n" n n;
      wl o "  [@inline_let] let _ = synth_%s_inverse () in\n" n;
      wl o "  [@inline_let] let _ = assert_norm (%s_parser_kind == %s'_parser_kind) in\n" n n;
      wl o "  LL.serialize32_synth %s'_lserializer synth_%s synth_%s_recip (fun x -> synth_%s_recip x) ()\n\n" n n n n;
  end;

  (* Pulse: copyful parser + free. A struct is a pair-tree of its fields'
     copyful parsers, wrapped with copyful_parse_synth to rebuild the record.
     The vmatch refers to synth_%s_recip (a .fst-only definition), so these are
     emitted transparently in the implementation. *)
  (* Pulse: copyful parser + free. A struct is a pair-tree of its fields'
     copyful parsers, wrapped with copyful_parse_synth to rebuild the record.
     The low-level representation (<n>_lowtype) is a pair-tree of the fields'
     low-level types and is exported transparently; <n>_vmatch/read_<n>/free_<n>
     are exported abstractly (their definitions mention the .fst-only
     synth_<n>_recip). *)
  let rec mk_pulse_copyful = function
    | TLeaf (_, ty) ->
       (pulse_jumper_name ty, copyful_read_name ty, copyful_vmatch_name ty, copyful_free_name ty, copyful_lowtype_name ty, copyful_mid_name ty, copyful_conv_name ty)
    | TNode (_, tl, tr) ->
       let (jl, rl, vml, fl, ltl, midl, convl) = mk_pulse_copyful tl in
       let (jr, rr, vmr, fr, ltr, midr, convr) = mk_pulse_copyful tr in
       let j = sprintf "(LPC.jump_nondep_then %s %s)" jl jr in
       let r = sprintf "(PPC.copyful_parse_pair %s %s () %s)" jl rl rr in
       let vm = sprintf "(LPC.vmatch_pair %s %s)" vml vmr in
       let f = sprintf "(PPC.free_pair %s %s)" fl fr in
       let lt = sprintf "(%s & %s)" ltl ltr in
       let mid = sprintf "(%s & %s)" midl midr in
       let conv = sprintf "(PPC.pair_conv %s %s)" convl convr in
       (j, r, vm, f, lt, mid, conv)
  in
  let (_, pulse_creader, pulse_cvmatch, pulse_cfree, pulse_clowtype, pulse_cmid, pulse_cconv) = mk_pulse_copyful tfields in
  wp i "let %s_lowtype = %s\n\n" n pulse_clowtype;
  wp i "noextract let %s_mid = %s\n\n" n pulse_cmid;
  wp i "let %s_vmatch : %s_lowtype -> %s_mid -> Pulse.Lib.Core.slprop = %s\n\n" n n n pulse_cvmatch;
  wp i "noextract let %s_conv : %s_mid -> GTot (FStar.Pervasives.Native.option %s) = PPC.synth_conv %s synth_%s\n\n" n n n pulse_cconv n;
  wp i "val read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv\n\n" n n n n;
  wp i "val free_%s : PPB.free_t %s_vmatch\n\n" n n;
  wp o "let read_%s : PPB.copyful_parse %s_vmatch %s_parser %s_conv =\n" n n n n;
  wp o "  synth_%s_injective ();\n" n;
  wp o "  assert_norm (%s_parser_kind == %s'_parser_kind);\n" n n;
  wp o "  PPC.copyful_parse_synth %s synth_%s synth_%s_recip\n\n" pulse_creader n n;
  wp o "let free_%s : PPB.free_t %s_vmatch = %s\n\n" n n pulse_cfree;

  (* Pulse: copyful safe writer. A struct's writer is a pair-tree of its fields'
     safe writers wrapped with l2r_safe_writer_synth to (de)serialize the record.
     Emitted only when every field type has a graceful writer. *)
  if !emit_pulse && List.for_all (fun (_, ty) -> copyful_writer_available ty) fields then begin
    let rec mk_pulse_safe_writer = function
      | TLeaf (_, ty) -> copyful_writer_name ty
      | TNode (_, tl, tr) ->
         let wl = mk_pulse_safe_writer tl in
         let wr = mk_pulse_safe_writer tr in
         sprintf "(PPC.l2r_safe_writer_pair %s () %s)" wl wr
    in
    let pulse_swriter = mk_pulse_safe_writer tfields in
    wp i "val write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let write_%s : PPB.l2r_safe_writer %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  synth_%s_injective ();\n" n;
    wp o "  assert_norm (%s_parser_kind == %s'_parser_kind);\n" n n;
    wp o "  PPC.l2r_safe_writer_synth %s synth_%s synth_%s_recip\n\n" pulse_swriter n n;
    register_writer n
  end;

  (* Pulse: copyful safe SIZE. A struct's size is a pair-tree of its fields'
     safe sizes wrapped with l2r_safe_size_synth. Emitted only when every field
     type has a graceful size. *)
  if !emit_pulse && List.for_all (fun (_, ty) -> copyful_size_available ty) fields then begin
    let rec mk_pulse_safe_size = function
      | TLeaf (_, ty) -> copyful_size_name ty
      | TNode (_, tl, tr) ->
         let sl = mk_pulse_safe_size tl in
         let sr = mk_pulse_safe_size tr in
         sprintf "(PPC.l2r_safe_size_pair %s () %s)" sl sr
    in
    let pulse_ssize = mk_pulse_safe_size tfields in
    wp i "val size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv\n\n" n n n n;
    wp o "let size_%s : PPB.l2r_safe_size %s_vmatch %s_serializer %s_conv =\n" n n n n;
    wp o "  synth_%s_injective ();\n" n;
    wp o "  PPC.l2r_safe_size_synth %s synth_%s synth_%s_recip\n\n" pulse_ssize n n;
    register_size n
  end;

  (* bytesize *)
  w i "val %s_bytesize_eqn (x: %s) : Lemma (%s_bytesize x == %s) [SMTPat (%s_bytesize x)]\n\n"
    n n n
    (List.fold_left
       (fun acc (fn, ty) ->
         let x' = sprintf "x.%s" fn in
         let bs = bytesize_call ty x' in
         if acc = "" then bs else sprintf "%s + %s" acc bs
       )
       ""
       fields
    )
    n
  ;
  let rec bytesize accu = function
  | TLeaf (fn, ty) ->
       (accu, scombinator_name ty, sprintf "x.%s" fn)
  | TNode (_, left, right) ->
     let (accu1, sleft, argleft) = bytesize accu left in
     let (accu2, sright, argright) = bytesize accu1 right in
     let accu = sprintf "%s;\nLP.length_serialize_nondep_then %s %s %s %s" accu2 sleft sright argleft argright in
     let s = sprintf "(%s `LP.serialize_nondep_then` %s)" sleft sright in
     let arg = sprintf "(%s, %s)" argleft argright in
     (accu, s, arg)
  in
  let (body, _, _) = bytesize "" tfields in
  w o "let %s_bytesize_eqn x =\n" n;
  w o "  [@inline_let] let _ = synth_%s_injective () in\n" n;
  w o "  [@inline_let] let _ = synth_%s_inverse () in\n" n;
  w o "  [@inline_let] let _ = assert_norm (%s_parser_kind == %s'_parser_kind) in\n" n n;
  w o "  LP.serialize_synth_eq _ synth_%s %s'_serializer synth_%s_recip () x%s" n n n body;
     List.iter
       (fun (fn, ty) ->
         let bseq = bytesize_eq_call ty (sprintf "x.%s" fn) in
         if bseq <> "()" then w o ";\n  %s" bseq
       )
       fields
     ;
     let seq_sum = List.fold_left
       (fun acc (fn, ty) ->
         let s = scombinator_name ty in
         let cur = sprintf "Seq.length (LP.serialize %s x.%s)" s fn in
         if acc = "" then cur else sprintf "%s + %s" acc cur
       ) "" fields in
     w o ";\n  assert(%s_bytesize x == %s)\n\n" n seq_sum;

  (* accessors for fields *)
     let gacc =
       btree_fold
         (fun output path (fn, ty) -> sprintf "%slet gaccessor'_%s_%s : LL.gaccessor %s'_parser %s _ = %s\n\n" output n fn n (pcombinator_name ty) path)
         (fun x -> x)
         (fun x -> x)
         (fun x -> x)
         (fun path -> sprintf "(LL.gaccessor_then_fst %s)" path)
         (fun path -> sprintf "(LL.gaccessor_then_snd %s)" path)
         ""
         (sprintf "(LL.gaccessor_id %s'_parser)" n)
         tfields
     in
     wl o "%s" gacc;
     let rec accessors (output: string) (path: string) = function
       | TLeaf (fn, ty) ->
          let output' = sprintf "%sinline_for_extraction noextract let accessor'_%s_%s : LL.accessor gaccessor'_%s_%s = %s\n\n" output n fn n fn path in
          (output', jumper_name ty)
       | TNode (_, left, right) ->
          let (output1, jumper1) = accessors output (sprintf "(LL.accessor_then_fst %s)" path) left in
          let (output2, jumper2) = accessors output1 (sprintf "(LL.accessor_then_snd %s %s)" path jumper1) right in
          (output2, sprintf "(%s `LL.jump_nondep_then` %s)" jumper1 jumper2)
     in
     let (acc, _) = accessors "" (sprintf "(LL.accessor_id %s'_parser)" n) tfields in
     wl o "%s" acc;
     wl o "noextract let clens_%s_%s' : LL.clens %s %s' = synth_%s_recip_inverse (); synth_%s_recip_injective (); LL.clens_synth synth_%s_recip synth_%s\n\n" n n n n n n n n;
     wl o "let gaccessor_%s_%s' : LL.gaccessor %s_parser %s'_parser clens_%s_%s' = synth_%s_inverse (); synth_%s_injective (); synth_%s_recip_inverse (); LL.gaccessor_synth %s'_parser synth_%s synth_%s_recip ()\n\n" n n n n n n n n n n n n;
     wl o "inline_for_extraction noextract let accessor_%s_%s' : LL.accessor gaccessor_%s_%s' = synth_%s_inverse (); synth_%s_injective (); synth_%s_recip_inverse (); LL.accessor_synth %s'_parser synth_%s synth_%s_recip ()\n\n" n n n n n n n n n n;
    (* write the lenses *)
    List.iter
      (fun (fn, ty) ->
        wl i "noextract let clens_%s_%s : LL.clens %s %s = {\n" n fn n (compile_type ty);
        wl i "  LL.clens_cond = (fun _ -> True);\n";
        wl i "  LL.clens_get = (fun x -> x.%s);\n" fn;
        wl i "}\n\n";
      )
      fields;
    (* write the accessors *)
    List.iter
      (fun (fn, ty) ->
        wl i "val gaccessor_%s_%s : LL.gaccessor %s_parser %s clens_%s_%s\n\n" n fn n (pcombinator_name ty) n fn;
        wl o "let gaccessor_%s_%s = LL.gaccessor_ext (gaccessor_%s_%s' `LL.gaccessor_compose` gaccessor'_%s_%s) clens_%s_%s ()\n\n" n fn n n n fn n fn;
        wl i "val accessor_%s_%s : LL.accessor gaccessor_%s_%s\n\n" n fn n fn;
        wl o "let accessor_%s_%s = LL.accessor_ext (LL.accessor_compose accessor_%s_%s' accessor'_%s_%s) clens_%s_%s ()\n\n" n fn n n n fn n fn
      )
      fields;

    (* Pulse: accessors for fields *)
    let rec pulse_jumper_of_tree = function
       | TLeaf (_, ty) -> pulse_jumper_name ty
       | TNode (_, left, right) ->
          sprintf "(LPC.jump_nondep_then %s %s)" (pulse_jumper_of_tree left) (pulse_jumper_of_tree right)
    in
    let rec pulse_accessors (output: string) (path: string) = function
       | TLeaf (fn, ty) ->
          let output' = sprintf "%sinline_for_extraction noextract let accessor'_%s_%s : PPB.accessor %s'_parser %s _ = %s\n\n" output n fn n (pcombinator_name ty) path in
          output'
       | TNode (_, left, right) ->
          let left_jumper = pulse_jumper_of_tree left in
          let output1 = pulse_accessors output (sprintf "(PPC.accessor_then_fst %s %s () ())" path left_jumper) left in
          let output2 = pulse_accessors output1 (sprintf "(PPC.accessor_then_snd %s %s () ())" path left_jumper) right in
          output2
    in
    let pulse_acc = pulse_accessors "" (sprintf "(PPC.accessor_id %s'_parser)" n) tfields in
    wp o "%s" pulse_acc;
    wp o "noextract let clens_%s_%s' : LowParse.CLens.clens %s %s' = synth_%s_recip_inverse (); synth_%s_recip_injective (); { LowParse.CLens.clens_cond = (fun _ -> True); LowParse.CLens.clens_get = synth_%s_recip }\n\n" n n n n n n n;
    wp o "inline_for_extraction noextract let accessor_%s_%s' : PPB.accessor %s_parser %s'_parser clens_%s_%s' = synth_%s_inverse (); synth_%s_injective (); synth_%s_recip_inverse (); PPC.accessor_synth_inv synth_%s synth_%s_recip\n\n" n n n n n n n n n n n;
    List.iter
      (fun (fn, ty) ->
        wp i "noextract let clens_%s_%s : LowParse.CLens.clens %s %s = {\n" n fn n (compile_type ty);
        wp i "  LowParse.CLens.clens_cond = (fun _ -> True);\n";
        wp i "  LowParse.CLens.clens_get = (fun x -> x.%s);\n" fn;
        wp i "}\n\n";
        wp i "val accessor_%s_%s : PPB.accessor %s_parser %s clens_%s_%s\n\n" n fn n (pcombinator_name ty) n fn;
        wp o "let accessor_%s_%s = PPC.accessor_ext (PPC.accessor_compose accessor_%s_%s' accessor'_%s_%s ()) clens_%s_%s ()\n\n" n fn n n n fn n fn
      )
      fields;

  (* valid intro lemma *)
  let rec valid ((count, (precond_l, precond_r, postcond), body) as accu) = function
    | TLeaf (fn, ty) ->
       let p = pcombinator_name ty in
       let count' = count + 1 in
       let letpos' = sprintf "  let pos%d = LL.get_valid_pos %s h input pos%d in\n" count' p count in
       let precond_l' = sprintf "%s  LL.valid %s h input pos%d /\\ (\n%s" precond_l p count letpos' in
       let precond_r' = sprintf "%s)" precond_r in
       let postcond' = sprintf "%s  let %s = LL.contents %s h input pos%d in\n%s" postcond fn p count letpos' in
       ((count', (precond_l', precond_r', postcond'), body), p)
    | TNode (_, left, right) ->
       let (accu1, pleft) = valid accu left in
       let ((count', cond', body2), pright) = valid accu1 right in
       let body' = sprintf "%s  LL.valid_nondep_then_intro h %s %s input pos%d;\n" body2 pleft pright count in
       let p' = sprintf "(%s `LP.nondep_then` %s)" pleft pright in
       ((count', cond', body'), p')
  in
  let ((count, (precond_l, precond_r, postcond), body), _) = valid (0, ("", "", ""), "") tfields in
  wl i "val %s_valid (h:HS.mem) (#rrel: _) (#rel: _) (input:LL.slice rrel rel) (pos0:U32.t) : Lemma\n  (requires (\n" n;
  wl i "%s  True\n  %s))\n" precond_l precond_r;
  wl i "  (ensures (\n";
  wl i "%s" postcond;
  wl i "  LL.valid_content_pos %s_parser h input pos0 ({\n" n;
  List.iter
    (fun (fn, _) ->
      wl i "      %s = %s;\n" fn fn;
    )
    fields;
  wl i "    }) pos%d))\n\n" count;
  wl o "let %s_valid h #_ #_ input pos0 =\n%s%s" n postcond body;
  wl o "  assert_norm (%s' == LP.get_parser_type %s'_parser);\n" n n;
  wl o "  assert_norm (%s_parser_kind == %s'_parser_kind);\n" n n;
  wl o "  synth_%s_injective ();\n" n;
  wl o "  LL.valid_synth_intro h %s'_parser synth_%s input pos0\n\n" n n;
  ()

(* Rewrite {... uintX len; t value[len]; ...} into VectorVldata *)
and normalize_symboliclen tch sn (fl:struct_field_t list) : struct_field_t list =
  match fl with
  | [] -> []
  | (al, TypeSimple(tagt), tagn, VectorNone, None)
    :: (al', ty, n, VectorSymbolic k, None) :: r
    when tagn = k ->
      let h =
        match ty with
        | TypeSimple ty -> (al @ al', TypeSimple ty, n, VectorVldata tagt, None)
        | TypeIfeq (itag, cst, tc, tt, fc, tf) ->
          let et = sprintf "%s_%s_true" sn n in
          let ef = sprintf "%s_%s_false" sn n in
          let (o, i) = open_files et in
          let (o', i') = open_files ef in
          compile tch o i "" (Typedef (al', TypeSimple tt, et, VectorVldata tagt, None));
          compile tch o' i' "" (Typedef (al', TypeSimple tf, ef, VectorVldata tagt, None));
          (al @ al', TypeIfeq(itag, cst, tc, et, fc, ef), n, VectorNone, None)
        | TypeSelect (sel, cl, def) ->
          let r = ref [] in
          let cl' = List.map (fun (c,t)->
              let etyp = sprintf "%s_%s_%s" sn n c in
              r := (etyp, t) :: !r; (c, etyp)
            ) cl in
          let def' = match def with
            | None -> None
            | Some ty ->
              let etyp = sprintf "%s_%s_default" sn n in
              r := (etyp, ty) :: !r; Some etyp
            in
          List.iter (fun (etyp, t) ->
            let p = Typedef(al @ al', TypeSimple t, etyp, VectorVldata tagt, None) in
            let (o', i') = open_files etyp in
            compile tch o' i' "" p
          ) !r;
          (al @ al', TypeSelect(sel, cl', def'), n, VectorNone, None)
        in
      h :: (normalize_symboliclen tch sn r)
  | h :: t -> h :: (normalize_symboliclen tch sn t)

(* Hoist {... tag t; select(t){} ...} when other fields are present,
  also rewrites { ... tag t[x]; (if t = v then ttrue else tfalse) y ... *)
and normalize_select sn (fl:struct_field_t list)
  (acc:struct_field_t list) (acc':tag_select_t list) (acc'':ite_t list)
  : struct_field_t list * tag_select_t list * ite_t list =
  match fl with
  | [] -> List.rev acc, List.rev acc', List.rev acc''
  | (al, TypeSimple("opaque"), tagn, VectorFixed d, None)
    :: (al', TypeIfeq(tagn', tagv, tc, tt, fc, tf), ifn, vec, def)
    :: r when tagn = tagn' ->
    let etyp = sprintf "%s_%s" sn ifn in
    let ite : ite_t = (al, al', sn, ifn, tagn, d, tagv, tt, tf, tc, fc) in
    let f' = (al', TypeSimple etyp, ifn, vec, def) in
    normalize_select sn r (f'::acc) acc' (ite::acc'')
  | (al, TypeSimple(tagt), tagn, VectorNone, None)
    :: (al', TypeSelect (tagn', cases, def), seln, VectorNone, None)
    :: r when tagn = tagn' ->
    let etyp = sprintf "%s_%s" sn seln in
    let sel' = (al, al', etyp, tagn, seln, tagt, cases, def) in
    let f' = (al, TypeSimple etyp, seln, VectorNone, None) in
    normalize_select sn r (f'::acc) (sel'::acc') acc''
  | (_, TypeSelect (_, _, _), seln, _, _) :: t ->
    failwith (sprintf "Field %s contains an invalid select in struct %s" seln sn)
  | h :: t -> normalize_select sn t (h::acc) acc' acc''

(* Extract friend module names from struct fields (select tag types) *)
and extract_friends (fl: struct_field_t list) : string list =
  match fl with
  | [] -> []
  | (_, TypeSimple(tagt), tagn, VectorNone, None)
    :: (_, TypeSelect (tagn', _, _), _, VectorNone, None)
    :: r when tagn = tagn' ->
    (module_name tagt) :: extract_friends r
  | _ :: r -> extract_friends r

(* Global type Substitution, this is use for staging sums on implicit tags *)
and subst_of (x:typ) = try SM.find x !subst with _ -> x
and apply_subst_t (t:type_t) =
  match t with
  | TypeSimple(ty) -> TypeSimple(subst_of ty)
  | TypeIfeq(tag, v, tc, t, fc, f) -> TypeIfeq(tag, v, tc, subst_of t, fc, subst_of f)
  | TypeSelect(sel, cl, def) ->
    let cl' = List.map (fun (case, ty) -> case, subst_of ty) cl in
    let def' = match def with None -> None | Some ty -> Some (subst_of ty) in
    TypeSelect(sel, cl', def')
and apply_subst_field (al, ty, n, vec, def) = al, apply_subst_t ty, n, vec, def
and apply_subst (p:gemstone_t) =
  match p with
  | Abstract _ -> p
  | Enum _ -> p
  | Typedef tdef -> Typedef (apply_subst_field tdef)
  | Struct(al, fl, n) ->
    let fl' = List.map apply_subst_field fl in
    Struct(al, fl', n)

and compile tch o i (tn:typ) (p:gemstone_t) =
  let p = apply_subst p in
  let n = if tn = "" then tname true p else tn^"_"^(tname false p) in
  let mn = module_name n in
  let (fst, fsti) = !headers in

  (* Rewrite symbolic vldata before emitting headers, so needs_fstar_bytes sees normalized fields *)
  let p = match p with
    | Struct(al, fl, nn) -> Struct(al, normalize_symboliclen tch n fl, nn)
    | p -> p in

  (* Under -pulse, emit the FStar.Bytes module headers only for the rare modules
     that still reference FStar.Bytes (var-length byte types with bounded/wide
     length headers); all Seq-native modules stay FStar.Bytes-free. *)
  let needs_fstar_bytes = (not !emit_pulse) || gemstone_uses_fstar_bytes_pulse p in

  (* .fsti *)
  w i "module %s\n\n" mn;
  write_autogen i;
  if !types_from <> "" then w i "include %s\n\n" !types_from;
  if !types_to <> "" then w i "include %s\n\n" (module_of_filename !types_to);
  if needs_fstar_bytes then w i "open %s\n" !bytes;
  w i "module U8 = FStar.UInt8\n";
  w i "module U16 = FStar.UInt16\n";
  w i "module U32 = FStar.UInt32\n";
  w i "module U64 = FStar.UInt64\n";
  if !emit_pulse
  then w i "module LP = LowParse.Spec\n"
  else w i "module LP = LowParse.Spec.Base\n";
  wh i "module LS = LowParse.SLow.Base\n";
  wnp i "module LSZ = LowParse.SLow.Base\n";
  w i "module LPI = LowParse.Spec.AllIntegers\n";
  wl i "module LL = LowParse.Low.Base\n";
  w i "module L = FStar.List.Tot\n";
  wl i "module B = LowStar.Buffer\n";
  if needs_fstar_bytes then w i "module BY = FStar.Bytes\n";
  wl i "module HS = FStar.HyperStack\n";
  wl i "module HST = FStar.HyperStack.ST\n";
  wp i "module LPS = LowParse.Pulse.Base\n";
  wp i "module LT = LowParse.TacLib\n";
  wp i "module PPB = LowParse.PulseParse.Base\n";
  wp i "module PPC = LowParse.PulseParse.Combinators\n";
  wp i "module PPBY = LowParse.PulseParse.Bytes\n";
  wp i "module PPVD = LowParse.PulseParse.VLData\n";
  wp i "module PPAR = LowParse.PulseParse.Array\n";
  wp i "module PPVCL = LowParse.PulseParse.VCList\n";
  wp i "module LPC = LowParse.Pulse.Combinators\n";
  wp i "module LPPI = LowParse.Pulse.Int\n";
  wp i "module LPPILE = LowParse.Pulse.BoundedIntLE\n";
  wp i "module PPE = LowParse.PulseParse.Enum\n";
  wp i "module PPS = LowParse.PulseParse.Sum\n";
  wp i "module PPBI = LowParse.PulseParse.BoundedInt\n";
  wp i "module PPBILE = LowParse.PulseParse.BoundedIntLE\n";
  wp i "module PPBCVLI = LowParse.PulseParse.BCVLI\n";
  wp i "module PPVG = LowParse.PulseParse.VLGen\n";
  wp i "module PPDER = LowParse.Pulse.DER\n";
  wp i "module PPLS = LowParse.PulseParse.List\n";
  wp i "module PPFD = LowParse.PulseParse.FLData\n";
  wp i "module LPPS = LowParse.Pulse.Sum\n";
  wp i "module PPSL = LowParse.PulseParse.SizeLeaf\n";
  wp i "module LSeqB = LowParse.Pulse.SeqBytes\n";
  wp i "module LPITE = LowParse.PulseParse.IfThenElse\n";
  (List.iter (w i "%s\n") (List.rev fsti));
  w i "\n";

  (* .fst *)
  w o "module %s\n\n" mn;
  (match p with
   | Struct(_, fl, _) ->
     let friends = extract_friends fl in
     if friends <> [] then (List.iter (fun f -> w o "friend %s\n" f) friends; w o "\n")
   | _ -> ());
  write_autogen o;
  if needs_fstar_bytes then w o "open %s\n" !bytes;
  w o "module U8 = FStar.UInt8\n";
  w o "module U16 = FStar.UInt16\n";
  w o "module U32 = FStar.UInt32\n";
  w o "module U64 = FStar.UInt64\n";
  w o "module LP = LowParse.Spec\n";
  w o "module LT = LowParse.TacLib\n" ;
  wh o "module LS = LowParse.SLow\n";
  wnp o "module LSZ = LowParse.SLow\n";
  w o "module LPI = LowParse.Spec.AllIntegers\n";
  wl o "module LL = LowParse.Low\n";
	w o "module L = FStar.List.Tot\n";
  wl o "module B = LowStar.Buffer\n";
  if needs_fstar_bytes then w o "module BY = FStar.Bytes\n";
  wl o "module HS = FStar.HyperStack\n";
  wl o "module HST = FStar.HyperStack.ST\n";
  wp o "module LPS = LowParse.Pulse.Base\n";
  wp o "module LPC = LowParse.Pulse.Combinators\n";
  wp o "module LPPI = LowParse.Pulse.Int\n";
  wp o "module LPPILE = LowParse.Pulse.BoundedIntLE\n";
  wp o "module PPB = LowParse.PulseParse.Base\n";
  wp o "module PPC = LowParse.PulseParse.Combinators\n";
  wp o "module PPE = LowParse.PulseParse.Enum\n";
  wp o "module PPS = LowParse.PulseParse.Sum\n";
  wp o "module PPBI = LowParse.PulseParse.BoundedInt\n";
  wp o "module PPBILE = LowParse.PulseParse.BoundedIntLE\n";
  wp o "module PPBY = LowParse.PulseParse.Bytes\n";
  wp o "module PPBCVLI = LowParse.PulseParse.BCVLI\n";
  wp o "module PPVG = LowParse.PulseParse.VLGen\n";
  wp o "module PPVCL = LowParse.PulseParse.VCList\n";
  wp o "module PPDER = LowParse.Pulse.DER\n";
  wp o "module PPVD = LowParse.PulseParse.VLData\n";
  wp o "module PPLS = LowParse.PulseParse.List\n";
  wp o "module PPAR = LowParse.PulseParse.Array\n";
  wp o "module PPFD = LowParse.PulseParse.FLData\n";
  wp o "module LPPS = LowParse.Pulse.Sum\n";
  wp o "module PPSL = LowParse.PulseParse.SizeLeaf\n";
  wp o "module LSeqB = LowParse.Pulse.SeqBytes\n";
  wp o "module LPITE = LowParse.PulseParse.IfThenElse\n";
  (List.iter (w o "%s\n") (List.rev fst));
  w o "\n";

  let depl = getdep (tn = "") p in
  let depl = List.filter (fun x -> not (basic_type x)) depl in
  let depl = List.map module_name depl in
  (List.iter (fun dep ->
    if BatString.starts_with dep (mn^"_") then w i "include %s\n" dep
    else w i "open %s\n" dep) depl);
  w i "\n";

  let rlimit = 16 in
	w o "#reset-options \"--using_facts_from '* -FStar.Tactics -FStar.Reflection -Pulse -PulseCore' --z3rlimit %d --z3cliopt smt.arith.nl=false --max_fuel 2 --max_ifuel 2\"\n\n" rlimit;

  try let _ =
    match p with
    | Abstract (attrs, dn, min, max, n) ->
      compile_abstract tch o i n dn min max attrs
  	| Enum(al, fl, _) ->  compile_enum tch o i n fl al
    | Typedef(al, ty, n', vec, def) -> compile_typedef tch o i tn n' ty vec def al
    | Struct(al, fl, _) ->
      match normalize_select n fl [] [] [] with
      | [_, TypeSimple etyp', seln', VectorNone, None], [], [al, al', sn, ifn, tagn, d, tagv, tt, tf, tc, fc] ->
        compile_ite tch o i n sn ifn tagn d tagv tt tf tc fc al
      | [_, TypeSimple etyp', seln', VectorNone, None], [al, al', etyp, tagn, seln, tagt, cases, def], [] ->
        if etyp' <> etyp || seln' <> seln then failwith "Invalid rewrite of a select (QD bug)";
        compile_select tch o i n seln tagn tagt al cases def al'
      | fl, sell, itel ->
        List.iter (fun (al, al', etyp, tagn, seln, tagt, cases, def) ->
          let p = Struct([], [(al, TypeSimple(tagt), tagn, VectorNone, None);
            (al', TypeSelect (tagn, cases, def), seln, VectorNone, None)], etyp) in
          let (o', i') = open_files etyp in
          compile tch o' i' "" p;
          w i "(* Internal select() for %s *)\ninclude %s\n\n" etyp (module_name etyp);
          w o "(* Internal select() for %s *)\nopen %s\n\n" etyp (module_name etyp);
        ) sell;
        List.iter (fun (al, al', sn, ifn, tagn, d, tagv, tt, tf, tc, fc) ->
          let etyp = sprintf "%s_%s" sn ifn in
          let p = Struct([], [(al, TypeSimple("opaque"), tagn, VectorFixed d, None);
            (al', TypeIfeq(tagn, tagv, tc, tt, fc, tf), ifn, VectorNone, None)], etyp) in
          let (o', i') = open_files etyp in
          compile tch o' i' "" p;
          w i "include %s\n\n" (module_name etyp);
          w o "open %s\n\n" (module_name etyp);
        ) itel;
        match fl with
        | [] -> compile_typedef tch o i tn n (TypeSimple "Empty") VectorNone None al
        | [(al, ty, _, vec, def)] -> compile_typedef tch o i tn n ty vec def al
        | _ -> compile_struct tch o i n fl al
  in close_files o i with e -> close_files o i; raise e

let rfc_generate_fstar (p:Rfc_ast.prog) =
  let type_channel =
    if !types_to = ""
    then None
    else begin
      let c = open_out !types_to in
      w c "module %s\n" (module_of_filename !types_to);
      write_autogen c;
      w c "module U8 = FStar.UInt8\n";
      w c "module U16 = FStar.UInt16\n";
      w c "module U32 = FStar.UInt32\n";
      w c "module U64 = FStar.UInt64\n";
      Some c
    end
  in
  let aux (p:gemstone_t) =
    let (o, i) = open_files' p in
    compile type_channel o i "" p
  in
  List.iter aux p;
  match type_channel with
  | None -> ()
  | Some c -> close_out c
